import subprocess, sys
def r(args, inp, env=None):
    import os
    e=dict(os.environ); 
    if env: e.update(env)
    p=subprocess.run(["/tmp/../executable"] if False else ["./executable"]+args, input=inp.encode(), capture_output=True, env=e)
    return p.stdout.decode(), p.stderr.decode(), p.returncode
def show(expr,inp,extra=[]):
    o,e,c=r(extra+[expr],inp)
    print(f"$ yq {extra} {expr!r} <<< {inp!r}\n -> out={o!r} err={e!r} code={c}")
