		copy(p, c.Path)
		nc.Path = append(p, pathElem)
	}
	nc.IsKey = false
	nc.Pseudo = ""
	nc.Target = nil
	return nc
}

func cloneNode(n *yaml.Node) *yaml.Node {
	if n == nil {
		return nil
	}
	c := *n
	if n.Content != nil {
		c.Content = make([]*yaml.Node, len(n.Content))
		for i, ch := range n.Content {
