func parseIntValue(s string) (int64, string, error) {
	// Determine base like Go base 0
	v, err := strconv.ParseInt(strings.ReplaceAll(s, "_", ""), 0, 64)
	if err != nil {
		// Go ParseInt with base0 handles underscores; but we removed them, also handles 0o etc.
		// Try again raw
		v2, err2 := strconv.ParseInt(s, 0, 64)
		if err2 != nil {
			return 0, "", err // original error with original string? ParsInt error includes input
