		v = v2
	}
	// format spec
	format := ""
	lower := strings.ToLower(s)
	if strings.HasPrefix(lower, "0x") {
		format = "hex"
	} else if strings.HasPrefix(lower, "0o") {
		format = "oct0o"
	} else if strings.HasPrefix(lower, "0b") {
		format = "bin"
	} else if len(s) > 1 && s[0] == '0' && allDigits(s) {
		// old octal representation
		// Verify parsed value corresponds to octal interpretation: ParseInt base0 does that
		format = "oct"
	}
	return v, format, nil
}

func allDigits(s string) bool {
	for _, r := range s {
		if r < '0' || r > '9' {
			return false
		}
	}
	return len(s) > 0
}

func formatIntWithFormat(v int64, format string) string {
	switch format {
	case "hex":
		if v < 0 {
			// Go FormatInt for hex negative gives -?
			// yq likely... keep simple
			return "-0x" + strings.ToUpper(strconv.FormatInt(-v, 16))
		}
		return "0x" + strings.ToUpper(strconv.FormatInt(v, 16))
	case "oct0o":
		if v < 0 {
			return "-0o" + strconv.FormatInt(-v, 8)
		}
		return "0o" + strconv.FormatInt(v, 8)
	case "oct":
		return strconv.FormatInt(v, 8)
	case "bin":
		if v < 0 {
			return "-0b" + strconv.FormatInt(-v, 2)
		}
		return "0b" + strconv.FormatInt(v, 2)
	default:
		return strconv.FormatInt(v, 10)
	}
}

func parseFloatValue(s string) (float64, error) {
	// handle .inf etc manually?
	ls := strings.ToLower(s)
	switch ls {
	case ".inf", "+.inf", "inf", "+inf":
		return math.Inf(1), nil
	case "-.inf", "-inf":
		return math.Inf(-1), nil
	case ".nan", "nan":
		return math.NaN(), nil
	}
	return strconv.ParseFloat(strings.ReplaceAll(s, "_", ""), 64)
