func nodeToNum(n *yaml.Node) (numVal, error) {
	if n == nil {
		return numVal{}, fmt.Errorf("not a number")
	}
	if n.Kind == yaml.AliasNode && n.Alias != nil {
		return nodeToNum(n.Alias)
	}
	s := n.Value
	if n.Tag == "!!int" {
		v, format, err := parseIntValue(s)
		if err != nil {
			return numVal{}, err
		}
		_ = format
		return numVal{isInt: true, i: v, f: float64(v), valid: true}, nil
	}
	if n.Tag == "!!float" {
		f, err := parseFloatValue(s)
		if err != nil {
			return numVal{}, err
		}
		return numVal{isFloat: true, f: f, valid: true}, nil
	}
	return numVal{}, fmt.Errorf("not a number")
}

func formatFloat(f float64) string {
	if math.IsInf(f, 1) {
		return "+Inf"
	}
	if math.IsInf(f, -1) {
		return "-Inf"
	}
	if math.IsNaN(f) {
		return "NaN"
	}
	return strconv.FormatFloat(f, 'g', -1, 64)
