// Guess tag for a literal number string as yaml would
func guessNumberNode(s string) *yaml.Node {
	// Try int parse base0
	if _, _, err := parseIntValue(s); err == nil && !strings.ContainsAny(s, ".eE") {
		return scalarNode("!!int", s)
	}
	if _, err := parseFloatValue(s); err == nil {
		// Ensure it looks like float (contains . or e or is .inf/.nan)
		return scalarNode("!!float", s)
	}
	return scalarNode("!!int", s)
}

func deepEqualNode(a, b *yaml.Node) bool {
	if a == nil || b == nil {
		return a == b
	}
	if a.Kind == yaml.AliasNode && a.Alias != nil {
		a = a.Alias
	}
	if b.Kind == yaml.AliasNode && b.Alias != nil {
		b = b.Alias
	}
	if a.Kind != b.Kind {
		return false
	}
	if a.Kind == yaml.ScalarNode {
		// yq equality based on value string (?) and? For scalars compare value
		return a.Value == b.Value
	}
	if a.Kind == yaml.MappingNode {
		if len(a.Content) != len(b.Content) {
			return false
		}
		// unordered? map equality: need same keys values
		for i := 0; i < len(a.Content); i += 2 {
			ak := a.Content[i]
			av := a.Content[i+1]
			found := false
			for j := 0; j < len(b.Content); j += 2 {
				if b.Content[j].Value == ak.Value && deepEqualNode(av, b.Content[j+1]) {
					found = true
					break
				}
			}
			if !found {
				return false
			}
		}
		return true
	}
	if a.Kind == yaml.SequenceNode {
		if len(a.Content) != len(b.Content) {
			return false
		}
		for i := range a.Content {
			if !deepEqualNode(a.Content[i], b.Content[i]) {
				return false
			}
		}
		return true
	}
	return a.Value == b.Value
}

// compare nodes for sorting/equality comparisons: returns -1,0,1 and supported
func compareNodes(a, b *yaml.Node) (int, bool) {
	if a == nil || b == nil {
		return 0, false
	}
	if a.Kind == yaml.AliasNode && a.Alias != nil {
		a = a.Alias
	}
	if b.Kind == yaml.AliasNode && b.Alias != nil {
		b = b.Alias
	}
	// For sort: handle tag rank first if kinds differ?
	if a.Kind != b.Kind {
		// In sort, scalars come? Tests [1,"a"] -> 1 before a; rank by tag?
		ra := tagRank(a)
		rb := tagRank(b)
		if ra != rb {
			if ra < rb {
				return -1, true
			}
			return 1, true
		}
		return 0, true
	}
	if a.Kind == yaml.ScalarNode {
		// numeric comparison if both numbers of same tag family?
		if (a.Tag == "!!int" || a.Tag == "!!float") && (b.Tag == "!!int" || b.Tag == "!!float") {
			af, aerr := parseFloatValue(normaliseNumStr(a.Value))
			bf, berr := parseFloatValue(normaliseNumStr(b.Value))
			if aerr == nil && berr == nil {
				if af < bf {
					return -1, true
				} else if af > bf {
					return 1, true
				}
				return 0, true
			}
		}
		if a.Tag == "!!bool" && b.Tag == "!!bool" {
			if a.Value == b.Value {
				return 0, true
			}
			if a.Value == "false" {
				return -1, true
			}
			return 1, true
		}
		if a.Value < b.Value {
			return -1, true
		} else if a.Value > b.Value {
			return 1, true
		}
		return 0, true
	}
	// maps/seqs not comparable for sort (equal)
	return 0, true
}

func normaliseNumStr(s string) string {
	// For float parsing of ints like 0x10 etc, parse int first
	if v, _, err := parseIntValue(s); err == nil && !strings.ContainsAny(s, ".eE") {
		return strconv.FormatInt(v, 10)
	}
	return strings.ReplaceAll(s, "_", "")
}

func tagRank(n *yaml.Node) int {
	switch n.Tag {
	case "!!null":
		return 0
	case "!!bool":
		return 1
	case "!!int", "!!float":
		return 2
	case "!!str":
		return 3
	case "!!timestamp":
		return 4
	case "!!seq":
		return 5
	case "!!map":
		return 6
	}
	if n.Kind == yaml.SequenceNode {
		return 5
	}
	if n.Kind == yaml.MappingNode {
		return 6
	}
	return 3
}

func nodeStringValue(n *yaml.Node) string {
	if n == nil {
		return ""
	}
	if n.Kind == yaml.AliasNode {
		if n.Alias != nil {
			return nodeStringValue(n.Alias)
		}
		return n.Value
	}
	if n.Kind == yaml.ScalarNode {
		return n.Value
	}
	// For maps/seq, yaml representation (tostring)
	s, _ := encodeYAMLToString(n)
	return strings.TrimRight(s, "\n")
}

func pathToString(path []interface{}) string {
	var sb strings.Builder
	for _, p := range path {
		switch v := p.(type) {
		case string:
			sb.WriteString(v)
		case int:
			sb.WriteString(strconv.Itoa(v))
		case int64:
			sb.WriteString(strconv.FormatInt(v, 10))
		default:
			sb.WriteString(fmt.Sprintf("%v", v))
		}
	}
	return sb.String()
}

// string representation for error messages path like [obj] ??
func formatPath(path []interface{}) string {
	if len(path) == 0 {
		return ""
	}
	parts := make([]string, len(path))
	for i, p := range path {
		parts[i] = fmt.Sprintf("%v", p)
	}
	return strings.Join(parts, ".")
}
