	"env": true, "strenv": true, "now": true, "tz": true, "with_dtf": true,
	"eval": true, "load": true, "load_str": true, "system": true, "shell": false,
	"explode": true, "flatten": true, "any": true, "all": true, "not": true, "and": true, "or": true,
	"headComment": true, "footComment": true, "lineComment": true, "head_comment": true, "line_comment": true, "foot_comment": true,
	"error": true, "array_to_map": true, "object_to_map": false, "ref": true, "collect": true, "with": true, "filter": true,
	"root": true, "key": true, "first": true, "values": false,
	"toString": false,
	"@base64": true, "@base64d": true, "@csv": true, "@tsv": true, "@json": true, "@yaml": true, "@xml": true, "@props": true, "@text": false, "@uri": true, "@toml": false, "@sh": true,
	"true": true, "false": true, "null": true,
}

func longestKnownPrefix(s string) string {
	best := ""
	for k := range knownIdents {
		if strings.HasPrefix(s, k) && len(k) > len(best) && len(k) < len(s) {
			best = k
		}
	}
	// also check generic (?) 'as' etc are included
	return best
}

type lexer struct {
	src  string
	pos  int // byte index
	line int
	col  int // 1-indexed in runes(?) bytes
}

func (l *lexer) peek() (rune, int) {
	if l.pos >= len(l.src) {
		return 0, 0
	}
	r, sz := utf8.DecodeRuneInString(l.src[l.pos:])
	return r, sz
}
func (l *lexer) next() rune {
	r, sz := utf8.DecodeRuneInString(l.src[l.pos:])
	l.pos += sz
	if r == '\n' {
		l.line++
		l.col = 1
	} else {
		l.col++
	}
	return r
}
func (l *lexer) backupTo(pos, line, col int) { l.pos, l.line, l.col = pos, line, col }

func lexExpression(src string) ([]Token, error) {
	l := &lexer{src: src, line: 1, col: 1}
	var toks []Token
	// prev token kind for negative numbers etc handled in parser
	for l.pos < len(l.src) {
		r, _ := l.peek()
		if r == ' ' || r == '\t' || r == '\r' || r == '\n' {
			l.next()
			continue
		}
		startLine, startCol, startPos := l.line, l.col, l.pos
		// comment? # until end line when preceded by space? In expressions, yq may treat # as comment? Test later; treat as invalid if not?
		switch {
		case r == '.':
			// check ellipsis / dotdot / dot
			rest := l.src[l.pos:]
			if strings.HasPrefix(rest, "...") {
				// ensure not .... ?
				l.next(); l.next(); l.next()
				toks = append(toks, Token{Kind: TEllipsis, Value: "...", Line: startLine, Col: startCol})
				continue
			}
			if strings.HasPrefix(rest, "..") {
				l.next(); l.next()
				toks = append(toks, Token{Kind: TDotDot, Value: "..", Line: startLine, Col: startCol})
				continue
			}
			// single dot: might be number .5
			if len(rest) > 1 && rest[1] >= '0' && rest[1] <= '9' {
				// number .5 - but in path context ".5" after dot? Lexer alone ambiguous. Treat as number if previous token is operator/start
				// We'll emit number
				tok, err := l.lexNumber()
				if err != nil { return nil, err }
				toks = append(toks, tok)
				continue
			}
			l.next()
			toks = append(toks, Token{Kind: TDot, Value: ".", Line: startLine, Col: startCol})
			// After dot, if immediate identifier chars (no space), lex path key as TIdentPath
			// Check next rune: if it's letter/digit/_/$ or quote/bracket handled by parser (quote handled below as string following dot)
			// Path key chars: until delimiter
			if l.pos < len(l.src) {
				nr, _ := l.peek()
				if nr == '"' {
					// path with quoted key like ."key" - let parser handle string token next
					continue
				}
				if isPathKeyStart(nr) {
					// read path key
					start2Line, start2Col := l.line, l.col
					var sb strings.Builder
					for l.pos < len(l.src) {
						cr, _ := l.peek()
						if isPathKeyChar(cr) {
							sb.WriteRune(l.next())
						} else {
							break
						}
					}
					_ = start2Line; _ = start2Col
					toks = append(toks, Token{Kind: TIdentPath, Value: sb.String(), Line: startLine, Col: startCol})
					_ = startPos
					continue
				}
			}
			continue
		case r == '"':
			tok, err := l.lexString()
			if err != nil {
				return nil, err
			}
			toks = append(toks, tok)
			continue
		case r == '\'':
			return nil, &lexerError{Line: startLine, Col: startCol, Text: l.src[startPos:]}
			// entire remainder as in original: 'single' gives text "'single'" only? Actually original truncated remainder but we pass remainder, error formatter truncates to 16. For '.a + 'single'' remainder is "'single'" (till end) ok.
		case r == '$':
			l.next()
			// variable name
			var sb strings.Builder
			for l.pos < len(l.src) {
				cr, _ := l.peek()
				if cr == '_' || unicode.IsLetter(cr) || unicode.IsDigit(cr) {
					sb.WriteRune(l.next())
				} else {
					break
				}
			}
			if sb.Len() == 0 {
				return nil, &lexerError{Line: startLine, Col: startCol, Text: "$"}
			}
			toks = append(toks, Token{Kind: TVariable, Value: sb.String(), Line: startLine, Col: startCol})
			continue
		case r == '@':
			// @format
			l.next()
			var sb strings.Builder
			sb.WriteRune('@')
			for l.pos < len(l.src) {
				cr, _ := l.peek()
				if unicode.IsLetter(cr) || unicode.IsDigit(cr) {
					sb.WriteRune(l.next())
				} else {
					break
				}
			}
			name := sb.String()
			if !knownIdents[name] {
				// check prefix ?
				return nil, &lexerError{Line: startLine, Col: startCol, Text: l.src[startPos:]}
			}
			toks = append(toks, Token{Kind: TAt, Value: name, Line: startLine, Col: startCol})
			continue
		case isDigit(r):
			tok, err := l.lexNumber()
			if err != nil { return nil, err }
			toks = append(toks, tok)
			continue
		case r == '(':
			l.next(); toks = append(toks, Token{Kind: TLParen, Value: "(", Line: startLine, Col: startCol}); continue
		case r == ')':
			l.next(); toks = append(toks, Token{Kind: TRParen, Value: ")", Line: startLine, Col: startCol}); continue
		case r == '[':
			l.next(); toks = append(toks, Token{Kind: TLBracket, Value: "[", Line: startLine, Col: startCol}); continue
		case r == ']':
			l.next(); toks = append(toks, Token{Kind: TRBracket, Value: "]", Line: startLine, Col: startCol}); continue
		case r == '{':
			l.next(); toks = append(toks, Token{Kind: TLBrace, Value: "{", Line: startLine, Col: startCol}); continue
		case r == '}':
			l.next(); toks = append(toks, Token{Kind: TRBrace, Value: "}", Line: startLine, Col: startCol}); continue
		case r == ',':
			l.next(); toks = append(toks, Token{Kind: TComma, Value: ",", Line: startLine, Col: startCol}); continue
		case r == ';':
			l.next(); toks = append(toks, Token{Kind: TSemi, Value: ";", Line: startLine, Col: startCol}); continue
		case r == ':':
			l.next(); toks = append(toks, Token{Kind: TColon, Value: ":", Line: startLine, Col: startCol}); continue
		case r == '|':
			// check |=
			rest := l.src[l.pos:]
			if strings.HasPrefix(rest, "|=") {
				l.next(); l.next(); toks = append(toks, Token{Kind: TOp, Value: "|=", Line: startLine, Col: startCol}); continue
			}
			l.next(); toks = append(toks, Token{Kind: TPipe, Value: "|", Line: startLine, Col: startCol}); continue
		case r == '?':
			rest := l.src[l.pos:]
			if strings.HasPrefix(rest, "?//") {
				l.next(); l.next(); l.next(); toks = append(toks, Token{Kind: TOp, Value: "?//", Line: startLine, Col: startCol}); continue
			}
			l.next(); toks = append(toks, Token{Kind: TQuestion, Value: "?", Line: startLine, Col: startCol}); continue
		case r == '/':
			rest := l.src[l.pos:]
			if strings.HasPrefix(rest, "//") {
				l.next(); l.next(); toks = append(toks, Token{Kind: TOp, Value: "//", Line: startLine, Col: startCol}); continue
			}
			if strings.HasPrefix(rest, "/=") {
				l.next(); l.next(); toks = append(toks, Token{Kind: TOp, Value: "/=", Line: startLine, Col: startCol}); continue
			}
			l.next(); toks = append(toks, Token{Kind: TOp, Value: "/", Line: startLine, Col: startCol}); continue
		case r == '=':
			rest := l.src[l.pos:]
			if strings.HasPrefix(rest, "==") {
				l.next(); l.next(); toks = append(toks, Token{Kind: TOp, Value: "==", Line: startLine, Col: startCol}); continue
			}
			l.next(); toks = append(toks, Token{Kind: TOp, Value: "=", Line: startLine, Col: startCol}); continue
		case r == '!':
			rest := l.src[l.pos:]
			if strings.HasPrefix(rest, "!=") {
				l.next(); l.next(); toks = append(toks, Token{Kind: TOp, Value: "!=", Line: startLine, Col: startCol}); continue
			}
			return nil, &lexerError{Line: startLine, Col: startCol, Text: l.src[startPos:]}
		case r == '<':
			rest := l.src[l.pos:]
			if strings.HasPrefix(rest, "<=") {
				l.next(); l.next(); toks = append(toks, Token{Kind: TOp, Value: "<=", Line: startLine, Col: startCol}); continue
			}
			l.next(); toks = append(toks, Token{Kind: TOp, Value: "<", Line: startLine, Col: startCol}); continue
		case r == '>':
			rest := l.src[l.pos:]
			if strings.HasPrefix(rest, ">=") {
				l.next(); l.next(); toks = append(toks, Token{Kind: TOp, Value: ">=", Line: startLine, Col: startCol}); continue
			}
			l.next(); toks = append(toks, Token{Kind: TOp, Value: ">", Line: startLine, Col: startCol}); continue
		case r == '+':
			rest := l.src[l.pos:]
			if strings.HasPrefix(rest, "+=") {
				l.next(); l.next(); toks = append(toks, Token{Kind: TOp, Value: "+=", Line: startLine, Col: startCol}); continue
			}
			l.next(); toks = append(toks, Token{Kind: TOp, Value: "+", Line: startLine, Col: startCol}); continue
		case r == '-':
			rest := l.src[l.pos:]
			if strings.HasPrefix(rest, "-=") {
				l.next(); l.next(); toks = append(toks, Token{Kind: TOp, Value: "-=", Line: startLine, Col: startCol}); continue
			}
			// negative number if digit follows and (prev token is operator/start/paren/bracket/comma/semi/colon/pipe)
			if len(rest) > 1 && isDigit(rune(rest[1])) {
				// treat as number token including -
				tok, err := l.lexNumber()
				if err != nil { return nil, err }
				toks = append(toks, tok)
				continue
			}
			l.next(); toks = append(toks, Token{Kind: TOp, Value: "-", Line: startLine, Col: startCol}); continue
		case r == '*':
			rest := l.src[l.pos:]
			if strings.HasPrefix(rest, "*=") {
				l.next(); l.next(); toks = append(toks, Token{Kind: TOp, Value: "*=", Line: startLine, Col: startCol}); continue
			}
			l.next(); toks = append(toks, Token{Kind: TOp, Value: "*", Line: startLine, Col: startCol}); continue
		case r == '%':
			rest := l.src[l.pos:]
			if strings.HasPrefix(rest, "%=") {
				l.next(); l.next(); toks = append(toks, Token{Kind: TOp, Value: "%=", Line: startLine, Col: startCol}); continue
			}
			l.next(); toks = append(toks, Token{Kind: TOp, Value: "%", Line: startLine, Col: startCol}); continue
		case isIdentStart(r):
			// identifier word
			var sb strings.Builder
			for l.pos < len(l.src) {
				cr, _ := l.peek()
				if isIdentChar(cr) {
					sb.WriteRune(l.next())
				} else {
					break
				}
			}
			word := sb.String()
			if word == "~" {
				// handled elsewhere
			}
			// check known
			if known, ok := knownIdents[word]; ok && known {
				toks = append(toks, Token{Kind: TIdent, Value: word, Line: startLine, Col: startCol})
				continue
			}
			if word == "true" || word == "false" || word == "null" {
				toks = append(toks, Token{Kind: TIdent, Value: word, Line: startLine, Col: startCol})
				continue
			}
			// unknown identifier: find longest known prefix
			prefix := longestKnownPrefix(word)
			if prefix != "" {
				// error at col+len(prefix) with remainder + rest of source? Original shows remainder of entire input (truncated to 16)
				// Compute error text as remainder of source from that prefix position
				// Need position: startPos + len(prefix) (bytes, assume ascii)
				errPos := startPos + len(prefix)
				errLine := startLine
				errCol := startCol + len([]rune(prefix))
				// lines? identifier no newline
				_ = errLine
				return nil, &lexerError{Line: errLine, Col: errCol, Text: l.src[errPos:]}
			}
			return nil, &lexerError{Line: startLine, Col: startCol, Text: l.src[startPos:]}
		case r == '~':
			l.next(); toks = append(toks, Token{Kind: TIdent, Value: "~", Line: startLine, Col: startCol}); continue
		default:
			return nil, &lexerError{Line: startLine, Col: startCol, Text: l.src[startPos:]}
		}
	}
	toks = append(toks, Token{Kind: TEOF, Line: l.line, Col: l.col})
	return toks, nil
}

func isDigit(r rune) bool { return r >= '0' && r <= '9' }
func isIdentStart(r rune) bool { return r == '_' || unicode.IsLetter(r) }
func isIdentChar(r rune) bool { return r == '_' || unicode.IsLetter(r) || unicode.IsDigit(r) }
func isPathKeyStart(r rune) bool {
	return r == '_' || r == '$' || unicode.IsLetter(r) || unicode.IsDigit(r) || r == '-'
}
func isPathKeyChar(r rune) bool {
	if unicode.IsSpace(r) {
		return false
	}
	switch r {
	case '.', '[', ']', '|', '(', ')', '{', '}', ',', ';', ':', '?', '=', '<', '>', '+', '*', '/', '%', '"', '\'', '@':
		return false
	case '-':
		// hyphen included in key names: but minus operator with spaces? Path key reading is only immediate after dot, so include '-'
		return true
	}
	return true
}

func (l *lexer) lexNumber() (Token, error) {
	startLine, startCol := l.line, l.col
	var sb strings.Builder
	// optional minus
	if r, _ := l.peek(); r == '-' {
		sb.WriteRune(l.next())
	}
	// hex
	rest := l.src[l.pos:]
	if strings.HasPrefix(rest, "0x") || strings.HasPrefix(rest, "0X") {
		sb.WriteString(rest[:2])
		l.next(); l.next()
		for l.pos < len(l.src) {
			cr, _ := l.peek()
			if isDigit(cr) || (cr >= 'a' && cr <= 'f') || (cr >= 'A' && cr <= 'F') {
				sb.WriteRune(l.next())
			} else {
				break
			}
		}
		return Token{Kind: TNumber, Value: sb.String(), Line: startLine, Col: startCol}, nil
	}
	hasDot := false
	hasExp := false
	for l.pos < len(l.src) {
		cr, _ := l.peek()
		if isDigit(cr) {
			sb.WriteRune(l.next())
		} else if cr == '.' && !hasDot && !hasExp {
			// need lookahead digit? If dot followed by ??? path separation? Numbers in expression like "1."? allow
			// But check next char is digit to avoid consuming dot for traversal? In "1.foo" unlikely.
			// Lookahead
			if l.pos+1 < len(l.src) && isDigit(rune(l.src[l.pos+1])) {
				hasDot = true
				sb.WriteRune(l.next())
			} else {
				break
			}
		} else if (cr == 'e' || cr == 'E') && !hasExp {
			hasExp = true
			sb.WriteRune(l.next())
			// sign
			if nr, _ := l.peek(); nr == '+' || nr == '-' {
				sb.WriteRune(l.next())
			}
		} else {
			break
		}
	}
	// leading dot case (.5): initial char '.' handled: sb may start with '.'
	// lexNumber is called when '.'+digit, first char is '.' - need handle: The caller in dot case called lexNumber but l.pos at '.'.
	// Our loop above won't consume '.' at start because we checked minus only. Handle:
	// Actually caller dot case: we entered lexNumber with pos at '.'; loop sees '.' && !hasDot, lookahead digit, consumes. Good because peek '.' works.
	return Token{Kind: TNumber, Value: sb.String(), Line: startLine, Col: startCol}, nil
}

func (l *lexer) lexString() (Token, error) {
	startLine, startCol, startPos := l.line, l.col, l.pos
	// opening "
	l.next()
	var parts []StrPart
	var lit strings.Builder
	flushLit := func() {
		if lit.Len() > 0 {
			parts = append(parts, StrPart{IsExpr: false, Text: lit.String()})
			lit.Reset()
		}
	}
	for l.pos < len(l.src) {
		r := l.next()
		if r == '"' {
			flushLit()
			if len(parts) == 0 {
				parts = append(parts, StrPart{IsExpr: false, Text: ""})
			}
			return Token{Kind: TString, Value: "", Parts: parts, Line: startLine, Col: startCol}, nil
		}
		if r == '\\' {
			if l.pos >= len(l.src) {
				break
			}
			nr, _ := l.peek()
			if nr == '(' && opts_AllowInterpolation() {
				// interpolation
				flushLit()
				// consume '('
				l.next()
				exprStartLine, exprStartCol := l.line, l.col
				// find matching )
				depth := 1
				var exprSb strings.Builder
				inStr := false
				escaped := false
				for l.pos < len(l.src) && depth > 0 {
					cr := l.next()
					if inStr {
						exprSb.WriteRune(cr)
						if escaped {
							escaped = false
						} else if cr == '\\' {
							escaped = true
						} else if cr == '"' {
							inStr = false
						}
						continue
					}
					if cr == '"' {
						inStr = true
						exprSb.WriteRune(cr)
						continue
					}
					if cr == '(' {
						depth++
						exprSb.WriteRune(cr)
						continue
					}
					if cr == ')' {
						depth--
						if depth == 0 {
							break
						}
						exprSb.WriteRune(cr)
						continue
					}
					exprSb.WriteRune(cr)
				}
				if depth != 0 {
					return Token{}, &lexerError{Line: startLine, Col: startCol, Text: l.src[startPos:]}
				}
				parts = append(parts, StrPart{IsExpr: true, ExprSrc: exprSb.String(), Line: exprStartLine, Col: exprStartCol})
				continue
			}
			// escape sequences
			er := l.next()
			switch er {
			case 'n':
				lit.WriteRune('\n')
			case 't':
				lit.WriteRune('\t')
			case 'r':
				lit.WriteRune('\r')
			case 'b':
				lit.WriteRune('\b')
			case 'f':
				lit.WriteRune('\f')
			case '"':
				lit.WriteRune('"')
			case '\\':
				lit.WriteRune('\\')
			default:
				// keep as backslash + char (matches yq for \u, \/, \x)
				lit.WriteRune('\\')
				lit.WriteRune(er)
			}
			continue
		}
		lit.WriteRune(r)
	}
	return Token{}, &lexerError{Line: startLine, Col: startCol, Text: l.src[startPos:]}
}

// global flag checked via opts (set in main before parsing)
func opts_AllowInterpolation() bool {
	if globalOpts != nil {
		return globalOpts.StringInterp
	}
	return true
}
EOF
"}

