{"command":"cat > lexer.go <<'EOF'
package main

import (
	"fmt"
	"strings"
	"unicode"
	"unicode/utf8"
)

type TokenKind int

const (
	TEOF TokenKind = iota
	TDot        // .
	TDotDot     // ..
	TEllipsis   // ...
	TPath       // a path segment following dot? We'll handle in parser via TDotDot etc. Instead lex path as single?
	// Actually design: lexer emits TDot then TIdentPath as path key, parser combines
	TIdentPath // path key after dot (value string)
	TNumber
	TString // raw segments computed later: value includes StringParts
	TVariable // $name (value name)
	TIdent    // function/operator name
	TOp       // operator string value
	TLParen
	TRParen
	TLBracket
	TRBracket
	TLBrace
	TRBrace
	TComma
	TSemi
	TColon
	TPipe
	TQuestion
	TAt // @xxx value
)

type StrPart struct {
	IsExpr bool
	Text   string // literal text (already unescaped) if not expr
	ExprSrc string // source if expr
	Line   int
	Col    int
}

type Token struct {
	Kind  TokenKind
	Value string
	Line  int
	Col   int
	// for string
	Parts []StrPart
	Raw   string // raw literal for numbers
}

func (t Token) String() string {
	return fmt.Sprintf("%v %q @%d:%d", t.Kind, t.Value, t.Line, t.Col)
}

type lexerError struct {
	Line int
	Col  int
	Text string
}

func (e *lexerError) Error() string {
	txt := e.Text
	// truncate to 16 chars (bytes? runes) plus ...
	runes := []rune(txt)
	if len(runes) > 16 {
		txt = string(runes[:16]) + "..."
	}
	return fmt.Sprintf("%d:%d: lexer: invalid input text %q", e.Line, e.Col, txt)
}

var knownIdents = map[string]bool{
	"as": true, "ireduce": true,
	"select": true, "map": true, "map_values": true, "sort": true, "sort_by": true, "sort_keys": true,
	"group_by": true, "unique": true, "unique_by": true, "reverse": true, "shuffle": true,
	"min": true, "max": true, "length": true, "keys": true, "has": true, "contains": true,
	"type": true, "tag": true, "style": true, "anchor": true, "alias": true, "kind": true,
	"line": true, "column": true, "fileIndex": true, "fi": true, "fileName": true, "filename": true, "file_name": true,
	"documentIndex": true, "document_index": true, "di": true,
