func longestKnownPrefix(s string) string {
	best := ""
	for k := range knownIdents {
		if strings.HasPrefix(s, k) && len(k) > len(best) && len(k) < len(s) {
			best = k
		}
	}
	// also check generic (?) 'as' etc are included
	return best
}

type lexer struct {
	src  string
	pos  int // byte index
	line int
	col  int // 1-indexed in runes(?) bytes
}

func (l *lexer) peek() (rune, int) {
	if l.pos >= len(l.src) {
		return 0, 0
	}
	r, sz := utf8.DecodeRuneInString(l.src[l.pos:])
	return r, sz
}
func (l *lexer) next() rune {
	r, sz := utf8.DecodeRuneInString(l.src[l.pos:])
	l.pos += sz
	if r == '\n' {
		l.line++
		l.col = 1
	} else {
		l.col++
	}
	return r
}
func (l *lexer) backupTo(pos, line, col int) { l.pos, l.line, l.col = pos, line, col }

func lexExpression(src string) ([]Token, error) {
	l := &lexer{src: src, line: 1, col: 1}
	var toks []Token
	// prev token kind for negative numbers etc handled in parser
	for l.pos < len(l.src) {
		r, _ := l.peek()
		if r == ' ' || r == '\t' || r == '\r' || r == '\n' {
			l.next()
			continue
		}
		startLine, startCol, startPos := l.line, l.col, l.pos
		// comment? # until end line when preceded by space? In expressions, yq may treat # as comment? Test later; treat as invalid if not?
		switch {
		case r == '.':
			// check ellipsis / dotdot / dot
			rest := l.src[l.pos:]
			if strings.HasPrefix(rest, "...") {
				// ensure not .... ?
				l.next(); l.next(); l.next()
				toks = append(toks, Token{Kind: TEllipsis, Value: "...", Line: startLine, Col: startCol})
				continue
			}
			if strings.HasPrefix(rest, "..") {
				l.next(); l.next()
				toks = append(toks, Token{Kind: TDotDot, Value: "..", Line: startLine, Col: startCol})
				continue
			}
			// single dot: might be number .5
			if len(rest) > 1 && rest[1] >= '0' && rest[1] <= '9' {
				// number .5 - but in path context ".5" after dot? Lexer alone ambiguous. Treat as number if previous token is operator/start
				// We'll emit number
