			// Check next rune: if it's letter/digit/_/$ or quote/bracket handled by parser (quote handled below as string following dot)
			// Path key chars: until delimiter
			if l.pos < len(l.src) {
				nr, _ := l.peek()
				if nr == '"' {
					// path with quoted key like ."key" - let parser handle string token next
					continue
				}
				if isPathKeyStart(nr) {
					// read path key
					start2Line, start2Col := l.line, l.col
					var sb strings.Builder
					for l.pos < len(l.src) {
						cr, _ := l.peek()
						if isPathKeyChar(cr) {
							sb.WriteRune(l.next())
						} else {
							break
						}
					}
					_ = start2Line; _ = start2Col
					toks = append(toks, Token{Kind: TIdentPath, Value: sb.String(), Line: startLine, Col: startCol})
					_ = startPos
					continue
				}
			}
			continue
		case r == '"':
			tok, err := l.lexString()
			if err != nil {
				return nil, err
			}
			toks = append(toks, tok)
			continue
		case r == '\'':
			return nil, &lexerError{Line: startLine, Col: startCol, Text: l.src[startPos:]}
			// entire remainder as in original: 'single' gives text "'single'" only? Actually original truncated remainder but we pass remainder, error formatter truncates to 16. For '.a + 'single'' remainder is "'single'" (till end) ok.
		case r == '$':
			l.next()
			// variable name
			var sb strings.Builder
			for l.pos < len(l.src) {
				cr, _ := l.peek()
				if cr == '_' || unicode.IsLetter(cr) || unicode.IsDigit(cr) {
					sb.WriteRune(l.next())
				} else {
					break
				}
			}
			if sb.Len() == 0 {
				return nil, &lexerError{Line: startLine, Col: startCol, Text: "$"}
			}
			toks = append(toks, Token{Kind: TVariable, Value: sb.String(), Line: startLine, Col: startCol})
			continue
		case r == '@':
			// @format
			l.next()
			var sb strings.Builder
			sb.WriteRune('@')
			for l.pos < len(l.src) {
				cr, _ := l.peek()
				if unicode.IsLetter(cr) || unicode.IsDigit(cr) {
					sb.WriteRune(l.next())
				} else {
					break
				}
			}
			name := sb.String()
