			}
			toks = append(toks, Token{Kind: TAt, Value: name, Line: startLine, Col: startCol})
			continue
		case isDigit(r):
			tok, err := l.lexNumber()
			if err != nil { return nil, err }
			toks = append(toks, tok)
			continue
		case r == '(':
			l.next(); toks = append(toks, Token{Kind: TLParen, Value: "(", Line: startLine, Col: startCol}); continue
		case r == ')':
			l.next(); toks = append(toks, Token{Kind: TRParen, Value: ")", Line: startLine, Col: startCol}); continue
		case r == '[':
			l.next(); toks = append(toks, Token{Kind: TLBracket, Value: "[", Line: startLine, Col: startCol}); continue
		case r == ']':
			l.next(); toks = append(toks, Token{Kind: TRBracket, Value: "]", Line: startLine, Col: startCol}); continue
		case r == '{':
			l.next(); toks = append(toks, Token{Kind: TLBrace, Value: "{", Line: startLine, Col: startCol}); continue
		case r == '}':
			l.next(); toks = append(toks, Token{Kind: TRBrace, Value: "}", Line: startLine, Col: startCol}); continue
		case r == ',':
			l.next(); toks = append(toks, Token{Kind: TComma, Value: ",", Line: startLine, Col: startCol}); continue
		case r == ';':
			l.next(); toks = append(toks, Token{Kind: TSemi, Value: ";", Line: startLine, Col: startCol}); continue
		case r == ':':
			l.next(); toks = append(toks, Token{Kind: TColon, Value: ":", Line: startLine, Col: startCol}); continue
		case r == '|':
			// check |=
			rest := l.src[l.pos:]
			if strings.HasPrefix(rest, "|=") {
				l.next(); l.next(); toks = append(toks, Token{Kind: TOp, Value: "|=", Line: startLine, Col: startCol}); continue
			}
			l.next(); toks = append(toks, Token{Kind: TPipe, Value: "|", Line: startLine, Col: startCol}); continue
		case r == '?':
			rest := l.src[l.pos:]
			if strings.HasPrefix(rest, "?//") {
				l.next(); l.next(); l.next(); toks = append(toks, Token{Kind: TOp, Value: "?//", Line: startLine, Col: startCol}); continue
			}
			l.next(); toks = append(toks, Token{Kind: TQuestion, Value: "?", Line: startLine, Col: startCol}); continue
		case r == '/':
			rest := l.src[l.pos:]
			if strings.HasPrefix(rest, "//") {
				l.next(); l.next(); toks = append(toks, Token{Kind: TOp, Value: "//", Line: startLine, Col: startCol}); continue
			}
			if strings.HasPrefix(rest, "/=") {
				l.next(); l.next(); toks = append(toks, Token{Kind: TOp, Value: "/=", Line: startLine, Col: startCol}); continue
			}
			l.next(); toks = append(toks, Token{Kind: TOp, Value: "/", Line: startLine, Col: startCol}); continue
		case r == '=':
			rest := l.src[l.pos:]
			if strings.HasPrefix(rest, "==") {
				l.next(); l.next(); toks = append(toks, Token{Kind: TOp, Value: "==", Line: startLine, Col: startCol}); continue
			}
			l.next(); toks = append(toks, Token{Kind: TOp, Value: "=", Line: startLine, Col: startCol}); continue
		case r == '!':
			rest := l.src[l.pos:]
			if strings.HasPrefix(rest, "!=") {
				l.next(); l.next(); toks = append(toks, Token{Kind: TOp, Value: "!=", Line: startLine, Col: startCol}); continue
			}
			return nil, &lexerError{Line: startLine, Col: startCol, Text: l.src[startPos:]}
		case r == '<':
			rest := l.src[l.pos:]
			if strings.HasPrefix(rest, "<=") {
				l.next(); l.next(); toks = append(toks, Token{Kind: TOp, Value: "<=", Line: startLine, Col: startCol}); continue
			}
			l.next(); toks = append(toks, Token{Kind: TOp, Value: "<", Line: startLine, Col: startCol}); continue
		case r == '>':
			rest := l.src[l.pos:]
			if strings.HasPrefix(rest, ">=") {
				l.next(); l.next(); toks = append(toks, Token{Kind: TOp, Value: ">=", Line: startLine, Col: startCol}); continue
			}
			l.next(); toks = append(toks, Token{Kind: TOp, Value: ">", Line: startLine, Col: startCol}); continue
		case r == '+':
			rest := l.src[l.pos:]
			if strings.HasPrefix(rest, "+=") {
				l.next(); l.next(); toks = append(toks, Token{Kind: TOp, Value: "+=", Line: startLine, Col: startCol}); continue
			}
			l.next(); toks = append(toks, Token{Kind: TOp, Value: "+", Line: startLine, Col: startCol}); continue
		case r == '-':
			rest := l.src[l.pos:]
			if strings.HasPrefix(rest, "-=") {
				l.next(); l.next(); toks = append(toks, Token{Kind: TOp, Value: "-=", Line: startLine, Col: startCol}); continue
			}
			// negative number if digit follows and (prev token is operator/start/paren/bracket/comma/semi/colon/pipe)
			if len(rest) > 1 && isDigit(rune(rest[1])) {
				// treat as number token including -
				tok, err := l.lexNumber()
				if err != nil { return nil, err }
				toks = append(toks, tok)
				continue
			}
			l.next(); toks = append(toks, Token{Kind: TOp, Value: "-", Line: startLine, Col: startCol}); continue
		case r == '*':
			rest := l.src[l.pos:]
			if strings.HasPrefix(rest, "*=") {
				l.next(); l.next(); toks = append(toks, Token{Kind: TOp, Value: "*=", Line: startLine, Col: startCol}); continue
			}
			l.next(); toks = append(toks, Token{Kind: TOp, Value: "*", Line: startLine, Col: startCol}); continue
		case r == '%':
			rest := l.src[l.pos:]
			if strings.HasPrefix(rest, "%=") {
				l.next(); l.next(); toks = append(toks, Token{Kind: TOp, Value: "%=", Line: startLine, Col: startCol}); continue
			}
			l.next(); toks = append(toks, Token{Kind: TOp, Value: "%", Line: startLine, Col: startCol}); continue
		case isIdentStart(r):
			// identifier word
			var sb strings.Builder
			for l.pos < len(l.src) {
				cr, _ := l.peek()
				if isIdentChar(cr) {
					sb.WriteRune(l.next())
				} else {
					break
				}
			}
			word := sb.String()
			if word == "~" {
				// handled elsewhere
			}
			// check known
			if known, ok := knownIdents[word]; ok && known {
				toks = append(toks, Token{Kind: TIdent, Value: word, Line: startLine, Col: startCol})
				continue
			}
			if word == "true" || word == "false" || word == "null" {
				toks = append(toks, Token{Kind: TIdent, Value: word, Line: startLine, Col: startCol})
				continue
			}
			// unknown identifier: find longest known prefix
			prefix := longestKnownPrefix(word)
			if prefix != "" {
				// error at col+len(prefix) with remainder + rest of source? Original shows remainder of entire input (truncated to 16)
				// Compute error text as remainder of source from that prefix position
				// Need position: startPos + len(prefix) (bytes, assume ascii)
				errPos := startPos + len(prefix)
				errLine := startLine
				errCol := startCol + len([]rune(prefix))
				// lines? identifier no newline
				_ = errLine
				return nil, &lexerError{Line: errLine, Col: errCol, Text: l.src[errPos:]}
			}
			return nil, &lexerError{Line: startLine, Col: startCol, Text: l.src[startPos:]}
		case r == '~':
			l.next(); toks = append(toks, Token{Kind: TIdent, Value: "~", Line: startLine, Col: startCol}); continue
		default:
			return nil, &lexerError{Line: startLine, Col: startCol, Text: l.src[startPos:]}
		}
	}
	toks = append(toks, Token{Kind: TEOF, Line: l.line, Col: l.col})
	return toks, nil
}

func isDigit(r rune) bool { return r >= '0' && r <= '9' }
func isIdentStart(r rune) bool { return r == '_' || unicode.IsLetter(r) }
func isIdentChar(r rune) bool { return r == '_' || unicode.IsLetter(r) || unicode.IsDigit(r) }
func isPathKeyStart(r rune) bool {
	return r == '_' || r == '$' || unicode.IsLetter(r) || unicode.IsDigit(r) || r == '-'
}
func isPathKeyChar(r rune) bool {
	if unicode.IsSpace(r) {
		return false
	}
	switch r {
	case '.', '[', ']', '|', '(', ')', '{', '}', ',', ';', ':', '?', '=', '<', '>', '+', '*', '/', '%', '"', '\'', '@':
		return false
	case '-':
		// hyphen included in key names: but minus operator with spaces? Path key reading is only immediate after dot, so include '-'
		return true
	}
	return true
}

func (l *lexer) lexNumber() (Token, error) {
	startLine, startCol := l.line, l.col
	var sb strings.Builder
	// optional minus
	if r, _ := l.peek(); r == '-' {
		sb.WriteRune(l.next())
	}
	// hex
	rest := l.src[l.pos:]
	if strings.HasPrefix(rest, "0x") || strings.HasPrefix(rest, "0X") {
		sb.WriteString(rest[:2])
		l.next(); l.next()
		for l.pos < len(l.src) {
			cr, _ := l.peek()
			if isDigit(cr) || (cr >= 'a' && cr <= 'f') || (cr >= 'A' && cr <= 'F') {
				sb.WriteRune(l.next())
			} else {
				break
			}
		}
		return Token{Kind: TNumber, Value: sb.String(), Line: startLine, Col: startCol}, nil
	}
	hasDot := false
	hasExp := false
	for l.pos < len(l.src) {
		cr, _ := l.peek()
		if isDigit(cr) {
			sb.WriteRune(l.next())
		} else if cr == '.' && !hasDot && !hasExp {
			// need lookahead digit? If dot followed by ??? path separation? Numbers in expression like "1."? allow
			// But check next char is digit to avoid consuming dot for traversal? In "1.foo" unlikely.
			// Lookahead
			if l.pos+1 < len(l.src) && isDigit(rune(l.src[l.pos+1])) {
				hasDot = true
				sb.WriteRune(l.next())
			} else {
				break
			}
		} else if (cr == 'e' || cr == 'E') && !hasExp {
			hasExp = true
			sb.WriteRune(l.next())
			// sign
			if nr, _ := l.peek(); nr == '+' || nr == '-' {
				sb.WriteRune(l.next())
			}
		} else {
			break
		}
	}
	// leading dot case (.5): initial char '.' handled: sb may start with '.'
	// lexNumber is called when '.'+digit, first char is '.' - need handle: The caller in dot case called lexNumber but l.pos at '.'.
	// Our loop above won't consume '.' at start because we checked minus only. Handle:
	// Actually caller dot case: we entered lexNumber with pos at '.'; loop sees '.' && !hasDot, lookahead digit, consumes. Good because peek '.' works.
	return Token{Kind: TNumber, Value: sb.String(), Line: startLine, Col: startCol}, nil
}

func (l *lexer) lexString() (Token, error) {
	startLine, startCol, startPos := l.line, l.col, l.pos
	// opening "
	l.next()
	var parts []StrPart
	var lit strings.Builder
	flushLit := func() {
		if lit.Len() > 0 {
			parts = append(parts, StrPart{IsExpr: false, Text: lit.String()})
			lit.Reset()
		}
	}
	for l.pos < len(l.src) {
		r := l.next()
		if r == '"' {
			flushLit()
			if len(parts) == 0 {
				parts = append(parts, StrPart{IsExpr: false, Text: ""})
			}
			return Token{Kind: TString, Value: "", Parts: parts, Line: startLine, Col: startCol}, nil
		}
		if r == '\\' {
			if l.pos >= len(l.src) {
				break
			}
			nr, _ := l.peek()
			if nr == '(' && opts_AllowInterpolation() {
				// interpolation
				flushLit()
				// consume '('
				l.next()
				exprStartLine, exprStartCol := l.line, l.col
				// find matching )
				depth := 1
				var exprSb strings.Builder
				inStr := false
				escaped := false
				for l.pos < len(l.src) && depth > 0 {
					cr := l.next()
					if inStr {
						exprSb.WriteRune(cr)
						if escaped {
							escaped = false
						} else if cr == '\\' {
							escaped = true
						} else if cr == '"' {
							inStr = false
						}
						continue
					}
					if cr == '"' {
						inStr = true
						exprSb.WriteRune(cr)
						continue
					}
					if cr == '(' {
						depth++
						exprSb.WriteRune(cr)
						continue
					}
					if cr == ')' {
						depth--
						if depth == 0 {
							break
						}
						exprSb.WriteRune(cr)
						continue
					}
					exprSb.WriteRune(cr)
				}
				if depth != 0 {
					return Token{}, &lexerError{Line: startLine, Col: startCol, Text: l.src[startPos:]}
				}
				parts = append(parts, StrPart{IsExpr: true, ExprSrc: exprSb.String(), Line: exprStartLine, Col: exprStartCol})
				continue
			}
			// escape sequences
			er := l.next()
			switch er {
			case 'n':
				lit.WriteRune('\n')
			case 't':
				lit.WriteRune('\t')
			case 'r':
				lit.WriteRune('\r')
			case 'b':
				lit.WriteRune('\b')
			case 'f':
				lit.WriteRune('\f')
			case '"':
				lit.WriteRune('"')
			case '\\':
				lit.WriteRune('\\')
			default:
				// keep as backslash + char (matches yq for \u, \/, \x)
				lit.WriteRune('\\')
				lit.WriteRune(er)
			}
			continue
		}
		lit.WriteRune(r)
	}
	return Token{}, &lexerError{Line: startLine, Col: startCol, Text: l.src[startPos:]}
}

// global flag checked via opts (set in main before parsing)
func opts_AllowInterpolation() bool {
	if globalOpts != nil {
		return globalOpts.StringInterp
	}
	return true
}
