package main

import (
	"fmt"
	"strings"

	"gopkg.in/yaml.v3"
)

type ASTKind int

const (
	AKRoot ASTKind = iota
	AKPath
	AKLiteral
	AKString
	AKVariable
	AKBinary
	AKPipe
	AKUnion
	AKAssign
	AKVarAssign
	AKReduce
	AKCollect
	AKCreateMap
	AKFunc
	AKSuffix // apply steps to base
)

type PathStep struct {
	Type     string // self,key,dyn,slice,iterate,recursive,ellipsis
	Key      string
	KeyNode  *yaml.Node // static literal key/index node if any
	KeyExpr  *AST
	FromExpr *AST
	ToExpr   *AST
	HasFrom  bool
	HasTo    bool
}

type MapEntry struct {
	Key *AST
	Val *AST // nil if no colon
}

type AST struct {
	Kind  ASTKind
	Steps []PathStep // for AKPath
	Node  *yaml.Node // literal
	Parts []StrPart  // string literal/interp (parsed exprs below)
	PartExprs []*AST // parallel to Parts where IsExpr
	VarName string
	Op    string
	L, R  *AST
	// var assign
	Source *AST
	Body   *AST
	Init   *AST
	Update *AST
	// collect
	Inner *AST
	// create map
	Entries []MapEntry
	// func
	Name string
	Args []*AST
	// suffix
	Base *AST
	// path optional
	Optional bool
	// string plain value if Parts simple
	StrVal string
	HasInterp bool
}

type parser struct {
	toks []Token
	pos  int
	src  string
}

func (p *parser) peek() Token { return p.toks[p.pos] }
func (p *parser) next() Token { t := p.toks[p.pos]; if p.pos < len(p.toks)-1 { p.pos++ }; return t }
func (p *parser) expect(k TokenKind) (Token, error) {
	t := p.peek()
	if t.Kind != k {
		return t, fmt.Errorf("bad expression, please check expression syntax")
	}
	return p.next(), nil
}
func (p *parser) matchOp(v string) bool {
	t := p.peek()
	return t.Kind == TOp && t.Value == v
}
func (p *parser) matchKind(k TokenKind) bool { return p.peek().Kind == k }

func parseExpressionString(src string) (*AST, error) {
	toks, err := lexExpression(src)
	if err != nil {
		return nil, err
	}
	p := &parser{toks: toks, src: src}
	ast, err := p.parsePipe()
	if err != nil {
		return nil, err
	}
	if p.peek().Kind != TEOF {
		// leftover token -> bad syntax
		// check unknown ident tokens
		if p.peek().Kind == TUnknownIdent {
			return nil, unknownIdentError(p.peek())
		}
		return nil, fmt.Errorf("bad expression, please check expression syntax")
	}
	return ast, nil
}

func unknownIdentError(t Token) error {
	// mimic lexer error
	word := t.Value
	if isKnownFalse(word) {
		return &lexerError{Line: t.Line, Col: t.Col, Text: t.RawRemainder}
	}
	if prefix := longestKnownPrefix(word); prefix != "" {
		// remainder starts after prefix in RawRemainder: RawRemainder is src from token start
		rem := t.RawRemainder
		if len(rem) >= len(prefix) {
			rem = rem[len(prefix):]
		}
		return &lexerError{Line: t.Line, Col: t.Col + len([]rune(prefix)), Text: rem}
	}
	return &lexerError{Line: t.Line, Col: t.Col, Text: t.RawRemainder}
}

func isKnownFalse(w string) bool {
	v, ok := knownIdents[w]
	return ok && !v
}

// parsePipe is top level
func (p *parser) parsePipe() (*AST, error) {
	left, err := p.parseComma()
	if err != nil {
		return nil, err
	}
	// as binding
	if p.peek().Kind == TIdent && p.peek().Value == "as" {
		p.next() // as
		vt := p.next()
		if vt.Kind != TVariable {
			return nil, fmt.Errorf("bad expression, please check expression syntax")
		}
		varName := vt.Value
		// ireduce
		if p.peek().Kind == TIdent && p.peek().Value == "ireduce" {
			p.next()
			if _, err := p.expect(TLParen); err != nil { return nil, err }
			init, err := p.parsePipe()
			if err != nil { return nil, err }
			if _, err := p.expect(TSemi); err != nil { return nil, err }
			update, err := p.parsePipe()
			if err != nil { return nil, err }
			if _, err := p.expect(TRParen); err != nil { return nil, err }
			reduceNode := &AST{Kind: AKReduce, Source: left, VarName: varName, Init: init, Update: update}
			// possible pipe after reduce
			if p.peek().Kind == TPipe {
				p.next()
				body, err := p.parsePipe()
				if err != nil { return nil, err }
				return &AST{Kind: AKPipe, L: reduceNode, R: body}, nil
			}
			return reduceNode, nil
		}
		// expect pipe
		if p.peek().Kind != TPipe {
			return nil, fmt.Errorf("must use variable with a pipe, e.g. `exp as $x | ...`")
		}
		p.next()
		body, err := p.parsePipe()
		if err != nil { return nil, err }
		return &AST{Kind: AKVarAssign, Source: left, VarName: varName, Body: body}, nil
	}
	if p.peek().Kind == TPipe {
		p.next()
		right, err := p.parsePipe()
		if err != nil { return nil, err }
		return &AST{Kind: AKPipe, L: left, R: right}, nil
	}
	return left, nil
}

func (p *parser) parseComma() (*AST, error) {
	left, err := p.parseAssign()
	if err != nil { return nil, err }
	for p.peek().Kind == TComma {
		p.next()
		// check trailing comma case: if next is } or ] or ) etc, original generates ',' expects 2 args...
		if p.peek().Kind == TRBrace || p.peek().Kind == TRBracket || p.peek().Kind == TRParen || p.peek().Kind == TEOF {
			return nil, fmt.Errorf("',' expects 2 args but there is 1")
		}
		right, err := p.parseAssign()
		if err != nil { return nil, err }
		left = &AST{Kind: AKUnion, L: left, R: right}
	}
	return left, nil
}

func (p *parser) parseAssign() (*AST, error) {
	left, err := p.parseAlternative()
	if err != nil { return nil, err }
	if p.peek().Kind == TOp {
		op := p.peek().Value
		if op == "=" || op == "|=" || op == "+=" || op == "-=" || op == "*=" || op == "/=" || op == "%=" {
			p.next()
			// For unsupported /= and %=, mimic original: they parse as ??? producing expects errors at eval.
			// We keep AST and eval will return error `<op-prefix> expects 2 args but there is 1`
			right, err := p.parseAssign()
			if err != nil { return nil, err }
			return &AST{Kind: AKAssign, Op: op, L: left, R: right}, nil
		}
	}
	return left, nil
}

func (p *parser) parseAlternative() (*AST, error) {
	left, err := p.parseOr()
	if err != nil { return nil, err }
	for p.peek().Kind == TOp && (p.peek().Value == "//" || p.peek().Value == "?//") {
		op := p.next().Value
		right, err := p.parseOr()
		if err != nil { return nil, err }
		left = &AST{Kind: AKBinary, Op: op, L: left, R: right}
	}
	return left, nil
}
func (p *parser) parseOr() (*AST, error) {
	left, err := p.parseAnd()
	if err != nil { return nil, err }
	for p.peek().Kind == TIdent && p.peek().Value == "or" {
		p.next()
		right, err := p.parseAnd()
		if err != nil { return nil, err }
		left = &AST{Kind: AKBinary, Op: "or", L: left, R: right}
	}
	return left, nil
}
func (p *parser) parseAnd() (*AST, error) {
	left, err := p.parseComparison()
	if err != nil { return nil, err }
	for p.peek().Kind == TIdent && p.peek().Value == "and" {
		p.next()
		right, err := p.parseComparison()
		if err != nil { return nil, err }
		left = &AST{Kind: AKBinary, Op: "and", L: left, R: right}
	}
	return left, nil
}
func (p *parser) parseComparison() (*AST, error) {
	left, err := p.parseAdd()
	if err != nil { return nil, err }
	for p.peek().Kind == TOp {
		op := p.peek().Value
		if op == "==" || op == "!=" || op == "<" || op == ">" || op == "<=" || op == ">=" {
			p.next()
			right, err := p.parseAdd()
			if err != nil { return nil, err }
			left = &AST{Kind: AKBinary, Op: op, L: left, R: right}
			continue
		}
		break
	}
	return left, nil
}
func (p *parser) parseAdd() (*AST, error) {
	left, err := p.parseMul()
	if err != nil { return nil, err }
	for p.peek().Kind == TOp && (p.peek().Value == "+" || p.peek().Value == "-") {
		op := p.next().Value
		right, err := p.parseMul()
		if err != nil { return nil, err }
		left = &AST{Kind: AKBinary, Op: op, L: left, R: right}
	}
	return left, nil
}
func (p *parser) parseMul() (*AST, error) {
	left, err := p.parsePostfix()
	if err != nil { return nil, err }
	for p.peek().Kind == TOp && (p.peek().Value == "*" || p.peek().Value == "/" || p.peek().Value == "%") {
		op := p.next().Value
		right, err := p.parsePostfix()
		if err != nil { return nil, err }
		left = &AST{Kind: AKBinary, Op: op, L: left, R: right}
	}
	return left, nil
}

// parsePostfix parses a primary and any trailing path suffixes / question
func (p *parser) parsePostfix() (*AST, error) {
	node, err := p.parsePrimary()
	if err != nil { return nil, err }
	// suffix loop
	for {
		t := p.peek()
		if t.Kind == TQuestion {
			p.next()
			// mark optional on node if path/suffix else wrap
			node.Optional = true
			continue
		}
		if t.Kind == TDot || t.Kind == TDotDot || t.Kind == TEllipsis || t.Kind == TLBracket {
			steps, err := p.parseSuffixSteps()
			if err != nil { return nil, err }
			if len(steps) == 0 {
				break
			}
			// if node is already a path with no base? Merge if node kind is AKPath and its base is root? Our AKPath represents steps applied to input. If node is AKPath, appending steps works.
			if node.Kind == AKPath {
				node.Steps = append(node.Steps, steps...)
			} else {
				node = &AST{Kind: AKSuffix, Base: node, Steps: steps}
			}
			continue
		}
		break
	}
	return node, nil
}

// parseSuffixSteps parses one or more suffix steps starting at current token (dot / bracket)
func (p *parser) parseSuffixSteps() ([]PathStep, error) {
	var steps []PathStep
	for {
		t := p.peek()
		if t.Kind == TDotDot {
			p.next()
			steps = append(steps, PathStep{Type: "recursive"})
			continue
		}
		if t.Kind == TEllipsis {
			p.next()
			steps = append(steps, PathStep{Type: "ellipsis"})
			continue
		}
		if t.Kind == TDot {
			p.next()
			nt := p.peek()
			if nt.Kind == TIdentPath {
				p.next()
				steps = append(steps, PathStep{Type: "key", Key: nt.Value})
				continue
			}
			if nt.Kind == TString {
				p.next()
				// string key: evaluate its parts plain
				sval := stringFromToken(nt)
				steps = append(steps, PathStep{Type: "key", Key: sval})
				continue
			}
			if nt.Kind == TLBracket || nt.Kind == TDotDot || nt.Kind == TEllipsis {
				// .[...] or .. handled in loop
				continue
			}
			if nt.Kind == TNumber {
				p.next()
				steps = append(steps, PathStep{Type: "key", Key: nt.Value})
				continue
			}
			// dot alone in middle: self step (no-op)
			steps = append(steps, PathStep{Type: "self"})
			continue
		}
		if t.Kind == TLBracket {
			step, err := p.parseBracketStep()
			if err != nil { return nil, err }
			steps = append(steps, step)
			continue
		}
		break
	}
	return steps, nil
}

func (p *parser) parseBracketStep() (PathStep, error) {
	// consume [
	if _, err := p.expect(TLBracket); err != nil { return PathStep{}, err }
	if p.peek().Kind == TRBracket {
		p.next()
		return PathStep{Type: "iterate"}, nil
	}
	// Parse expression(s) until ] or :
	// We need to detect slice: parse first expression (not consuming colon/comma? comma union inside is okay)
	// Use parseAssign for first to avoid consuming top-level colon? parseAssign will not consume colon.
	// But commas inside brackets: .["a","b"] should be union of indices: parseComma handles union.
	first, err := p.parseComma()
	if err != nil { return PathStep{}, err }
	if p.peek().Kind == TColon {
		// slice
		p.next()
		var toExpr *AST
		hasTo := false
		if p.peek().Kind != TRBracket {
			toExpr, err = p.parseComma()
			if err != nil { return PathStep{}, err }
			hasTo = true
		}
		if _, err := p.expect(TRBracket); err != nil { return PathStep{}, err }
		// if first is something? Might be omitted: parser would have failed if starts with colon. Need handle [:1] separately below.
		return PathStep{Type: "slice", FromExpr: first, HasFrom: true, ToExpr: toExpr, HasTo: hasTo}, nil
	}
	if _, err := p.expect(TRBracket); err != nil { return PathStep{}, err }
	return PathStep{Type: "dyn", KeyExpr: first}, nil
}

// parsePrimary
func (p *parser) parsePrimary() (*AST, error) {
	t := p.peek()
	switch t.Kind {
	case TDot:
		// path starting at context
		steps, err := p.parseSuffixStepsForPrimary()
		if err != nil { return nil, err }
		return &AST{Kind: AKPath, Steps: steps}, nil
	case TDotDot:
		steps, err := p.parseSuffixSteps()
		if err != nil { return nil, err }
		return &AST{Kind: AKPath, Steps: steps}, nil
	case TEllipsis:
		steps, err := p.parseSuffixSteps()
		if err != nil { return nil, err }
		return &AST{Kind: AKPath, Steps: steps}, nil
	case TNumber:
		p.next()
		return &AST{Kind: AKLiteral, Node: guessNumberNode(t.Value)}, nil
	case TString:
		p.next()
		ast := &AST{Kind: AKString, Parts: t.Parts}
		// parse interpolations
		for _, part := range t.Parts {
			if part.IsExpr {
				if globalOpts != nil && !globalOpts.StringInterp {
					// treated as literal by lexer? Lexer already handled: if interp disabled, lexer won't create expr parts because opts check? lexString checks opts_AllowInterpolation which returns flag; if false, backslash... Actually our lexer: if nr=='(' && allowed => interp, else escape default: lit writes '\' + '(' => literal. So parts won't be expr.
					ast.PartExprs = append(ast.PartExprs, nil)
				} else {
					sub, err := parseExpressionString(part.ExprSrc)
					if err != nil { return nil, err }
					ast.PartExprs = append(ast.PartExprs, sub)
				}
				ast.HasInterp = true
			} else {
				ast.PartExprs = append(ast.PartExprs, nil)
			}
		}
		// compute plain value if no interp
		if !ast.HasInterp {
			ast.StrVal = stringFromToken(t)
		}
		return ast, nil
	case TVariable:
		p.next()
		return &AST{Kind: AKVariable, VarName: t.Value}, nil
	case TLParen:
		p.next()
		inner, err := p.parsePipe()
		if err != nil { return nil, err }
		if _, err := p.expect(TRParen); err != nil { return nil, err }
		return inner, nil
	case TLBracket:
		// collect array or slice starting with colon ? '[' then ...
		// Need lookahead for [: slice on context? Expression [:1] alone is??? Probably treat as collect if next not colon.
		if p.pos+1 < len(p.toks) && p.toks[p.pos+1].Kind == TColon {
			// slice on input
			step, err := p.parseBracketStepAllowEmptyFrom()
			if err != nil { return nil, err }
			return &AST{Kind: AKPath, Steps: []PathStep{step}}, nil
		}
		p.next() // [
		if p.peek().Kind == TRBracket {
			p.next()
			return &AST{Kind: AKLiteral, Node: &yaml.Node{Kind: yaml.SequenceNode, Tag: "!!seq"}}, nil
		}
		inner, err := p.parsePipe()
		if err != nil { return nil, err }
		if _, err := p.expect(TRBracket); err != nil { return nil, err }
		return &AST{Kind: AKCollect, Inner: inner}, nil
	case TLBrace:
		return p.parseCreateMap()
	case TIdent:
		return p.parseIdentPrimary()
	case TUnknownIdent:
		return nil, unknownIdentError(t)
	case TAt:
		p.next()
		return &AST{Kind: AKFunc, Name: t.Value}, nil
	case TOp:
		if t.Value == "-" {
			// unary minus for numbers only handled by lexer as number token; here operator with no lhs => error like original
			return nil, fmt.Errorf("'-' expects 2 args but there is 1")
		}
		return nil, fmt.Errorf("bad expression, please check expression syntax")
	}
	return nil, fmt.Errorf("bad expression, please check expression syntax")
}

func (p *parser) parseBracketStepAllowEmptyFrom() (PathStep, error) {
	// current is '[' and next is ':'
	p.expect(TLBracket)
	p.expect(TColon)
	var toExpr *AST
	hasTo := false
	var err error
	if p.peek().Kind != TRBracket {
		toExpr, err = p.parseComma()
		if err != nil { return PathStep{}, err }
		hasTo = true
	}
	if _, err := p.expect(TRBracket); err != nil { return PathStep{}, err }
	return PathStep{Type: "slice", HasFrom: false, ToExpr: toExpr, HasTo: hasTo}, nil
}

// suffix steps when primary starts with dot: handles initial dot etc using same logic but returns path steps
func (p *parser) parseSuffixStepsForPrimary() ([]PathStep, error) {
	// It starts with TDot
	var steps []PathStep
	// consume first dot and immediate key if any
	// Reuse parseSuffixSteps but need identity if dot alone: parseSuffixSteps will add self step when dot alone.
	steps, err := p.parseSuffixSteps()
	if err != nil { return nil, err }
	if len(steps) == 0 {
		steps = append(steps, PathStep{Type: "self"})
	}
	return steps, nil
}

func (p *parser) parseCreateMap() (*AST, error) {
	p.expect(TLBrace)
	node := &AST{Kind: AKCreateMap}
	if p.peek().Kind == TRBrace {
		p.next()
		return node, nil
	}
	for {
		// key expression: parse a postfix/primary (?) but not comma/colon
		// Use parseAssign but stopping at colon: parseAssign does not consume colon.
		// However key could be expression like (.a) or .a or "x" or number or $var etc.
		// If we use parseAssign, {"x": .a + 1} value parsing later separate.
		// For key, parseAlternative? Use parseAssign limited: it will parse .a etc and stop before colon.
		key, err := p.parseAssign()
		if err != nil { return nil, err }
		var val *AST
		if p.peek().Kind == TColon {
			p.next()
			if p.peek().Kind == TRBrace || p.peek().Kind == TComma {
				return nil, fmt.Errorf("':' expects 2 args but there is 1")
			}
			val, err = p.parseAssign()
			if err != nil { return nil, err }
		}
		node.Entries = append(node.Entries, MapEntry{Key: key, Val: val})
		if p.peek().Kind == TComma {
			p.next()
			if p.peek().Kind == TRBrace {
				return nil, fmt.Errorf("',' expects 2 args but there is 1")
			}
			continue
		}
		break
	}
	if _, err := p.expect(TRBrace); err != nil { return nil, err }
	return node, nil
}

func (p *parser) parseIdentPrimary() (*AST, error) {
	t := p.next() // TIdent
	name := t.Value
	switch name {
	case "true":
		return &AST{Kind: AKLiteral, Node: boolNode(true)}, nil
	case "false":
		return &AST{Kind: AKLiteral, Node: boolNode(false)}, nil
	case "null", "~":
		n := nullNode()
		if name == "~" {
			n.Value = "~"
		}
		return &AST{Kind: AKLiteral, Node: n}, nil
	case "as", "ireduce", "and", "or":
		// operator in wrong place
		// mimic arg errors
		if name == "and" || name == "or" {
			return nil, fmt.Errorf("'%s' expects 2 args but there is 0", name)
		}
		return nil, fmt.Errorf("bad expression, please check expression syntax")
	}
	// function
	var args []*AST
	hasParens := false
	if p.peek().Kind == TLParen {
		hasParens = true
		p.next()
		if p.peek().Kind == TRParen {
			p.next()
		} else {
			// special env/strenv: argument may be bare identifier
			if name == "env" || name == "strenv" {
				// consume one token as name
				at := p.next()
				var envName string
				switch at.Kind {
				case TIdent, TUnknownIdent, TVariable:
					envName = at.Value
				case TString:
					envName = stringFromToken(at)
				default:
					envName = at.Value
				}
				args = append(args, &AST{Kind: AKLiteral, Node: strNode(envName)})
				if _, err := p.expect(TRParen); err != nil { return nil, err }
				return &AST{Kind: AKFunc, Name: name, Args: args}, nil
			}
			for {
				arg, err := p.parsePipe()
				if err != nil { return nil, err }
				args = append(args, arg)
				if p.peek().Kind == TSemi {
					p.next()
					continue
				}
				break
			}
			if _, err := p.expect(TRParen); err != nil { return nil, err }
		}
	}
	_ = hasParens
	// flatten can have optional arg without? it's okay
	return &AST{Kind: AKFunc, Name: name, Args: args}, nil
}

func stringFromToken(t Token) string {
	var sb strings.Builder
	for _, part := range t.Parts {
		if !part.IsExpr {
			sb.WriteString(part.Text)
		} else {
			sb.WriteString("\\(")
			sb.WriteString(part.ExprSrc)
			sb.WriteString(")")
		}
	}
	return sb.String()
}

var _ = strings.TrimSpace
EOF
