{"command":"cat > traverse.go <<'EOF'
package main

import (
	"fmt"
	"strconv"
	"strings"

	"gopkg.in/yaml.v3"
)

func effectiveNode(n *yaml.Node) *yaml.Node {
	if n != nil && n.Kind == yaml.AliasNode && n.Alias != nil {
		return n.Alias
	}
	return n
}

func pathElemForKey(keyNode *yaml.Node) interface{} {
	if keyNode == nil {
		return ""
	}
	if keyNode.Tag == "!!int" {
		if v, err := strconv.Atoi(keyNode.Value); err == nil {
			return v
		}
	}
	return keyNode.Value
}

// find map entry
func findMapEntry(mapNode *yaml.Node, key string) (int, *yaml.Node, *yaml.Node) {
	for i := 0; i+1 < len(mapNode.Content); i += 2 {
		k := mapNode.Content[i]
		if k.Value == key {
			return i + 1, k, mapNode.Content[i+1]
		}
	}
	return -1, nil, nil
}

func applySteps(cands []*Candidate, steps []PathStep, create bool) ([]*Candidate, error) {
	current := cands
	for _, step := range steps {
		var next []*Candidate
		for _, c := range current {
			res, err := applyStep(c, step, create)
			if err != nil {
				return nil, err
			}
			next = append(next, res...)
		}
		current = next
		if len(current) == 0 {
			// can break but keep empty
			// continue to allow? no candidates
			// break
		}
	}
	return current, nil
}

func applyStep(c *Candidate, step PathStep, create bool) ([]*Candidate, error) {
	switch step.Type {
	case "self":
		return []*Candidate{c}, nil
	case "recursive":
		var out []*Candidate
		collectRecursive(c, c, &out)
		return out, nil
	case "ellipsis":
		var out []*Candidate
		collectEllipsis(c, &out)
		return out, nil
	case "key":
		return applyKey(c, step.Key, nil, create)
	case "dyn":
		return applyDyn(c, step, create)
	case "iterate":
		return applyIterate(c)
	case "slice":
		return applySlice(c, step)
	}
	return []*Candidate{c}, nil
}

func collectRecursive(orig, c *Candidate, out *[]*Candidate) {
	*out = append(*out, c)
	node := effectiveNode(c.Node)
	if node == nil {
		return
	}
	if node.Kind == yaml.MappingNode {
		for i := 0; i+1 < len(node.Content); i += 2 {
			val := node.Content[i+1]
			child := c.child(val, node, i+1, pathElemForKey(node.Content[i]))
			collectRecursive(orig, child, out)
		}
	} else if node.Kind == yaml.SequenceNode {
		for i, el := range node.Content {
			child := c.child(el, node, i, i)
			collectRecursive(orig, child, out)
		}
	}
}

func collectEllipsis(c *Candidate, out *[]*Candidate) {
	*out = append(*out, c)
	node := effectiveNode(c.Node)
	if node == nil {
		return
	}
	if node.Kind == yaml.MappingNode {
		for i := 0; i+1 < len(node.Content); i += 2 {
			k := node.Content[i]
			v := node.Content[i+1]
			keyCand := c.child(k, node, i, pathElemForKey(k))
			keyCand.IsKey = true
			// ellipsis on key: key candidate included, then its children (none)
			collectEllipsis(keyCand, out)
			valCand := c.child(v, node, i+1, pathElemForKey(k))
			collectEllipsis(valCand, out)
		}
	} else if node.Kind == yaml.SequenceNode {
		for i, el := range node.Content {
			child := c.child(el, node, i, i)
			collectEllipsis(child, out)
		}
	}
}

func applyKey(c *Candidate, key string, keyNode *yaml.Node, create bool) ([]*Candidate, error) {
	node := effectiveNode(c.Node)
	if node == nil {
		return []*Candidate{makeNullCandidateLike(c)}, nil
	}
	// pseudo candidate traversal? If c is pseudo, traverse its string value? return empty
	if c.Pseudo != "" {
		return nil, nil
	}
	switch node.Kind {
	case yaml.MappingNode:
		idx, kNode, val := findMapEntry(node, key)
		if idx >= 0 {
			child := c.child(val, node, idx, pathElemForKey(kNode))
			return []*Candidate{child}, nil
		}
		if create {
			// create new entry
			var kn *yaml.Node
			if keyNode != nil {
				kn = cloneNode(keyNode)
			} else {
				kn = strNode(key)
			}
			// If key node is string but numeric, ensure tag str; yaml encoder will quote as needed
			nv := nullNode()
			node.Content = append(node.Content, kn, nv)
			child := c.child(nv, node, len(node.Content)-1, pathElemForKey(kn))
			return []*Candidate{child}, nil
		}
		// missing -> null virtual candidate
		nc := c.cloneShallow()
		nc.Node = nullNode()
		nc.Parent = nil
		nc.Index = 0
		// path append
		p := make([]interface{}, len(c.Path), len(c.Path)+1)
		copy(p, c.Path)
		// path element type: if keyNode int etc
		if keyNode != nil {
			nc.Path = append(p, pathElemForKey(keyNode))
		} else {
			// try numeric?
			nc.Path = append(p, key)
		}
		nc.IsKey = false
		nc.Pseudo = ""
		nc.Target = nil
		nc.FromRoot = false
		return []*Candidate{nc}, nil
	case yaml.SequenceNode:
		// parse index
		iv, err := strconv.ParseInt(key, 10, 64)
		if err != nil {
			return nil, fmt.Errorf("cannot index array with '%s' (%v)", key, err)
		}
		return applyIndex(c, int(iv), create)
	case yaml.ScalarNode:
		if node.Tag == "!!null" {
			if create {
				// convert null node in-place to map if candidate node is mutable real node (not alias)
				// Only if c.Node is the actual node (scalar)
				if c.Node != nil && c.Node.Kind == yaml.ScalarNode {
					// mutate to mapping
					c.Node.Kind = yaml.MappingNode
					c.Node.Tag = "!!map"
					c.Node.Value = ""
					c.Node.Content = nil
					c.Node.Style = 0
					return applyKey(c, key, keyNode, create)
				}
			}
			nc := c.cloneShallow()
			nc.Node = nullNode()
			nc.Parent = nil
			p := make([]interface{}, len(c.Path), len(c.Path)+1)
			copy(p, c.Path)
			nc.Path = append(p, key)
			return []*Candidate{nc}, nil
		}
		// scalar non-null: no traversal
		return nil, nil
	case yaml.DocumentNode:
		if len(node.Content) > 0 {
			cc := c.cloneShallow()
			cc.Node = node.Content[0]
			return applyKey(cc, key, keyNode, create)
		}
		return []*Candidate{makeNullCandidateLike(c)}, nil
	}
	return nil, nil
}

func applyIndex(c *Candidate, idx int, create bool) ([]*Candidate, error) {
	node := effectiveNode(c.Node)
	if node == nil {
		return []*Candidate{makeNullCandidateLike(c)}, nil
	}
	if node.Kind == yaml.MappingNode {
		// index by int key as string
		return applyKey(c, strconv.Itoa(idx), intNode(int64(idx)), create)
	}
	if node.Kind != yaml.SequenceNode {
		if node.Kind == yaml.ScalarNode && node.Tag == "!!null" {
			// treat as null traversal
			nc := c.cloneShallow()
			nc.Node = nullNode()
			nc.Parent = nil
			p := make([]interface{}, len(c.Path), len(c.Path)+1)
			copy(p, c.Path)
			nc.Path = append(p, idx)
			return []*Candidate{nc}, nil
		}
		return nil, nil
	}
	origIdx := idx
	if idx < 0 {
		idx = len(node.Content) + idx
	}
	if idx >= 0 && idx < len(node.Content) {
		child := c.child(node.Content[idx], node, idx, idx)
		return []*Candidate{child}, nil
	}
	if create {
		if idx < 0 {
			// cannot create negative beyond? return empty
			return nil, nil
		}
		for len(node.Content) <= idx {
			node.Content = append(node.Content, nullNode())
		}
		child := c.child(node.Content[idx], node, idx, idx)
		return []*Candidate{child}, nil
	}
	// out of range -> null
	nc := c.cloneShallow()
	nc.Node = nullNode()
	nc.Parent = nil
	p := make([]interface{}, len(c.Path), len(c.Path)+1)
	copy(p, c.Path)
	nc.Path = append(p, origIdx)
	return []*Candidate{nc}, nil
}

func applyDyn(c *Candidate, step PathStep, create bool) ([]*Candidate, error) {
	if step.KeyExpr == nil {
		return []*Candidate{c}, nil
	}
	// Evaluate key expression against single candidate
	ctx := &EvalContext{Candidates: []*Candidate{c}, Vars: currentVars()}
	// Use saved vars? EvalContext is passed via global? Instead applySteps caller should handle vars. Simplify: the evaluation of paths is done in eval.go where ctx vars known. applySteps needs vars.
	// We'll use thread-local var stack `evalVarsStack` top if present.
	if len(varStack) > 0 {
		ctx.Vars = varStack[len(varStack)-1]
	}
	results, err := evalAST(step.KeyExpr, ctx)
	if err != nil {
		return nil, err
	}
	var out []*Candidate
	for _, r := range results {
		rn := effectiveNode(r.Node)
		if rn == nil {
			continue
		}
		if rn.Kind == yaml.MappingNode || rn.Kind == yaml.SequenceNode {
			// dynamic key as a composite? skip
			continue
		}
		keyStr := rn.Value
		node := effectiveNode(c.Node)
		if node != nil && node.Kind == yaml.SequenceNode {
			iv, err := strconv.ParseInt(keyStr, 10, 64)
			if err != nil {
				return nil, fmt.Errorf("cannot index array with '%s' (%v)", keyStr, err)
			}
			res, err := applyIndex(c, int(iv), create)
			if err != nil { return nil, err }
			out = append(out, res...)
		} else if node != nil && node.Kind == yaml.MappingNode {
			// key node for creation: use rn clone as key if creating
			res, err := applyKeyWithNode(c, keyStr, rn, create)
			if err != nil { return nil, err }
			out = append(out, res...)
		} else {
			// scalar/null
			// if string and ... dyn used for slice handled separately. For other scalars, mimic applyKey behavior
			res, err := applyKey(c, keyStr, rn, create)
			if err != nil { return nil, err }
			out = append(out, res...)
		}
	}
	return out, nil
}

func applyKeyWithNode(c *Candidate, key string, keyNode *yaml.Node, create bool) ([]*Candidate, error) {
	// like applyKey but preserve key node type for creation
	node := effectiveNode(c.Node)
	if node != nil && node.Kind == yaml.MappingNode {
		idx, kNode, val := findMapEntry(node, key)
		if idx >= 0 {
			child := c.child(val, node, idx, pathElemForKey(kNode))
			return []*Candidate{child}, nil
		}
		if create {
			kn := cloneNode(keyNode)
			// key nodes from expressions: string literal nodes have style 0; ensure tag
			if kn.Kind == 0 {
				kn.Kind = yaml.ScalarNode
			}
			nv := nullNode()
			node.Content = append(node.Content, kn, nv)
			child := c.child(nv, node, len(node.Content)-1, pathElemForKey(kn))
			return []*Candidate{child}, nil
		}
		nc := c.cloneShallow()
		nc.Node = nullNode()
		nc.Parent = nil
		p := make([]interface{}, len(c.Path), len(c.Path)+1)
		copy(p, c.Path)
		nc.Path = append(p, pathElemForKey(keyNode))
		return []*Candidate{nc}, nil
	}
	return applyKey(c, key, keyNode, create)
}

func applyIterate(c *Candidate) ([]*Candidate, error) {
	node := effectiveNode(c.Node)
	if node == nil {
		return nil, nil
	}
	var out []*Candidate
	if node.Kind == yaml.MappingNode {
		for i := 0; i+1 < len(node.Content); i += 2 {
			child := c.child(node.Content[i+1], node, i+1, pathElemForKey(node.Content[i]))
			out = append(out, child)
		}
		return out, nil
	}
	if node.Kind == yaml.SequenceNode {
		for i, el := range node.Content {
			child := c.child(el, node, i, i)
			out = append(out, child)
		}
		return out, nil
	}
	return nil, nil
}

func applySlice(c *Candidate, step PathStep) ([]*Candidate, error) {
	node := effectiveNode(c.Node)
	if node == nil {
		return nil, nil
	}
	evalIdx := func(expr *AST, def int) (int, error) {
		if expr == nil {
			return def, nil
		}
		ctx := &EvalContext{Candidates: []*Candidate{c}}
		if len(varStack) > 0 {
			ctx.Vars = varStack[len(varStack)-1]
		}
		res, err := evalAST(expr, ctx)
		if err != nil {
			return 0, err
		}
		if len(res) == 0 {
			return def, nil
		}
		rn := effectiveNode(res[0].Node)
		iv, err := strconv.Atoi(strings.TrimSpace(rn.Value))
		if err != nil {
			return 0, err
		}
		return iv, nil
	}
	if node.Kind == yaml.SequenceNode {
		from := 0
		to := len(node.Content)
		var err error
		if step.HasFrom {
			from, err = evalIdx(step.FromExpr, 0)
			if err != nil { return nil, err }
		}
		if step.HasTo {
			to, err = evalIdx(step.ToExpr, len(node.Content))
			if err != nil { return nil, err }
		}
		if from < 0 { from = len(node.Content) + from }
		if to < 0 { to = len(node.Content) + to }
		if from < 0 { from = 0 }
		if to < 0 { to = 0 }
		if from > len(node.Content) { from = len(node.Content) }
		if to > len(node.Content) { to = len(node.Content) }
		if from > to { from = to }
		newNode := &yaml.Node{Kind: yaml.SequenceNode, Tag: "!!seq"}
		for i := from; i < to; i++ {
			newNode.Content = append(newNode.Content, node.Content[i])
		}
		nc := candWithNode(c, newNode)
		nc.Path = c.Path
		nc.DocIndex = c.DocIndex
		return []*Candidate{nc}, nil
	}
	if node.Kind == yaml.ScalarNode && node.Tag == "!!str" {
		runes := []rune(node.Value)
		from := 0
		to := len(runes)
		var err error
		if step.HasFrom {
			from, err = evalIdx(step.FromExpr, 0)
			if err != nil { return nil, err }
		}
		if step.HasTo {
			to, err = evalIdx(step.ToExpr, len(runes))
			if err != nil { return nil, err }
		}
		if from < 0 { from = len(runes) + from }
		if to < 0 { to = len(runes) + to }
		if from < 0 { from = 0 }
		if to < 0 { to = 0 }
		if from > len(runes) { from = len(runes) }
		if to > len(runes) { to = len(runes) }
		if from > to { from = to }
		nc := candWithNode(c, strNode(string(runes[from:to])))
		return []*Candidate{nc}, nil
	}
	// for maps etc: return null like .a[0]? Slice on map: return null candidate
	if node.Kind == yaml.MappingNode {
		return []*Candidate{makeNullCandidateLike(c)}, nil
	}
	return nil, nil
}
EOF
"}

