func applySlice(c *Candidate, step PathStep) ([]*Candidate, error) {
	node := effectiveNode(c.Node)
	if node == nil {
		return nil, nil
	}
	evalIdx := func(expr *AST, def int) (int, error) {
		if expr == nil {
			return def, nil
		}
		ctx := &EvalContext{Candidates: []*Candidate{c}}
		if len(varStack) > 0 {
			ctx.Vars = varStack[len(varStack)-1]
		}
		res, err := evalAST(expr, ctx)
		if err != nil {
			return 0, err
		}
		if len(res) == 0 {
			return def, nil
		}
		rn := effectiveNode(res[0].Node)
		iv, err := strconv.Atoi(strings.TrimSpace(rn.Value))
		if err != nil {
			return 0, err
		}
		return iv, nil
	}
	if node.Kind == yaml.SequenceNode {
		from := 0
		to := len(node.Content)
		var err error
		if step.HasFrom {
			from, err = evalIdx(step.FromExpr, 0)
			if err != nil { return nil, err }
		}
		if step.HasTo {
			to, err = evalIdx(step.ToExpr, len(node.Content))
			if err != nil { return nil, err }
		}
		if from < 0 { from = len(node.Content) + from }
		if to < 0 { to = len(node.Content) + to }
		if from < 0 { from = 0 }
		if to < 0 { to = 0 }
		if from > len(node.Content) { from = len(node.Content) }
		if to > len(node.Content) { to = len(node.Content) }
		if from > to { from = to }
		newNode := &yaml.Node{Kind: yaml.SequenceNode, Tag: "!!seq"}
		for i := from; i < to; i++ {
			newNode.Content = append(newNode.Content, node.Content[i])
		}
		nc := candWithNode(c, newNode)
		nc.Path = c.Path
		nc.DocIndex = c.DocIndex
		return []*Candidate{nc}, nil
	}
	if node.Kind == yaml.ScalarNode && node.Tag == "!!str" {
		runes := []rune(node.Value)
		from := 0
		to := len(runes)
		var err error
		if step.HasFrom {
			from, err = evalIdx(step.FromExpr, 0)
			if err != nil { return nil, err }
		}
		if step.HasTo {
			to, err = evalIdx(step.ToExpr, len(runes))
			if err != nil { return nil, err }
		}
		if from < 0 { from = len(runes) + from }
		if to < 0 { to = len(runes) + to }
		if from < 0 { from = 0 }
		if to < 0 { to = 0 }
		if from > len(runes) { from = len(runes) }
		if to > len(runes) { to = len(runes) }
		if from > to { from = to }
		nc := candWithNode(c, strNode(string(runes[from:to])))
		return []*Candidate{nc}, nil
	}
	// for maps etc: return null like .a[0]? Slice on map: return null candidate
	if node.Kind == yaml.MappingNode {
		return []*Candidate{makeNullCandidateLike(c)}, nil
	}
	return nil, nil
}
