func evalAST(ast *AST, ctx *EvalContext) ([]*Candidate, error) {
	if ast == nil {
		return nil, nil
	}
	if ctx.Vars == nil {
		ctx = &EvalContext{Candidates: ctx.Candidates, Vars: make(map[string][]*Candidate)}
	}
