		if err != nil {
			if ast.Optional {
				return nil, nil
			}
			return nil, err
		}
		res, err := applySteps(base, ast.Steps, false)
		if err != nil {
			if ast.Optional {
				return nil, nil
			}
			return nil, err
		}
		return res, nil
