		for _, c := range left {
			cc := c.cloneShallow()
			cc.Lead = cc
			rc = append(rc, cc)
		}
		return evalAST(ast.R, ctx.withCandidates(rc))
	case AKUnion:
		left, err := evalAST(ast.L, ctx)
		if err != nil {
			return nil, err
		}
		right, err := evalAST(ast.R, ctx)
		if err != nil {
			return nil, err
		}
		return append(left, right...), nil
	case AKBinary:
		return evalBinary(ast, ctx)
	case AKAssign:
		return evalAssign(ast, ctx)
	case AKVarAssign:
		src, err := evalAST(ast.Source, ctx)
		if err != nil {
			return nil, err
