func effectiveNodeForCollect(n *yaml.Node) *yaml.Node {
	// When collecting, yq keeps node as-is (including flow style?). Collect creates block seq, elements retain their original nodes (clone external)
	if n == nil {
		return nullNode()
	}
	return n
}

func candidateToString(c *Candidate) string {
	if c == nil || c.Node == nil {
		return ""
	}
	n := effectiveNode(c.Node)
