	return nodeStringValue(n)
}

func evalCreateMap(ast *AST, ctx *EvalContext, c *Candidate) (*Candidate, error) {
	// If any entry has nil value, behaviour: returns no candidate (as observed {.a} -> no output)
	for _, e := range ast.Entries {
		if e.Val == nil {
			// Check special mismatch handling: if more than... Original {.a} gave no output (empty candidate list)
			return nil, nil
		}
	}
