	var entryPairs [][]pair
	for _, e := range ast.Entries {
		keys, err := evalAST(e.Key, ctx.withCandidates([]*Candidate{c}))
		if err != nil {
			return nil, err
		}
		vals, err := evalAST(e.Val, ctx.withCandidates([]*Candidate{c}))
		if err != nil {
			return nil, err
		}
		if len(keys) == 0 || len(vals) == 0 {
			return nil, fmt.Errorf("CollectObject: mismatching node sizes; are you creating a map with mismatching key value pairs?")
		}
		var eps []pair
		for _, k := range keys {
			for _, v := range vals {
				kn := keyNodeFromCandidate(k)
				eps = append(eps, pair{kn, cloneNode(v.Node)})
			}
		}
		entryPairs = append(entryPairs, eps)
	}
