func evalAssignTarget(ast *AST, ctx *EvalContext) ([]*Candidate, error) {
	if ast == nil {
		return nil, nil
	}
	pop := pushVars(ctx.Vars)
	defer pop()
	switch ast.Kind {
	case AKPath:
		return applySteps(ctx.Candidates, ast.Steps, true)
	case AKSuffix:
		base, err := evalAssignTarget(ast.Base, ctx)
		if err != nil {
			// if base is not path (e.g., func results), fall back to eval then apply steps with create
			base, err = evalAST(ast.Base, ctx)
			if err != nil {
				return nil, err
			}
			return applySteps(base, ast.Steps, true)
		}
		return applySteps(base, ast.Steps, true)
	case AKPipe:
		// evaluate left, then right target with lead reset
		left, err := evalAST(ast.L, ctx)
		if err != nil {
			return nil, err
		}
		var rc []*Candidate
		for _, c := range left {
			cc := c.cloneShallow()
			cc.Lead = cc
			rc = append(rc, cc)
		}
		return evalAssignTarget(ast.R, ctx.withCandidates(rc))
	default:
		return evalAST(ast, ctx)
	}
}
EOF
"}

