{"command":"cat > ops.go <<'EOF'
package main

import (
	"fmt"
	"math"
	"strconv"
	"strings"
	"time"

	"gopkg.in/yaml.v3"
)

func evalBinary(ast *AST, ctx *EvalContext) ([]*Candidate, error) {
	op := ast.Op
	if op == "//" || op == "?//" {
		var out []*Candidate
		for _, c := range ctx.Candidates {
			left, err := evalAST(ast.L, ctx.withCandidates([]*Candidate{c}))
			if err != nil {
				if op == "?//" {
					// suppressed
					left = nil
				} else {
					return nil, err
				}
			}
			var filtered []*Candidate
			for _, r := range left {
				if truthy(effectiveNode(r.Node)) {
					filtered = append(filtered, r)
				}
			}
			if len(filtered) > 0 {
				out = append(out, filtered...)
			} else {
				right, err := evalAST(ast.R, ctx.withCandidates([]*Candidate{c}))
				if err != nil {
					return nil, err
				}
				out = append(out, right...)
			}
		}
		return out, nil
	}
	left, err := evalAST(ast.L, ctx)
	if err != nil {
		return nil, err
	}
	right, err := evalAST(ast.R, ctx)
	if err != nil {
		return nil, err
	}
	var out []*Candidate
	for _, l := range left {
		for _, r := range right {
			resNode, err := applyBinaryOp(op, l, r)
			if err != nil {
				return nil, err
			}
			if resNode == nil {
				continue
			}
			nc := candWithNode(l, resNode)
			// candWithNode clones l shallow including DocIndex; lead points to l's lead
			out = append(out, nc)
		}
	}
	return out, nil
}

func applyBinaryOp(op string, l, r *Candidate) (*yaml.Node, error) {
	ln := effectiveNode(l.Node)
	rn := effectiveNode(r.Node)
	switch op {
	case "and":
		return boolNode(truthy(ln) && truthy(rn)), nil
	case "or":
		return boolNode(truthy(ln) || truthy(rn)), nil
	case "==":
		return boolNode(nodesEqualForEq(ln, rn)), nil
	case "!=":
		return boolNode(!nodesEqualForEq(ln, rn)), nil
	case "<", ">", "<=", ">=":
		return compareOp(op, l, r)
	case "+":
		return addNodes(l, r)
	case "-":
		return subtractNodes(l, r)
	case "*":
		return multiplyNodes(l, r)
	case "/":
		return divideNodes(l, r)
	case "%":
		return moduloNodes(l, r)
	}
	return nil, fmt.Errorf("bad expression, please check expression syntax")
}

func nodesEqualForEq(a, b *yaml.Node) bool {
	if a == nil || b == nil {
		return a == b
	}
	// null handling
	if a.Tag == "!!null" && b.Tag == "!!null" {
		return true
	}
	if a.Kind != yaml.ScalarNode || b.Kind != yaml.ScalarNode {
		return false
	}
	return a.Value == b.Value
}

func compareOp(op string, l, r *Candidate) (*yaml.Node, error) {
	ln := effectiveNode(l.Node)
	rn := effectiveNode(r.Node)
	if ln.Kind == yaml.SequenceNode {
		return nil, fmt.Errorf("arrays not yet supported for comparison")
	}
	if ln.Kind == yaml.MappingNode {
		return nil, fmt.Errorf("maps not yet supported for comparison")
	}
	if ln.Tag == "!!bool" {
		return nil, fmt.Errorf("!!bool not yet supported for comparison")
	}
	if ln.Tag == "!!null" && rn.Tag == "!!null" {
		switch op {
		case "<", ">":
			return boolNode(false), nil
		default:
			return boolNode(true), nil
		}
	}
	// numeric
	if isNumberTag(ln.Tag) && isNumberTag(rn.Tag) {
		lf, _ := parseFloatValue(normaliseNumStr(ln.Value))
		rf, _ := parseFloatValue(normaliseNumStr(rn.Value))
		return boolNode(cmpOpFloat(op, lf, rf)), nil
	}
	if ln.Tag == "!!timestamp" && rn.Tag == "!!timestamp" {
		lt, err1 := parseTimeValue(ln.Value)
		rt, err2 := parseTimeValue(rn.Value)
		if err1 == nil && err2 == nil {
			if lt.Before(rt) {
				return boolNode(op == "<" || op == "<="), nil
			}
			if lt.After(rt) {
				return boolNode(op == ">" || op == ">="), nil
			}
			return boolNode(op == "<=" || op == ">="), nil
		}
	}
	if ln.Kind == yaml.ScalarNode && rn.Kind == yaml.ScalarNode && ln.Tag == rn.Tag {
		// string etc lexical
		cmp := strings.Compare(ln.Value, rn.Value)
		return boolNode(cmpOpInt(op, cmp)), nil
	}
	// mismatched types
	return nil, fmt.Errorf("%s not yet supported for comparison", ln.Tag)
}

func isNumberTag(t string) bool { return t == "!!int" || t == "!!float" }
func cmpOpFloat(op string, a, b float64) bool {
	switch op {
	case "<":
		return a < b
	case ">":
		return a > b
	case "<=":
		return a <= b
	case ">=":
		return a >= b
	}
	return false
}
func cmpOpInt(op string, cmp int) bool {
	switch op {
	case "<":
		return cmp < 0
	case ">":
		return cmp > 0
	case "<=":
		return cmp <= 0
	case ">=":
		return cmp >= 0
	}
	return false
}

func parseTimeValue(s string) (time.Time, error) {
	layouts := []string{time.RFC3339Nano, "2006-01-02T15:04:05Z07:00", "2006-01-02 15:04:05Z07:00", "2006-01-02 15:04:05", "2006-01-02"}
	for _, l := range layouts {
		if t, err := time.Parse(l, s); err == nil {
			return t, nil
		}
	}
	return time.Time{}, fmt.Errorf("unable to parse time %s", s)
}

func addNodes(l, r *Candidate) (*yaml.Node, error) {
	ln := effectiveNode(l.Node)
	rn := effectiveNode(r.Node)
	// null lhs identity
	if ln.Tag == "!!null" && ln.Kind == yaml.ScalarNode {
		return cloneNode(rn), nil
	}
	if rn.Tag == "!!null" && rn.Kind == yaml.ScalarNode {
		return nil, fmt.Errorf("%s cannot be added to !!null", ln.Tag)
	}
	// timestamps + duration
	if ln.Tag == "!!timestamp" && rn.Tag == "!!str" {
		t, err := parseTimeValue(ln.Value)
		if err != nil { return nil, err }
		d, err := time.ParseDuration(rn.Value)
		if err != nil { return nil, fmt.Errorf("unable to parse duration [%s]: %v", rn.Value, err) }
		return scalarNode("!!timestamp", t.Add(d).Format(time.RFC3339)), nil
	}
	// maps
	if ln.Kind == yaml.MappingNode || rn.Kind == yaml.MappingNode {
