		ri, _, err := parseIntValue(rn.Value)
		if err != nil { return nil, err }
		var res int64
		switch op {
		case "+": res = li + ri
		case "-": res = li - ri
		case "*": res = li * ri
		case "%": res = li % ri
		}
		return scalarNode("!!int", formatIntWithFormat(res, lformat)), nil
	}
	lf, err := parseFloatValue(normaliseNumStr(ln.Value))
	if err != nil { return nil, err }
	rf, err := parseFloatValue(normaliseNumStr(rn.Value))
	if err != nil { return nil, err }
	var res float64
	switch op {
	case "+": res = lf + rf
	case "-": res = lf - rf
	case "*": res = lf * rf
	case "/": res = lf / rf
	case "%": res = math.Mod(lf, rf)
	}
	return scalarNode("!!float", formatFloat(res)), nil
}

var _ = strconv.Itoa
EOF

