{"command":"cat > ops.go <<'EOF'
package main

import (
	"fmt"
	"math"
	"strconv"
	"strings"
	"time"

	"gopkg.in/yaml.v3"
)

func evalBinary(ast *AST, ctx *EvalContext) ([]*Candidate, error) {
	op := ast.Op
	if op == "//" || op == "?//" {
		var out []*Candidate
		for _, c := range ctx.Candidates {
			left, err := evalAST(ast.L, ctx.withCandidates([]*Candidate{c}))
			if err != nil {
				if op == "?//" {
					// suppressed
					left = nil
				} else {
					return nil, err
				}
			}
			var filtered []*Candidate
			for _, r := range left {
				if truthy(effectiveNode(r.Node)) {
					filtered = append(filtered, r)
				}
			}
			if len(filtered) > 0 {
				out = append(out, filtered...)
			} else {
				right, err := evalAST(ast.R, ctx.withCandidates([]*Candidate{c}))
				if err != nil {
					return nil, err
				}
				out = append(out, right...)
			}
		}
		return out, nil
	}
	left, err := evalAST(ast.L, ctx)
	if err != nil {
		return nil, err
	}
	right, err := evalAST(ast.R, ctx)
	if err != nil {
		return nil, err
	}
	var out []*Candidate
	for _, l := range left {
		for _, r := range right {
			resNode, err := applyBinaryOp(op, l, r)
			if err != nil {
				return nil, err
			}
			if resNode == nil {
				continue
			}
			nc := candWithNode(l, resNode)
			// candWithNode clones l shallow including DocIndex; lead points to l's lead
			out = append(out, nc)
		}
	}
	return out, nil
}

func applyBinaryOp(op string, l, r *Candidate) (*yaml.Node, error) {
	ln := effectiveNode(l.Node)
	rn := effectiveNode(r.Node)
	switch op {
	case "and":
		return boolNode(truthy(ln) && truthy(rn)), nil
	case "or":
		return boolNode(truthy(ln) || truthy(rn)), nil
	case "==":
		return boolNode(nodesEqualForEq(ln, rn)), nil
	case "!=":
		return boolNode(!nodesEqualForEq(ln, rn)), nil
	case "<", ">", "<=", ">=":
		return compareOp(op, l, r)
	case "+":
		return addNodes(l, r)
	case "-":
		return subtractNodes(l, r)
	case "*":
		return multiplyNodes(l, r)
	case "/":
		return divideNodes(l, r)
	case "%":
		return moduloNodes(l, r)
	}
	return nil, fmt.Errorf("bad expression, please check expression syntax")
}

func nodesEqualForEq(a, b *yaml.Node) bool {
	if a == nil || b == nil {
		return a == b
	}
	// null handling
	if a.Tag == "!!null" && b.Tag == "!!null" {
		return true
	}
	if a.Kind != yaml.ScalarNode || b.Kind != yaml.ScalarNode {
		return false
	}
	return a.Value == b.Value
}

func compareOp(op string, l, r *Candidate) (*yaml.Node, error) {
	ln := effectiveNode(l.Node)
	rn := effectiveNode(r.Node)
	if ln.Kind == yaml.SequenceNode {
		return nil, fmt.Errorf("arrays not yet supported for comparison")
	}
	if ln.Kind == yaml.MappingNode {
		return nil, fmt.Errorf("maps not yet supported for comparison")
	}
	if ln.Tag == "!!bool" {
		return nil, fmt.Errorf("!!bool not yet supported for comparison")
	}
	if ln.Tag == "!!null" && rn.Tag == "!!null" {
		switch op {
		case "<", ">":
			return boolNode(false), nil
		default:
			return boolNode(true), nil
		}
	}
	// numeric
	if isNumberTag(ln.Tag) && isNumberTag(rn.Tag) {
		lf, _ := parseFloatValue(normaliseNumStr(ln.Value))
		rf, _ := parseFloatValue(normaliseNumStr(rn.Value))
		return boolNode(cmpOpFloat(op, lf, rf)), nil
	}
	if ln.Tag == "!!timestamp" && rn.Tag == "!!timestamp" {
		lt, err1 := parseTimeValue(ln.Value)
		rt, err2 := parseTimeValue(rn.Value)
		if err1 == nil && err2 == nil {
			if lt.Before(rt) {
				return boolNode(op == "<" || op == "<="), nil
			}
			if lt.After(rt) {
				return boolNode(op == ">" || op == ">="), nil
			}
			return boolNode(op == "<=" || op == ">="), nil
		}
	}
	if ln.Kind == yaml.ScalarNode && rn.Kind == yaml.ScalarNode && ln.Tag == rn.Tag {
		// string etc lexical
		cmp := strings.Compare(ln.Value, rn.Value)
		return boolNode(cmpOpInt(op, cmp)), nil
	}
	// mismatched types
	return nil, fmt.Errorf("%s not yet supported for comparison", ln.Tag)
}

func isNumberTag(t string) bool { return t == "!!int" || t == "!!float" }
func cmpOpFloat(op string, a, b float64) bool {
	switch op {
	case "<":
		return a < b
	case ">":
		return a > b
	case "<=":
		return a <= b
	case ">=":
		return a >= b
	}
	return false
}
func cmpOpInt(op string, cmp int) bool {
	switch op {
	case "<":
		return cmp < 0
	case ">":
		return cmp > 0
	case "<=":
		return cmp <= 0
	case ">=":
		return cmp >= 0
	}
	return false
}

func parseTimeValue(s string) (time.Time, error) {
	layouts := []string{time.RFC3339Nano, "2006-01-02T15:04:05Z07:00", "2006-01-02 15:04:05Z07:00", "2006-01-02 15:04:05", "2006-01-02"}
	for _, l := range layouts {
		if t, err := time.Parse(l, s); err == nil {
			return t, nil
		}
	}
	return time.Time{}, fmt.Errorf("unable to parse time %s", s)
}

func addNodes(l, r *Candidate) (*yaml.Node, error) {
	ln := effectiveNode(l.Node)
	rn := effectiveNode(r.Node)
	// null lhs identity
	if ln.Tag == "!!null" && ln.Kind == yaml.ScalarNode {
		return cloneNode(rn), nil
	}
	if rn.Tag == "!!null" && rn.Kind == yaml.ScalarNode {
		return nil, fmt.Errorf("%s cannot be added to !!null", ln.Tag)
	}
	// timestamps + duration
	if ln.Tag == "!!timestamp" && rn.Tag == "!!str" {
		t, err := parseTimeValue(ln.Value)
		if err != nil { return nil, err }
		d, err := time.ParseDuration(rn.Value)
		if err != nil { return nil, fmt.Errorf("unable to parse duration [%s]: %v", rn.Value, err) }
		return scalarNode("!!timestamp", t.Add(d).Format(time.RFC3339)), nil
	}
	// maps
	if ln.Kind == yaml.MappingNode || rn.Kind == yaml.MappingNode {
		if ln.Kind == yaml.MappingNode && rn.Kind == yaml.MappingNode {
			res := cloneNode(ln)
			mergeMapsShallow(res, rn)
			return res, nil
		}
		// error: rhs cannot be added to lhs
		return nil, fmt.Errorf("%s (%s) cannot be added to a %s (%s)", rn.Tag, pathLast(r), ln.Tag, pathLast(l))
	}
	// sequences
	if ln.Kind == yaml.SequenceNode {
		res := cloneNode(ln)
		if rn.Kind == yaml.SequenceNode {
			for _, el := range rn.Content {
				res.Content = append(res.Content, cloneNode(el))
			}
		} else {
			res.Content = append(res.Content, cloneNode(rn))
		}
		return res, nil
	}
	if rn.Kind == yaml.SequenceNode {
		res := cloneNode(rn)
		// prepend lhs
		res.Content = append([]*yaml.Node{cloneNode(ln)}, res.Content...)
		return res, nil
	}
	// strings
	if ln.Tag == "!!str" || rn.Tag == "!!str" {
		return strNode(nodeScalarString(ln) + nodeScalarString(rn)), nil
	}
	// numbers
	if isNumberTag(ln.Tag) && isNumberTag(rn.Tag) {
		return arithmeticResult("+", ln, rn)
	}
	return nil, fmt.Errorf("%s cannot be added to %s", ln.Tag, rn.Tag)
}

func pathLast(c *Candidate) string {
	if c == nil || len(c.Path) == 0 {
		return ""
	}
	// yq message uses path ..? Use last element or full? For .c it is c, for root empty.
	// We'll use full dotted if multiple? Tests may use nested. Use last for c case, but nested would be ? Guess full join.
	parts := make([]string, len(c.Path))
	for i, p := range c.Path {
		parts[i] = fmt.Sprintf("%v", p)
	}
	return strings.Join(parts, ".")
}

func nodeScalarString(n *yaml.Node) string {
	if n == nil { return "" }
	if n.Kind == yaml.ScalarNode { return n.Value }
	return nodeStringValue(n)
}

func mergeMapsShallow(dst, src *yaml.Node) {
	for i := 0; i+1 < len(src.Content); i += 2 {
		k := src.Content[i]
		v := src.Content[i+1]
		if idx, _, _ := findMapEntry(dst, k.Value); idx >= 0 {
			dst.Content[idx] = cloneNode(v)
		} else {
			dst.Content = append(dst.Content, cloneNode(k), cloneNode(v))
		}
	}
}

func mergeMapsDeep(dst, src *yaml.Node) {
	for i := 0; i+1 < len(src.Content); i += 2 {
		k := src.Content[i]
		v := src.Content[i+1]
		if idx, _, existing := findMapEntry(dst, k.Value); idx >= 0 {
			ev := effectiveNode(existing)
			sv := effectiveNode(v)
			if ev.Kind == yaml.MappingNode && sv.Kind == yaml.MappingNode {
				// merge into existing clone? dst is already a clone, merge in place
				mergeMapsDeep(ev, sv)
				// if existing was alias, need replace? keep
				if existing.Kind == yaml.AliasNode {
					dst.Content[idx] = ev
				}
			} else {
				dst.Content[idx] = cloneNode(v)
			}
		} else {
			dst.Content = append(dst.Content, cloneNode(k), cloneNode(v))
		}
	}
}

func subtractNodes(l, r *Candidate) (*yaml.Node, error) {
	ln := effectiveNode(l.Node)
	rn := effectiveNode(r.Node)
	if ln.Tag == "!!timestamp" && rn.Tag == "!!str" {
		t, err := parseTimeValue(ln.Value)
		if err != nil { return nil, err }
		d, err := time.ParseDuration(rn.Value)
		if err != nil { return nil, fmt.Errorf("unable to parse duration [%s]: %v", rn.Value, err) }
		return scalarNode("!!timestamp", t.Add(-d).Format(time.RFC3339)), nil
	}
	if ln.Tag == "!!timestamp" && rn.Tag == "!!timestamp" {
		lt, _ := parseTimeValue(ln.Value)
		rt, _ := parseTimeValue(rn.Value)
		return strNode(lt.Sub(rt).String()), nil
	}
	if ln.Tag == "!!str" || rn.Tag == "!!str" {
		if ln.Tag == "!!str" && rn.Tag == "!!str" {
			return nil, fmt.Errorf("strings cannot be subtracted")
		}
		// mimic: !!int cannot be added to !!str (when lhs int rhs str)
		return nil, fmt.Errorf("%s cannot be added to %s", ln.Tag, rn.Tag)
	}
	if ln.Kind == yaml.MappingNode || rn.Kind == yaml.MappingNode {
		return nil, fmt.Errorf("maps not yet supported for subtraction")
	}
	if ln.Kind == yaml.SequenceNode {
		if rn.Kind != yaml.SequenceNode {
			return nil, fmt.Errorf("%s (%s) cannot be subtracted from !!seq", rn.Tag, pathLast(r))
		}
		res := cloneNode(ln)
		var filtered []*yaml.Node
		for _, el := range res.Content {
			found := false
			for _, rel := range rn.Content {
				if deepEqualNode(el, rel) { found = true; break }
			}
			if !found { filtered = append(filtered, el) }
		}
		res.Content = filtered
		return res, nil
	}
	if isNumberTag(ln.Tag) && isNumberTag(rn.Tag) {
		return arithmeticResult("-", ln, rn)
	}
	return nil, fmt.Errorf("%s cannot be subtracted from %s", rn.Tag, ln.Tag)
}

func multiplyNodes(l, r *Candidate) (*yaml.Node, error) {
	ln := effectiveNode(l.Node)
	rn := effectiveNode(r.Node)
	if ln.Tag == "!!null" {
		return cloneNode(rn), nil
	}
	if rn.Tag == "!!null" {
		return cloneNode(ln), nil
	}
	if ln.Kind == yaml.MappingNode && rn.Kind == yaml.MappingNode {
		res := cloneNode(ln)
		mergeMapsDeep(res, rn)
		return res, nil
	}
	// string repeat
	if ln.Tag == "!!str" && rn.Tag == "!!int" {
		cnt, _, err := parseIntValue(rn.Value)
		if err != nil { return nil, err }
		if cnt < 0 { cnt = 0 }
		return strNode(strings.Repeat(ln.Value, int(cnt))), nil
	}
	if rn.Tag == "!!str" && ln.Tag == "!!int" {
		cnt, _, err := parseIntValue(ln.Value)
		if err != nil { return nil, err }
		if cnt < 0 { cnt = 0 }
		return strNode(strings.Repeat(rn.Value, int(cnt))), nil
	}
	if isNumberTag(ln.Tag) && isNumberTag(rn.Tag) {
		return arithmeticResult("*", ln, rn)
	}
	return nil, fmt.Errorf("cannot multiply %s with %s", ln.Tag, rn.Tag)
}

func divideNodes(l, r *Candidate) (*yaml.Node, error) {
	ln := effectiveNode(l.Node)
	rn := effectiveNode(r.Node)
	if ln.Tag == "!!str" && rn.Tag == "!!str" {
		parts := strings.Split(ln.Value, rn.Value)
		seq := &yaml.Node{Kind: yaml.SequenceNode, Tag: "!!seq"}
		for _, p := range parts { seq.Content = append(seq.Content, strNode(p)) }
		return seq, nil
	}
	if isNumberTag(ln.Tag) && isNumberTag(rn.Tag) {
		return arithmeticResult("/", ln, rn)
	}
	// error format: !!int cannot be divided by !!str / !!str cannot be divided by !!int
	return nil, fmt.Errorf("%s cannot be divided by %s", ln.Tag, rn.Tag)
}

func moduloNodes(l, r *Candidate) (*yaml.Node, error) {
	ln := effectiveNode(l.Node)
	rn := effectiveNode(r.Node)
	if isNumberTag(ln.Tag) && isNumberTag(rn.Tag) {
		// check zero
		rf, _ := parseFloatValue(normaliseNumStr(rn.Value))
		if rf == 0 {
			return nil, fmt.Errorf("cannot modulo by 0")
		}
		return arithmeticResult("%", ln, rn)
	}
	return nil, fmt.Errorf("cannot modulo %s by %s", ln.Tag, rn.Tag)
}

func arithmeticResult(op string, ln, rn *yaml.Node) (*yaml.Node, error) {
	// determine int vs float
	if op != "/" && ln.Tag == "!!int" && rn.Tag == "!!int" {
		li, lformat, err := parseIntValue(ln.Value)
		if err != nil { return nil, err }
		ri, _, err := parseIntValue(rn.Value)
		if err != nil { return nil, err }
		var res int64
		switch op {
		case "+": res = li + ri
		case "-": res = li - ri
		case "*": res = li * ri
		case "%": res = li % ri
		}
		return scalarNode("!!int", formatIntWithFormat(res, lformat)), nil
	}
	lf, err := parseFloatValue(normaliseNumStr(ln.Value))
	if err != nil { return nil, err }
	rf, err := parseFloatValue(normaliseNumStr(rn.Value))
	if err != nil { return nil, err }
	var res float64
	switch op {
	case "+": res = lf + rf
	case "-": res = lf - rf
	case "*": res = lf * rf
	case "/": res = lf / rf
	case "%": res = math.Mod(lf, rf)
	}
	return scalarNode("!!float", formatFloat(res)), nil
}

var _ = strconv.Itoa
EOF
"}

{"command":"cat > assign.go <<'EOF'
package main

import (
	"fmt"
	"strings"

	"gopkg.in/yaml.v3"
)

func evalAssign(ast *AST, ctx *EvalContext) ([]*Candidate, error) {
	switch ast.Op {
	case "/=":
		return nil, fmt.Errorf("'/' expects 2 args but there is 1")
	case "%=":
		return nil, fmt.Errorf("'%%' expects 2 args but there is 1")
	case "//=":
		return nil, fmt.Errorf("'//' expects 2 args but there is 1")
	}
	targets, err := evalAssignTarget(ast.L, ctx)
	if err != nil {
		return nil, err
	}
	if len(targets) == 0 {
		// Still need to return something? Original for scalar traversal assigning returns original doc (lead?) If no targets, e.g., .a.b =5 where a is scalar, returns document.
		// Return original candidates as leads
		var out []*Candidate
		for _, c := range ctx.Candidates {
			out = append(out, c)
		}
		return out, nil
	}
	// leaders collection
	seen := make(map[*yaml.Node]bool)
	var leads []*Candidate
	addLead := func(t *Candidate) {
		lead := leadOf(t)
		if lead == nil || lead.Node == nil {
			return
		}
		if seen[lead.Node] {
			return
		}
		seen[lead.Node] = true
		leads = append(leads, lead)
	}
	if ast.Op == "=" {
		rhs, err := evalAST(ast.R, ctx)
		if err != nil {
			return nil, err
		}
		for _, t := range targets {
			addLead(t)
			if t.Pseudo != "" {
				if len(rhs) > 0 {
					setPseudo(t, rhs[0])
				}
				continue
			}
			for _, rv := range rhs {
				replaceCandidateNode(t, rv.Node)
			}
		}
		if len(leads) == 0 {
			leads = append(leads, targets[0])
		}
		return leads, nil
	}
	if ast.Op == "|=" {
		for _, t := range targets {
			addLead(t)
			if t.Pseudo != "" {
				// pseudo update: e.g., ??? RHS evaluated against pseudo candidate? Original .a style |= ??? uncommon. Evaluate RHS on target candidate context
				tc := t.Target
				if tc == nil { tc = t }
				res, err := evalAST(ast.R, ctx.withCandidates([]*Candidate{tc.cloneShallow()}))
				if err != nil { return nil, err }
				if len(res) > 0 {
					setPseudo(t, res[0])
				}
				continue
			}
			tc := t.cloneShallow()
			tc.Lead = tc
			res, err := evalAST(ast.R, ctx.withCandidates([]*Candidate{tc}))
			if err != nil {
				return nil, err
			}
			if len(res) == 0 {
				continue
			}
			// If result is same node as target, in-place already done
			if res[0].Node == t.Node {
				continue
			}
			// If result's node is ancestor? Actually del returns lead = tc (same node) handled.
			// If multiple results, take first? yq may take ... We'll replace with first.
			replaceCandidateNode(t, res[0].Node)
		}
		if len(leads) == 0 {
			leads = append(leads, targets[0])
		}
		return leads, nil
	}
	// compound += -= *=
	rhs, err := evalAST(ast.R, ctx)
	if err != nil {
		return nil, err
	}
	op := strings.TrimSuffix(ast.Op, "=")
	for _, t := range targets {
		addLead(t)
		if t.Pseudo != "" {
			continue
		}
		for _, rv := range rhs {
			resNode, err := applyBinaryOp(op, t, rv)
			if err != nil {
				return nil, err
			}
			replaceCandidateNode(t, resNode)
		}
	}
	if len(leads) == 0 && len(targets) > 0 {
		leads = append(leads, targets[0])
	}
	return leads, nil
}

func leadOf(c *Candidate) *Candidate {
	if c == nil {
		return nil
	}
	if c.Lead != nil {
		return c.Lead
	}
	return c
}

func replaceCandidateNode(t *Candidate, newNode *yaml.Node) {
	if t == nil || t.Node == nil || newNode == nil {
		return
	}
	cl := cloneNode(newNode)
	// Preserve? Replace entire struct
	old := t.Node
	*old = *cl
}

func setPseudo(t *Candidate, rhs *Candidate) {
	if t == nil || t.Target == nil || rhs == nil || rhs.Node == nil {
		return
	}
	target := t.Target.Node
	val := effectiveNode(rhs.Node)
	strVal := ""
	if val != nil {
		strVal = val.Value
	}
	switch t.Pseudo {
	case "style":
		target.Style = styleFromString(strVal)
	case "tag":
		target.Tag = strVal
	case "anchor":
		target.Anchor = strVal
	case "alias":
		// convert to alias node
		target.Kind = yaml.AliasNode
		target.Value = strVal
		target.Tag = ""
		target.Style = 0
		target.Content = nil
		// create dummy alias target with anchor so encoder emits *strVal
		target.Alias = &yaml.Node{Kind: yaml.ScalarNode, Tag: "!!str", Value: "", Anchor: strVal}
	case "headComment":
		target.HeadComment = cleanComment(strVal)
	case "lineComment":
		target.LineComment = cleanComment(strVal)
	case "footComment":
		target.FootComment = cleanComment(strVal)
	}
}

func cleanComment(s string) string {
	s = strings.TrimSpace(s)
	s = strings.TrimPrefix(s, "#")
	s = strings.TrimSpace(s)
	return s
}

func styleFromString(s string) yaml.Style {
	switch s {
	case "":
		return 0
	case "double":
		return yaml.DoubleQuotedStyle
	case "single":
		return yaml.SingleQuotedStyle
	case "literal":
		return yaml.LiteralStyle
	case "folded":
		return yaml.FoldedStyle
	case "flow":
		return yaml.FlowStyle
	case "tagged":
		return yaml.TaggedStyle
	}
	return 0
}
func styleToString(st yaml.Style) string {
	// yq style returns: "" for 0, "double","single","literal","folded","flow","tagged"?
	if st&yaml.FlowStyle != 0 {
		return "flow"
	}
	switch st {
	case yaml.DoubleQuotedStyle:
		return "double"
	case yaml.SingleQuotedStyle:
		return "single"
	case yaml.LiteralStyle:
		return "literal"
	case yaml.FoldedStyle:
		return "folded"
	case yaml.TaggedStyle:
		return "tagged"
	}
	// flow bit may combine? yaml styles are bits; check separately
	if st == yaml.FlowStyle {
		return "flow"
	}
	return ""
}
EOF
"}

