	case "//=":
		return nil, fmt.Errorf("'//' expects 2 args but there is 1")
	}
	targets, err := evalAssignTarget(ast.L, ctx)
	if err != nil {
		return nil, err
	}
	if len(targets) == 0 {
		// Still need to return something? Original for scalar traversal assigning returns original doc (lead?) If no targets, e.g., .a.b =5 where a is scalar, returns document.
		// Return original candidates as leads
		var out []*Candidate
		for _, c := range ctx.Candidates {
			out = append(out, c)
		}
		return out, nil
	}
	// leaders collection
	seen := make(map[*yaml.Node]bool)
	var leads []*Candidate
	addLead := func(t *Candidate) {
		lead := leadOf(t)
		if lead == nil || lead.Node == nil {
			return
		}
		if seen[lead.Node] {
			return
		}
		seen[lead.Node] = true
		leads = append(leads, lead)
	}
	if ast.Op == "=" {
		rhs, err := evalAST(ast.R, ctx)
		if err != nil {
			return nil, err
		}
		for _, t := range targets {
			addLead(t)
			if t.Pseudo != "" {
				if len(rhs) > 0 {
					setPseudo(t, rhs[0])
				}
				continue
			}
			for _, rv := range rhs {
				replaceCandidateNode(t, rv.Node)
			}
		}
		if len(leads) == 0 {
			leads = append(leads, targets[0])
		}
		return leads, nil
	}
	if ast.Op == "|=" {
		for _, t := range targets {
			addLead(t)
			if t.Pseudo != "" {
				// pseudo update: e.g., ??? RHS evaluated against pseudo candidate? Original .a style |= ??? uncommon. Evaluate RHS on target candidate context
				tc := t.Target
				if tc == nil { tc = t }
				res, err := evalAST(ast.R, ctx.withCandidates([]*Candidate{tc.cloneShallow()}))
				if err != nil { return nil, err }
				if len(res) > 0 {
					setPseudo(t, res[0])
				}
				continue
			}
			tc := t.cloneShallow()
			tc.Lead = tc
			res, err := evalAST(ast.R, ctx.withCandidates([]*Candidate{tc}))
			if err != nil {
				return nil, err
			}
			if len(res) == 0 {
				continue
			}
			// If result is same node as target, in-place already done
			if res[0].Node == t.Node {
				continue
			}
			// If result's node is ancestor? Actually del returns lead = tc (same node) handled.
			// If multiple results, take first? yq may take ... We'll replace with first.
			replaceCandidateNode(t, res[0].Node)
		}
		if len(leads) == 0 {
			leads = append(leads, targets[0])
		}
		return leads, nil
	}
	// compound += -= *=
	rhs, err := evalAST(ast.R, ctx)
	if err != nil {
		return nil, err
	}
	op := strings.TrimSuffix(ast.Op, "=")
	for _, t := range targets {
		addLead(t)
		if t.Pseudo != "" {
			continue
		}
		for _, rv := range rhs {
			resNode, err := applyBinaryOp(op, t, rv)
			if err != nil {
				return nil, err
			}
			replaceCandidateNode(t, resNode)
		}
	}
	if len(leads) == 0 && len(targets) > 0 {
		leads = append(leads, targets[0])
	}
	return leads, nil
}

func leadOf(c *Candidate) *Candidate {
	if c == nil {
		return nil
	}
	if c.Lead != nil {
		return c.Lead
	}
	return c
}

func replaceCandidateNode(t *Candidate, newNode *yaml.Node) {
	if t == nil || t.Node == nil || newNode == nil {
		return
	}
	cl := cloneNode(newNode)
	// Preserve? Replace entire struct
	old := t.Node
	*old = *cl
}

func setPseudo(t *Candidate, rhs *Candidate) {
	if t == nil || t.Target == nil || rhs == nil || rhs.Node == nil {
		return
	}
	target := t.Target.Node
	val := effectiveNode(rhs.Node)
	strVal := ""
	if val != nil {
		strVal = val.Value
	}
	switch t.Pseudo {
	case "style":
		target.Style = styleFromString(strVal)
	case "tag":
		target.Tag = strVal
	case "anchor":
		target.Anchor = strVal
	case "alias":
		// convert to alias node
		target.Kind = yaml.AliasNode
		target.Value = strVal
		target.Tag = ""
		target.Style = 0
		target.Content = nil
		// create dummy alias target with anchor so encoder emits *strVal
		target.Alias = &yaml.Node{Kind: yaml.ScalarNode, Tag: "!!str", Value: "", Anchor: strVal}
	case "headComment":
		target.HeadComment = cleanComment(strVal)
	case "lineComment":
		target.LineComment = cleanComment(strVal)
	case "footComment":
		target.FootComment = cleanComment(strVal)
	}
}

func cleanComment(s string) string {
	s = strings.TrimSpace(s)
	s = strings.TrimPrefix(s, "#")
	s = strings.TrimSpace(s)
	return s
}

func styleFromString(s string) yaml.Style {
	switch s {
	case "":
		return 0
	case "double":
		return yaml.DoubleQuotedStyle
	case "single":
		return yaml.SingleQuotedStyle
	case "literal":
		return yaml.LiteralStyle
	case "folded":
		return yaml.FoldedStyle
	case "flow":
		return yaml.FlowStyle
	case "tagged":
		return yaml.TaggedStyle
	}
	return 0
}
func styleToString(st yaml.Style) string {
	// yq style returns: "" for 0, "double","single","literal","folded","flow","tagged"?
	if st&yaml.FlowStyle != 0 {
		return "flow"
	}
	switch st {
	case yaml.DoubleQuotedStyle:
		return "double"
	case yaml.SingleQuotedStyle:
		return "single"
	case yaml.LiteralStyle:
		return "literal"
	case yaml.FoldedStyle:
		return "folded"
	case yaml.TaggedStyle:
		return "tagged"
	}
	// flow bit may combine? yaml styles are bits; check separately
	if st == yaml.FlowStyle {
		return "flow"
	}
	return ""
}
