		vi, _, vv := findMapEntry(en, "value")
		if vi<0 { return nil, fmt.Errorf("expected to find one 'value' entry but found 0 in position %d", pos) }
		m.Content = append(m.Content, cloneNode(kv), cloneNode(vv))
		// Note kv here is key node? findMapEntry returns idx,k,v so kv variable above misnamed: we used kv as key? Wait re-evaluate: ki is idx, second return is k node, third is v. We captured _, kv as ??? Actually code: ki, _, kv := findMapEntry(en,"key") => kv is value node of "key" entry, which is actual key. Good.
		_ = vi; _ = vv
		// But vv is value of "value" entry, correct.
		// However we appended cloneNode(kv), cloneNode(vv) - correct.
	}
	return []*Candidate{resultCand(c, m)}, nil
