func funcPickOmit(ast *AST, ctx *EvalContext, c *Candidate, isPick bool) ([]*Candidate, error) {
	node := effectiveNode(c.Node)
	args, err := evalArg(ast, ctx, c, 0); if err != nil { return nil, err }
	if len(args)==0 { return []*Candidate{resultCand(c, cloneNode(node))}, nil }
	argNode := effectiveNode(args[0].Node)
	var keys []string
	var indices []int
	isIndex := false
	if argNode != nil && argNode.Kind == yaml.SequenceNode {
		for _, el := range argNode.Content {
			en := effectiveNode(el)
			keys = append(keys, en.Value)
			if iv, err := strconv.Atoi(en.Value); err==nil { indices = append(indices, iv); isIndex=true }
		}
	}
	if node == nil { return []*Candidate{c}, nil }
	if node.Kind == yaml.MappingNode {
		if isPick {
			m := &yaml.Node{Kind: yaml.MappingNode, Tag: "!!map", Style: node.Style}
			for _, k := range keys {
				if idx, kn, v := findMapEntry(node, k); idx>=0 { m.Content = append(m.Content, cloneNode(kn), cloneNode(v)) }
			}
			return []*Candidate{resultCand(c, m)}, nil
		} else {
			m := cloneNode(node)
			var content []*yaml.Node
			for i:=0;i+1<len(m.Content);i+=2 {
				if !containsStr(keys, m.Content[i].Value) { content = append(content, m.Content[i], m.Content[i+1]) }
			}
			m.Content = content
			return []*Candidate{resultCand(c, m)}, nil
		}
	}
	if node.Kind == yaml.SequenceNode {
		if isPick {
			seq := &yaml.Node{Kind: yaml.SequenceNode, Tag: "!!seq", Style: node.Style}
			for _, iv := range indices { if iv>=0 && iv < len(node.Content) { seq.Content = append(seq.Content, cloneNode(node.Content[iv])) } }
			_ = isIndex
			return []*Candidate{resultCand(c, seq)}, nil
		} else {
			seq := cloneNode(node)
			var content []*yaml.Node
			for i, el := range node.Content { if !containsInt(indices, i) { content = append(content, el) } }
			seq.Content = content
			return []*Candidate{resultCand(c, seq)}, nil
		}
	}
	return []*Candidate{c}, nil
}
func containsStr(s []string, v string) bool { for _,x:=range s{if x==v{return true}}; return false }
func containsInt(s []int, v int) bool { for _,x:=range s{if x==v{return true}}; return false }
func funcDel(ast *AST, ctx *EvalContext, c *Candidate) ([]*Candidate, error) {
	if len(ast.Args)==0 { return nil, fmt.Errorf("'del' expects 1 arg but received none") }
	// evaluate arg as assign target? Use evalAST to get candidates (they have parents)
	targets, err := evalAST(ast.Args[0], ctx.withCandidates([]*Candidate{c}))
	if err != nil { return nil, err }
	// Delete in reverse for sequences: sort targets by parent and index descending for seq parents
	// Perform deletion via node identity search each time
	// Collect leaders
	seen := make(map[*yaml.Node]bool)
	var leads []*Candidate
	for _, t := range targets {
		lead := leadOf(t)
		if lead != nil && lead.Node != nil && !seen[lead.Node] { seen[lead.Node]=true; leads = append(leads, lead) }
		deleteCandidate(t)
	}
	if len(leads)==0 { leads = append(leads, c) }
	return leads, nil
}
func deleteCandidate(t *Candidate) {
	if t == nil || t.Parent == nil || t.Node == nil { return }
	parent := t.Parent
	// find node index in parent content
	for i, el := range parent.Content {
		if el == t.Node {
			if parent.Kind == yaml.MappingNode {
				// remove pair: if i is value (odd), remove i-1,i; if key, remove i,i+1
				if i%2==1 {
					parent.Content = append(parent.Content[:i-1], parent.Content[i+1:]...)
				} else {
					if i+1 < len(parent.Content) { parent.Content = append(parent.Content[:i], parent.Content[i+2:]...) }
				}
			} else {
				parent.Content = append(parent.Content[:i], parent.Content[i+1:]...)
			}
			return
		}
	}
}
func funcDelPaths(ast *AST, ctx *EvalContext, c *Candidate) ([]*Candidate, error) {
	args, err := evalArg(ast, ctx, c, 0); if err != nil { return nil, err }
	if len(args)==0 { return []*Candidate{c}, nil }
	argNode := effectiveNode(args[0].Node)
	if argNode == nil || argNode.Kind != yaml.SequenceNode { return []*Candidate{c}, nil }
	// each element is a path array
	var targets []*Candidate
	for _, pathNode := range argNode.Content {
		pn := effectiveNode(pathNode)
		if pn.Kind != yaml.SequenceNode { continue }
		// traverse c by path
		current := []*Candidate{c}
		for _, pe := range pn.Content {
			pen := effectiveNode(pe)
			var next []*Candidate
			for _, cur := range current {
				var res []*Candidate; var err error
				if effectiveNode(cur.Node) != nil && effectiveNode(cur.Node).Kind == yaml.SequenceNode {
					iv, _ := strconv.Atoi(pen.Value); res, err = applyIndex(cur, iv, false)
				} else {
					res, err = applyKey(cur, pen.Value, pen, false)
				}
				if err != nil { return nil, err }
				next = append(next, res...)
			}
			current = next
		}
		targets = append(targets, current...)
	}
	for _, t := range targets { deleteCandidate(t) }
	return []*Candidate{c}, nil
}
func funcSetPath(ast *AST, ctx *EvalContext, c *Candidate) ([]*Candidate, error) {
	if len(ast.Args) < 2 {
		// original expects 1 arg in function definition but semantically needs 2; when setpath(["x"]) without value? Probe: it would error? We'll just return c
		// Evaluate path and use nil?
		if len(ast.Args)==0 { return nil, fmt.Errorf("'setpath' expects 1 arg but received none") }
	}
	pathRes, err := evalArg(ast, ctx, c, 0); if err != nil { return nil, err }
	if len(pathRes)==0 { return []*Candidate{c}, nil }
	pathNode := effectiveNode(pathRes[0].Node)
	if pathNode == nil || pathNode.Kind != yaml.SequenceNode { return []*Candidate{c}, nil }
	var path []interface{}
	for _, pe := range pathNode.Content {
		pen := effectiveNode(pe)
		if pen.Tag=="!!int" { if iv,err:=strconv.Atoi(pen.Value); err==nil { path=append(path, iv); continue } }
		path = append(path, pen.Value)
	}
	valRes, err := evalArg(ast, ctx, c, 1); if err != nil { return nil, err }
	if len(valRes)==0 { return []*Candidate{c}, nil }
	// work on cloned? Original setpath modifies candidate in place (returns candidate). Use its node as root.
	// Traverse creating
	current := c
	// Build target candidate via applying path steps with create on c
	// Convert path to steps
	var steps []PathStep
	for _, p := range path {
		switch v:=p.(type) {
		case int: steps = append(steps, PathStep{Type:"dyn", KeyExpr: &AST{Kind: AKLiteral, Node: intNode(int64(v))}})
		default: steps = append(steps, PathStep{Type:"key", Key: fmt.Sprintf("%v", v)})
		}
	}
	targets, err := applySteps([]*Candidate{current}, steps, true)
	if err != nil { return nil, err }
	for _, t := range targets { replaceCandidateNode(t, valRes[0].Node) }
	return []*Candidate{c}, nil
}
func funcExplode(ast *AST, ctx *EvalContext, c *Candidate) ([]*Candidate, error) {
	// arg is evaluated but ignored except maybe side effects? Original explode(.) evaluates '.' and uses that as ??? Actually explode operates on candidate, arg may be ??? We'll ignore.
	node := cloneNode(c.Node)
