func explodeNode(n *yaml.Node) *yaml.Node {
	if n == nil { return nil }
	if n.Kind == yaml.AliasNode && n.Alias != nil {
		return explodeNode(cloneNode(n.Alias))
	}
	res := cloneNode(n)
	res.Anchor = ""
	if res.Kind == yaml.MappingNode {
		// process merge keys
		var newContent []*yaml.Node
		// first collect explicit entries
		// We'll build map: start with merged entries, then explicit overriding? Original explicit wins and position: merged keys appear in place of << ?
		// Approach: iterate entries, when merge, insert merged entries at that position if not already explicit later? Simpler: newContent initially merged, then explicit override in place.
		for i:=0;i+1<len(res.Content);i+=2 {
			k:=res.Content[i]; v:=res.Content[i+1]
			if k.Value == "<<" {
				vExploded := explodeNode(v)
				// v can be map or seq of maps
				var maps []*yaml.Node
				if vExploded.Kind == yaml.MappingNode { maps = append(maps, vExploded) } else if vExploded.Kind == yaml.SequenceNode { for _, el := range vExploded.Content { if effectiveNode(el).Kind==yaml.MappingNode { maps = append(maps, effectiveNode(el)) } else { /* error ignored */ } } }
				for _, m := range maps {
					for j:=0;j+1<len(m.Content);j+=2 {
						mk:=m.Content[j]; mv:=m.Content[j+1]
						if idx,_,_ := findMapEntrySlice(newContent, mk.Value); idx>=0 { newContent[idx]=mv } else { newContent = append(newContent, mk, mv) }
					}
				}
				continue
			}
			ev := explodeNode(v)
			if idx,_,_ := findMapEntrySlice(newContent, k.Value); idx>=0 { newContent[idx]=ev } else { newContent = append(newContent, k, ev) }
		}
		res.Content = newContent
		return res
	}
	if res.Kind == yaml.SequenceNode {
		for i, el := range res.Content { res.Content[i]=explodeNode(el) }
		return res
	}
	return res
}
func findMapEntrySlice(content []*yaml.Node, key string) (int, *yaml.Node, *yaml.Node) {
	for i:=0;i+1<len(content);i+=2 { if content[i].Value==key { return i+1, content[i], content[i+1] } }
	return -1,nil,nil
}
func funcWith(ast *AST, ctx *EvalContext, c *Candidate) ([]*Candidate, error) {
	if len(ast.Args)<2 { return nil, fmt.Errorf("'with' expects 1 arg but received none") }
	targets, err := evalAST(ast.Args[0], ctx.withCandidates([]*Candidate{c}))
	if err != nil { return nil, err }
	for _, t := range targets {
		tc := t.cloneShallow(); tc.Lead = tc
		_, err := evalAST(ast.Args[1], ctx.withCandidates([]*Candidate{tc}))
		if err != nil { return nil, err }
	}
	return []*Candidate{c}, nil
}
