func funcWithDTF(ast *AST, ctx *EvalContext, c *Candidate) ([]*Candidate, error) {
	if len(ast.Args)<2 { return nil, fmt.Errorf("'with_dtf' expects 1 arg but received none") }
	layout, _, err := evalArgString(ast, ctx, c, 0); if err != nil { return nil, err }
	node := effectiveNode(c.Node)
	if node == nil || node.Kind != yaml.ScalarNode { return []*Candidate{c}, nil }
	parsed, err := time.Parse(layout, node.Value)
	if err != nil {
		// If node already timestamp standard, try RFC
		parsed, err = parseTimeValue(node.Value)
		if err != nil { return nil, err }
	}
	tempNode := scalarNode("!!timestamp", parsed.Format(time.RFC3339))
	tempCand := resultCand(c, tempNode)
	res, err := evalAST(ast.Args[1], ctx.withCandidates([]*Candidate{tempCand}))
	if err != nil { return nil, err }
	var out []*Candidate
	for _, r := range res {
		rn := effectiveNode(r.Node)
		if rn != nil && rn.Tag=="!!timestamp" {
			if pt, err := parseTimeValue(rn.Value); err==nil {
				nc := resultCand(c, scalarNode("!!timestamp", pt.Format(layout)))
				out = append(out, nc); continue
			}
		}
		out = append(out, r)
	}
	return out, nil
}
func candidateToStringFromLiteral(ast *AST) string {
