	// simple
	return "'" + strings.ReplaceAll(s, "'", "'\\''") + "'"
}
var _ = utf8.RuneLen
EOF
"}

actions.command:
cat > funcs.go <<'EOF'
package main

import (
	"encoding/base64"
	"fmt"
	"math/rand"
	"net/url"
	"os"
	"os/exec"
	"regexp"
	"sort"
	"strconv"
	"strings"
	"time"
	"unicode/utf8"

	"gopkg.in/yaml.v3"
)

var funcArgCounts = map[string]int{
	"capture": 1, "contains": 1, "del": 1, "delpaths": 1, "error": 1, "explode": 1, "group_by": 1, "has": 1, "join": 1, "load": 1, "load_str": 1, "map": 1, "map_values": 1, "match": 1, "omit": 1, "pick": 1, "select": 1, "sort_by": 1, "sort_keys": 1, "split": 1, "sub": 1, "system": 1, "test": 1, "unique_by": 1, "with_entries": 1, "tz": 1, "setpath": 1, "eval": 1, "collect": 1, "filter": 1,
	"ireduce": 2, "and": 2, "or": 2, "ref": 2, "with": 2, "with_dtf": 2, "delpaths_": 1,
}

func resultCand(like *Candidate, node *yaml.Node) *Candidate {
	nc := candWithNode(like, node)
	// preserve line/col? If node line zero and like node exists, keep? For most scalar funcs original retains? length etc line of result is maybe 0. Keep 0.
	if like != nil && like.FromRoot {
		nc.PrintID = 0
	}
	return nc
}

func evalFunc(ast *AST, ctx *EvalContext) ([]*Candidate, error) {
	name := ast.Name
	// argument count errors for functions requiring args
	if req, ok := funcArgCounts[name]; ok {
		if len(ast.Args) < req {
			// special message forms: most are "expects 1 arg but received none"
			// ireduce/and/or/ref say "expects 2 args but there is 0" when called via AST? Those are usually infix, but keep map distinction
			if name == "ireduce" || name == "and" || name == "or" || name == "ref" {
				return nil, fmt.Errorf("'%s' expects %d args but there is %d", name, req, len(ast.Args))
			}
			if len(ast.Args) == 0 {
				return nil, fmt.Errorf("'%s' expects %d arg but received none", name, req)
			}
		}
	}
	// pseudo properties are handled separately (no candidates iteration changes)
	switch name {
	case "style", "tag", "anchor", "alias", "headComment", "lineComment", "footComment", "head_comment", "line_comment", "foot_comment":
		return evalPseudo(ast, ctx)
	}
	var out []*Candidate
	for _, c := range ctx.Candidates {
		res, err := evalFuncOne(ast, ctx, c)
		if err != nil {
			return nil, err
		}
		out = append(out, res...)
	}
	return out, nil
}

func evalPseudo(ast *AST, ctx *EvalContext) ([]*Candidate, error) {
	name := ast.Name
	// normalize snake to camel for Target pseudo handling in assign (store normalized)
	norm := name
	if norm == "head_comment" { norm = "headComment" }
	if norm == "line_comment" { norm = "lineComment" }
	if norm == "foot_comment" { norm = "footComment" }
	var out []*Candidate
	for _, c := range ctx.Candidates {
		var val string
		n := c.Node
		if n != nil {
			switch norm {
			case "style": val = styleToString(n.Style)
			case "tag": val = n.Tag
			case "anchor": val = n.Anchor
			case "alias":
				if n.Kind == yaml.AliasNode { val = n.Value }
			case "headComment": val = n.HeadComment
			case "lineComment": val = n.LineComment
			case "footComment": val = n.FootComment
			}
		}
		nc := candWithNode(c, strNode(val))
		nc.Pseudo = norm
		// target is input candidate (original)
		nc.Target = c
		// Path etc keep from c (candWithNode clone)
		out = append(out, nc)
	}
	return out, nil
}

// helper to evaluate arg against single candidate
func evalArg(ast *AST, ctx *EvalContext, c *Candidate, idx int) ([]*Candidate, error) {
	if idx >= len(ast.Args) {
		return nil, nil
	}
	return evalAST(ast.Args[idx], ctx.withCandidates([]*Candidate{c}))
}
func evalArgString(ast *AST, ctx *EvalContext, c *Candidate, idx int) (string, *Candidate, error) {
	res, err := evalArg(ast, ctx, c, idx)
	if err != nil { return "", nil, err }
	if len(res) == 0 { return "", nil, nil }
	return candidateToString(res[0]), res[0], nil
}

func evalFuncOne(ast *AST, ctx *EvalContext, c *Candidate) ([]*Candidate, error) {
	name := ast.Name
	node := effectiveNode(c.Node)
	switch name {
	case "root":
		rc := c.cloneShallow()
		if c.RootNode != nil { rc.Node = c.RootNode }
		rc.Parent = nil
		rc.Path = nil
		rc.Lead = rc
		rc.FromRoot = true
		return []*Candidate{rc}, nil
	case "path":
		seq := &yaml.Node{Kind: yaml.SequenceNode, Tag: "!!seq"}
		for _, p := range c.Path {
			switch v := p.(type) {
			case int: seq.Content = append(seq.Content, intNode(int64(v)))
			case int64: seq.Content = append(seq.Content, intNode(v))
			default: seq.Content = append(seq.Content, strNode(fmt.Sprintf("%v", v)))
			}
		}
		return []*Candidate{resultCand(c, seq)}, nil
	case "parent":
		if c.Parent == nil {
			return nil, nil
		}
		pc := c.cloneShallow()
		pc.Node = c.Parent
		pc.Parent = nil
		// drop last path
		if len(c.Path) > 0 { pc.Path = c.Path[:len(c.Path)-1] } else { pc.Path = nil }
		return []*Candidate{pc}, nil
	case "key":
		if c.Parent == nil { return nil, nil }
		if c.Parent.Kind == yaml.MappingNode {
			if c.IsKey {
				return []*Candidate{resultCand(c, strNode(c.Node.Value))}, nil
			}
			// value candidate: key at Index-1
			if c.Index-1 >= 0 && c.Index-1 < len(c.Parent.Content) {
				kn := c.Parent.Content[c.Index-1]
				return []*Candidate{resultCand(c, cloneNode(kn))}, nil
			}
			return nil, nil
		}
		if c.Parent.Kind == yaml.SequenceNode {
			return []*Candidate{resultCand(c, intNode(int64(c.Index)))}, nil
		}
		return nil, nil
	case "documentIndex", "document_index", "di":
		return []*Candidate{resultCand(c, intNode(int64(c.DocIndex)))}, nil
	case "fileIndex", "fi":
		return []*Candidate{resultCand(c, intNode(int64(c.FileIdx)))}, nil
	case "filename", "fileName", "file_name":
		fn := c.Filename
		if fn == "" { fn = "-" }
		return []*Candidate{resultCand(c, strNode(fn))}, nil
	case "line":
		ln := 0
		if c.Node != nil { ln = c.Node.Line }
		return []*Candidate{resultCand(c, intNode(int64(ln)))}, nil
	case "column":
		col := 0
		if c.Node != nil { col = c.Node.Column }
		return []*Candidate{resultCand(c, intNode(int64(col)))}, nil
	case "length":
		var l int
		if node == nil { l = 0 } else if node.Kind == yaml.MappingNode { l = len(node.Content)/2 } else if node.Kind == yaml.SequenceNode { l = len(node.Content) } else if node.Tag == "!!null" { l = 0 } else { l = len(node.Value) }
		return []*Candidate{resultCand(c, intNode(int64(l)))}, nil
	case "kind":
		return []*Candidate{resultCand(c, strNode(kindName(node)))}, nil
	case "type", "tag":
		// type and tag both return tag when used as function; tag pseudo earlier handled, but this is a function call? We already routed tag to pseudo. However bare 'type' should be tag.
		// This case unreachable for tag due pseudo routing; for type:
		t := ""
		if node != nil { t = node.Tag }
		return []*Candidate{resultCand(c, strNode(t))}, nil
	case "keys":
		if node == nil || (node.Kind != yaml.MappingNode && node.Kind != yaml.SequenceNode) {
			tag := "!!null"
			if node != nil { tag = node.Tag }
			return nil, fmt.Errorf("cannot get keys of %s, keys only works for maps and arrays", tag)
		}
		seq := &yaml.Node{Kind: yaml.SequenceNode, Tag: "!!seq"}
		if node.Kind == yaml.MappingNode {
			for i := 0; i+1 < len(node.Content); i+=2 { seq.Content = append(seq.Content, cloneNode(node.Content[i])) }
		} else {
			for i := range node.Content { seq.Content = append(seq.Content, intNode(int64(i))) }
		}
		return []*Candidate{resultCand(c, seq)}, nil
	case "has":
		argStr, argCand, err := evalArgString(ast, ctx, c, 0)
		if err != nil { return nil, err }
		found := false
		if node != nil && node.Kind == yaml.MappingNode {
			idx, _, _ := findMapEntry(node, argStr); found = idx >= 0
		} else if node != nil && node.Kind == yaml.SequenceNode {
			if argCand != nil {
				if iv, err := strconv.Atoi(candidateToString(argCand)); err == nil && iv >= 0 && iv < len(node.Content) { found = true }
			}
		} else {
			found = false
		}
		return []*Candidate{resultCand(c, boolNode(found))}, nil
	case "contains":
		args, err := evalArg(ast, ctx, c, 0)
		if err != nil { return nil, err }
		if len(args)==0 { return []*Candidate{resultCand(c, boolNode(false))}, nil }
		res := nodeContains(node, effectiveNode(args[0].Node))
		// special error if lhs map and arg is scalar string: original contains("ell") on map error "!!str cannot check contained in !!map"
		if node != nil && node.Kind == yaml.MappingNode && effectiveNode(args[0].Node).Kind == yaml.ScalarNode {
			return nil, fmt.Errorf("%s cannot check contained in !!map", effectiveNode(args[0].Node).Tag)
		}
		return []*Candidate{resultCand(c, boolNode(res))}, nil
	case "not":
		return []*Candidate{resultCand(c, boolNode(!truthy(node)))}, nil
	case "sort":
		if node == nil { return []*Candidate{c}, nil }
		if node.Kind == yaml.MappingNode {
			sortMapEntries(node)
			return []*Candidate{c}, nil
		}
		if node.Kind == yaml.SequenceNode {
			sort.SliceStable(node.Content, func(i,j int) bool {
				cmp, _ := compareNodes(node.Content[i], node.Content[j]); return cmp < 0
			})
			return []*Candidate{c}, nil
		}
		return []*Candidate{c}, nil
	case "sort_keys":
		// arg ignored (but evaluate? original seemed to ignore errors from path?) If arg present, we evaluate it to mimic side errors? sort_keys(.a) on map gave sorted, .a evaluation would be fine; sort_by on map errored differently, so sort_keys likely does NOT evaluate argument as expression on candidate, it uses it as something else. We'll just sort top map.
		if node != nil && node.Kind == yaml.MappingNode { sortMapEntries(node) }
		if node != nil && node.Kind == yaml.SequenceNode {
			// sort each map inside?
			for _, el := range node.Content { if effectiveNode(el).Kind == yaml.MappingNode { sortMapEntries(effectiveNode(el)) } }
		}
		return []*Candidate{c}, nil
	case "sort_by":
		return funcSortBy(ast, ctx, c)
	case "reverse":
		if node == nil || node.Kind != yaml.SequenceNode {
			tag := ""; if node != nil { tag = node.Tag }
			return nil, fmt.Errorf("node at path %s is not an array (it's a %s)", formatPathBracket(c.Path), tag)
		}
		for i,j := 0, len(node.Content)-1; i<j; i,j = i+1, j-1 { node.Content[i], node.Content[j] = node.Content[j], node.Content[i] }
		return []*Candidate{c}, nil
	case "shuffle":
		if node == nil || node.Kind != yaml.SequenceNode {
			tag := ""; if node != nil { tag = node.Tag }
			return nil, fmt.Errorf("node at path %s is not an array (it's a %s)", formatPathBracket(c.Path), tag)
		}
		rand.Shuffle(len(node.Content), func(i,j int){ node.Content[i], node.Content[j] = node.Content[j], node.Content[i] })
		return []*Candidate{c}, nil
	case "unique":
		if node == nil || node.Kind != yaml.SequenceNode { return nil, fmt.Errorf("only arrays are supported for unique") }
		var uniq []*yaml.Node
		for _, el := range node.Content {
			found:=false; for _, u := range uniq { if deepEqualNode(el,u){found=true;break} }
			if !found { uniq = append(uniq, el) }
		}
		node.Content = uniq
		return []*Candidate{c}, nil
	case "unique_by":
		if node == nil || node.Kind != yaml.SequenceNode { return nil, fmt.Errorf("only arrays are supported for unique") }
		var uniq []*yaml.Node
		var keys []*yaml.Node
		for _, el := range node.Content {
			elCand := c.child(el, node, indexOfNode(node, el), pathElemForIndex(node, el))
			kres, err := evalAST(ast.Args[0], ctx.withCandidates([]*Candidate{elCand}))
			if err != nil { return nil, err }
			var kn *yaml.Node; if len(kres)>0 { kn = kres[0].Node } else { kn = nullNode() }
			found:=false; for _, u := range keys { if deepEqualNode(kn,u){found=true;break} }
			if !found { keys = append(keys, kn); uniq = append(uniq, el) }
		}
		node.Content = uniq
		return []*Candidate{c}, nil
	case "group_by":
		if node == nil || node.Kind != yaml.SequenceNode { return nil, fmt.Errorf("only arrays are supported for group by") }
		type group struct { key *yaml.Node; elems []*yaml.Node }
		var groups []*group
		for idx, el := range node.Content {
			elCand := c.child(el, node, idx, idx)
			kres, err := evalAST(ast.Args[0], ctx.withCandidates([]*Candidate{elCand}))
			if err != nil { return nil, err }
			var kn *yaml.Node; if len(kres)>0 { kn = kres[0].Node } else { kn = nullNode() }
			var g *group
			for _, gg := range groups { if deepEqualNode(kn, gg.key){ g=gg; break } }
			if g==nil { g=&group{key:kn}; groups=append(groups,g) }
			g.elems = append(g.elems, el)
		}
		outer := &yaml.Node{Kind: yaml.SequenceNode, Tag: "!!seq"}
		for _, g := range groups {
			inner := &yaml.Node{Kind: yaml.SequenceNode, Tag: "!!seq", Content: g.elems}
			outer.Content = append(outer.Content, inner)
		}
		return []*Candidate{resultCand(c, outer)}, nil
	case "flatten":
		if node == nil || node.Kind != yaml.SequenceNode { return nil, fmt.Errorf("only arrays are supported for flatten") }
		depth := -1
		if len(ast.Args)>0 {
			s, _, err := evalArgString(ast, ctx, c, 0); if err != nil { return nil, err }
			if iv, err := strconv.Atoi(strings.TrimSpace(s)); err == nil { depth = iv }
		}
		res := cloneNode(node)
		res.Content = flattenContent(node.Content, depth)
		return []*Candidate{resultCand(c, res)}, nil
	case "min", "max":
		if node == nil { return []*Candidate{resultCand(c, nullNode())}, nil }
		var elems []*yaml.Node
		if node.Kind == yaml.SequenceNode { elems = node.Content } else if node.Kind == yaml.MappingNode { for i:=1;i<len(node.Content);i+=2{elems=append(elems,node.Content[i])} } else { elems = []*yaml.Node{node} }
		if len(elems)==0 { return []*Candidate{resultCand(c, nullNode())}, nil }
		best := elems[0]
		for _, el := range elems[1:] {
			cmp,_ := compareNodes(el,best)
			if name=="min" && cmp<0 { best=el }
			if name=="max" && cmp>0 { best=el }
		}
		return []*Candidate{resultCand(c, cloneNode(best))}, nil
	case "any", "all":
		if node == nil || node.Kind != yaml.SequenceNode { 
			tag:=""; if node!=nil{tag=node.Tag}; return nil, fmt.Errorf("%s only supports arrays, was %s", name, tag)
		}
		if name=="any" {
			for _, el := range node.Content { if truthy(effectiveNode(el)){ return []*Candidate{resultCand(c, boolNode(true))}, nil } }
			return []*Candidate{resultCand(c, boolNode(false))}, nil
		} else {
			for _, el := range node.Content { if !truthy(effectiveNode(el)){ return []*Candidate{resultCand(c, boolNode(false))}, nil } }
			return []*Candidate{resultCand(c, boolNode(true))}, nil
		}
	case "map", "filter":
		return funcMap(ast, ctx, c, false)
	case "map_values":
		return funcMap(ast, ctx, c, true)
	case "select":
		res, err := evalArg(ast, ctx, c, 0)
		if err != nil { return nil, err }
		for _, r := range res { if truthy(effectiveNode(r.Node)) { return []*Candidate{c}, nil } }
		return nil, nil
	case "first":
		if len(ast.Args)==0 {
			// bare first: return first key/value? Implement first child as key for maps, first element for seq
			if node != nil && node.Kind == yaml.MappingNode && len(node.Content)>=2 {
				// original returned key
				return []*Candidate{resultCand(c, cloneNode(node.Content[0]))}, nil
			}
			if node != nil && node.Kind == yaml.SequenceNode && len(node.Content)>0 {
				return []*Candidate{resultCand(c, cloneNode(node.Content[0]))}, nil
			}
			return []*Candidate{c}, nil
		}
		res, err := evalArg(ast, ctx, c, 0)
		if err != nil { return nil, err }
		if len(res)>0 { return res[:1], nil }
		return nil, nil
	case "error":
		s, _, err := evalArgString(ast, ctx, c, 0)
		if err != nil { return nil, err }
		return nil, fmt.Errorf("%s", s)
	case "tostring":
		if node == nil { return []*Candidate{resultCand(c, strNode(""))}, nil }
		if node.Kind == yaml.ScalarNode {
			return []*Candidate{resultCand(c, strNode(node.Value))}, nil
		}
		s := nodeStringValue(node)
		return []*Candidate{resultCand(c, strNode(s))}, nil
	case "tonumber":
		return funcToNumber(ast, ctx, c)
	case "upcase", "downcase":
		if node == nil || node.Kind != yaml.ScalarNode || node.Tag == "!!null" && false {
			// scalar check
		}
		if node == nil || node.Kind != yaml.ScalarNode {
			tag:=""; if node!=nil{tag=node.Tag}; return nil, fmt.Errorf("cannot change case with %s, can only operate on strings. ", tag)
		}
		v := node.Value
		if name=="upcase" { v = strings.ToUpper(v) } else { v = strings.ToLower(v) }
		nn := strNode(v); nn.Line = node.Line; nn.Column = node.Column
		return []*Candidate{resultCand(c, nn)}, nil
	case "trim":
		if node == nil || node.Kind != yaml.ScalarNode {
			tag:=""; if node!=nil{tag=node.Tag}; return nil, fmt.Errorf("cannot trim %s, can only operate on strings. ", tag)
		}
		return []*Candidate{resultCand(c, strNode(strings.TrimSpace(node.Value)))}, nil
	case "test":
		return funcTestMatch(ast, ctx, c, false)
	case "match":
		return funcTestMatch(ast, ctx, c, true)
	case "capture":
		return funcCapture(ast, ctx, c)
	case "sub":
		return funcSub(ast, ctx, c)
	case "split":
		if node == nil || node.Kind != yaml.ScalarNode {
			tag:=""; if node!=nil{tag=node.Tag}; _ = tag; return nil, fmt.Errorf("cannot split %s, can only split strings", nodeTag(node))
		}
		sep, _, err := evalArgString(ast, ctx, c, 0); if err != nil { return nil, err }
		var parts []string
		if sep == "" {
			for _, r := range node.Value { parts = append(parts, string(r)) }
		} else {
			parts = strings.Split(node.Value, sep)
		}
		seq := &yaml.Node{Kind: yaml.SequenceNode, Tag: "!!seq"}
		for _, p := range parts { seq.Content = append(seq.Content, strNode(p)) }
		return []*Candidate{resultCand(c, seq)}, nil
	case "join":
		if node == nil || node.Kind != yaml.SequenceNode {
			return nil, fmt.Errorf("cannot join with %s, can only join arrays of scalars", nodeTag(node))
		}
		sep, _, err := evalArgString(ast, ctx, c, 0); if err != nil { return nil, err }
		var vals []string
		for _, el := range node.Content {
			en := effectiveNode(el)
			if en.Kind != yaml.ScalarNode { return nil, fmt.Errorf("cannot join with %s, can only join arrays of scalars", nodeTag(node)) }
			if en.Tag == "!!null" { vals = append(vals, "") } else { vals = append(vals, en.Value) }
		}
		return []*Candidate{resultCand(c, strNode(strings.Join(vals, sep)))}, nil
	case "to_entries":
		return funcToEntries(c)
	case "from_entries":
		return funcFromEntries(c)
	case "with_entries":
		// convert to entries, apply arg per entry, then from entries
		entries, err := funcToEntries(c)
		if err != nil { return nil, err }
		if len(entries)==0 { return nil, nil }
		seqCand := entries[0]
		seqNode := effectiveNode(seqCand.Node)
		var newEntries []*Candidate
		for i, el := range seqNode.Content {
			elCand := seqCand.child(el, seqNode, i, i)
			res, err := evalAST(ast.Args[0], ctx.withCandidates([]*Candidate{elCand}))
			if err != nil { return nil, err }
			newEntries = append(newEntries, res...)
		}
		// Build a seq candidate from newEntries nodes to run from_entries
		newSeq := &yaml.Node{Kind: yaml.SequenceNode, Tag: "!!seq"}
		for _, e := range newEntries { newSeq.Content = append(newSeq.Content, e.Node) }
		nc := resultCand(c, newSeq)
		return funcFromEntries(nc)
	case "pick", "omit":
		return funcPickOmit(ast, ctx, c, name=="pick")
	case "array_to_map":
		if node != nil && node.Kind == yaml.SequenceNode {
			m := &yaml.Node{Kind: yaml.MappingNode, Tag: "!!map"}
			for i, el := range node.Content { m.Content = append(m.Content, intNode(int64(i)), cloneNode(el)) }
			return []*Candidate{resultCand(c, m)}, nil
		}
		return []*Candidate{c}, nil
	case "to_json", "@json":
		// to_json uses pretty indent 2; @json compact
		var s string; var err error
		if name=="to_json" { s, err = encodeJSONToString(c.Node, true) } else { s, err = encodeJSONCompact(c.Node) }
		if err != nil { return nil, err }
		if name=="to_json" { s = s + "\n" } // encodeJSON already (?) check helpers: compact returns no newline; pretty returns without? We'll adjust helpers
		return []*Candidate{resultCand(c, strNode(s))}, nil
	case "to_yaml", "@yaml":
		s, err := encodeYAMLToStringForNode(c.Node)
		if err != nil { return nil, err }
		return []*Candidate{resultCand(c, strNode(s))}, nil
	case "@csv", "to_csv":
		s, err := encodeCSVString(c.Node, ',')
		if err != nil { return nil, err }
		return []*Candidate{resultCand(c, strNode(strings.TrimRight(s, "\n")))}, nil
	case "@tsv", "to_tsv":
		s, err := encodeCSVString(c.Node, '\t')
		if err != nil { return nil, err }
		return []*Candidate{resultCand(c, strNode(strings.TrimRight(s, "\n")))}, nil
	case "to_props", "@props":
		s, err := encodePropsString(c.Node)
		if err != nil { return nil, err }
		return []*Candidate{resultCand(c, strNode(s))}, nil
	case "to_xml", "@xml":
		s, err := encodeXMLString(c.Node)
		if err != nil { return nil, err }
		return []*Candidate{resultCand(c, strNode(s))}, nil
	case "@base64":
		if node == nil || node.Kind != yaml.ScalarNode || node.Tag == "!!map" {
			return nil, fmt.Errorf("cannot encode %s as base64, can only operate on strings", nodeTag(node))
		}
		return []*Candidate{resultCand(c, strNode(base64.StdEncoding.EncodeToString([]byte(node.Value))))}, nil
	case "@base64d":
		if node == nil || node.Kind != yaml.ScalarNode {
			return []*Candidate{resultCand(c, strNode(""))}, nil
		}
		dec, err := base64.StdEncoding.DecodeString(node.Value)
		if err != nil { return nil, err }
		return []*Candidate{resultCand(c, strNode(string(dec)))}, nil
	case "@uri":
		if node == nil || node.Kind != yaml.ScalarNode {
			return nil, fmt.Errorf("cannot encode %s as URI, can only operate on strings. Please first pipe through another encoding operator to convert the value to a string", nodeTag(node))
		}
		return []*Candidate{resultCand(c, strNode(url.QueryEscape(node.Value)))}, nil
	case "@sh":
		if node == nil || node.Kind != yaml.ScalarNode { return []*Candidate{resultCand(c, strNode(""))}, nil }
		return []*Candidate{resultCand(c, strNode(shellEscape(node.Value)))}, nil
	case "from_json":
		if node == nil || node.Kind != yaml.ScalarNode || node.Value=="" {
			return nil, fmt.Errorf("EOF")
		}
		n, err := decodeJSONToNode([]byte(node.Value))
		if err != nil { return nil, err }
		return []*Candidate{resultCand(c, n)}, nil
	case "from_yaml":
		if node == nil || node.Kind != yaml.ScalarNode || node.Value=="" {
			return nil, fmt.Errorf("EOF")
		}
		docs, err := decodeYAMLBytes([]byte(node.Value), "-")
		if err != nil { return nil, err }
		if len(docs)==0 { return nil, fmt.Errorf("EOF") }
		var out []*Candidate
		for _, d := range docs { nc := resultCand(c, d.Node); out = append(out, nc) }
		return out, nil
	case "from_csv", "from_tsv":
		sep := ','; if name=="from_tsv" { sep='\t' }
		if node == nil || node.Kind != yaml.ScalarNode || node.Value=="" { return nil, fmt.Errorf("EOF") }
		n, err := decodeCSVBytes([]byte(node.Value), sep, name=="from_tsv")
		if err != nil { return nil, err }
		return []*Candidate{resultCand(c, n)}, nil
	case "from_xml":
		if node == nil || node.Kind != yaml.ScalarNode { return nil, nil }
		n, err := decodeXMLBytes([]byte(node.Value))
		if err != nil { return nil, err }
		if n==nil { return nil, nil }
		return []*Candidate{resultCand(c, n)}, nil
	case "now":
		nowStr := time.Now().UTC().Format("2006-01-02T15:04:05Z")
		return []*Candidate{resultCand(c, scalarNode("!!timestamp", nowStr))}, nil
	case "tz":
		return funcTZ(ast, ctx, c)
	case "with_dtf":
		return funcWithDTF(ast, ctx, c)
	case "env", "strenv":
		// args[0] is literal env name node
		if globalOpts != nil && globalOpts.DisableEnvOps { return nil, fmt.Errorf("env operations have been disabled") }
		if len(ast.Args)==0 { return nil, fmt.Errorf("'%s' expects 1 arg but received none", name) }
		envName := candidateToStringFromLiteral(ast.Args[0])
		val, ok := os.LookupEnv(envName)
		if name=="env" {
			if !ok || val=="" { return nil, fmt.Errorf("value for env variable '%s' not provided in env()", envName) }
			return []*Candidate{resultCand(c, strNode(val))}, nil
		}
		return []*Candidate{resultCand(c, strNode(val))}, nil
	case "eval":
		s, _, err := evalArgString(ast, ctx, c, 0); if err != nil { return nil, err }
		subAst, err := parseExpressionString(s); if err != nil { return nil, err }
		return evalAST(subAst, ctx.withCandidates([]*Candidate{c}))
	case "load":
		if globalOpts != nil && globalOpts.DisableFileOps { return nil, fmt.Errorf("file operations have been disabled") }
		s, _, err := evalArgString(ast, ctx, c, 0); if err != nil { return nil, err }
		data, err := os.ReadFile(s); if err != nil { return nil, fmt.Errorf("failed to load %s: %v", s, err) }
		// Determine format by extension
		format := formatFromFilename(s)
		docs, err := decodeBytesByFormat(data, format, s)
		if err != nil { return nil, err }
		var out []*Candidate
		for _, d := range docs { out = append(out, d) }
		if len(out)==0 { out = append(out, resultCand(c, nullNode())) }
		return out, nil
	case "load_str":
		if globalOpts != nil && globalOpts.DisableFileOps { return nil, fmt.Errorf("file operations have been disabled") }
		s, _, err := evalArgString(ast, ctx, c, 0); if err != nil { return nil, err }
		data, err := os.ReadFile(s); if err != nil { return nil, fmt.Errorf("failed to load %s: %v", s, err) }
		return []*Candidate{resultCand(c, strNode(string(data)))}, nil
	case "system":
		if globalOpts == nil || !globalOpts.EnableSystem {
			return nil, fmt.Errorf("system operations are disabled, use --security-enable-system-operator to enable")
		}
		s, _, err := evalArgString(ast, ctx, c, 0); if err != nil { return nil, err }
		cmd := exec.Command(s)
		outb, err := cmd.Output()
		if err != nil { return nil, fmt.Errorf("system command '%s' failed: %v", s, err) }
		return []*Candidate{resultCand(c, strNode(strings.TrimRight(string(outb), "\n")))}, nil
	case "del":
		// handled in evalFunc directly? Here c is single candidate. del arg evaluated against c gives targets to delete.
		return funcDel(ast, ctx, c)
	case "delpaths":
		return funcDelPaths(ast, ctx, c)
	case "setpath":
		return funcSetPath(ast, ctx, c)
	case "explode":
		return funcExplode(ast, ctx, c)
	case "with":
		return funcWith(ast, ctx, c)
	case "collect":
		// collect(arg) as function: evaluate arg and collect into array
		res, err := evalArg(ast, ctx, c, 0); if err != nil { return nil, err }
		seq := &yaml.Node{Kind: yaml.SequenceNode, Tag: "!!seq"}
		for _, r := range res { seq.Content = append(seq.Content, cloneNode(r.Node)) }
		return []*Candidate{resultCand(c, seq)}, nil
	}
	// Fallback for names not implemented: try treat as arg-less returning candidate
	// For functions that are really encoding names (@...)
	if strings.HasPrefix(name, "@") {
		// @text etc already handled as lexer error, unreachable
	}
	return []*Candidate{c}, nil
}

func nodeTag(n *yaml.Node) string {
	if n == nil { return "!!null" }
	if n.Tag != "" { return n.Tag }
	switch n.Kind {
	case yaml.MappingNode: return "!!map"
	case yaml.SequenceNode: return "!!seq"
	}
	return "!!str"
}
func formatPathBracket(path []interface{}) string {
	// fmt.Sprintf %v of []interface gives [a b]
	return fmt.Sprintf("%v", path)
}
func indexOfNode(parent *yaml.Node, target *yaml.Node) int {
	for i, el := range parent.Content { if el==target { return i } }
	return 0
}
func pathElemForIndex(parent *yaml.Node, target *yaml.Node) interface{} {
	idx := indexOfNode(parent, target)
	if parent.Kind == yaml.SequenceNode { return idx }
	if parent.Kind == yaml.MappingNode && idx%2==1 { return pathElemForKey(parent.Content[idx-1]) }
	return idx
}
func sortMapEntries(m *yaml.Node) {
	type pair struct{k,v *yaml.Node}
	var pairs []pair
	for i:=0;i+1<len(m.Content);i+=2 { pairs=append(pairs,pair{m.Content[i],m.Content[i+1]}) }
	sort.SliceStable(pairs, func(i,j int) bool {
		cmp,_ := compareNodes(pairs[i].k, pairs[j].k); return cmp<0
	})
	m.Content = nil
	for _, p := range pairs { m.Content = append(m.Content, p.k, p.v) }
}
func flattenContent(content []*yaml.Node, depth int) []*yaml.Node {
	if depth == 0 { return content }
	var out []*yaml.Node
	for _, el := range content {
		en := effectiveNode(el)
		if en.Kind == yaml.SequenceNode {
			nd := depth; if nd>0 { nd-- }
			out = append(out, flattenContent(en.Content, nd)...)
		} else {
			out = append(out, el)
		}
	}
	return out
}
func nodeContains(lhs, rhs *yaml.Node) bool {
	if lhs == nil || rhs == nil { return false }
	l := effectiveNode(lhs); r := effectiveNode(rhs)
	if l.Kind == yaml.ScalarNode && r.Kind == yaml.ScalarNode {
		if l.Tag == "!!str" && r.Tag == "!!str" { return strings.Contains(l.Value, r.Value) }
		return l.Value == r.Value
	}
	if l.Kind == yaml.MappingNode && r.Kind == yaml.MappingNode {
		for i:=0;i+1<len(r.Content);i+=2 {
			idx, _, lv := findMapEntry(l, r.Content[i].Value)
			if idx<0 { return false }
			if !nodeContains(lv, r.Content[i+1]) { return false }
		}
		return true
	}
	if l.Kind == yaml.SequenceNode && r.Kind == yaml.SequenceNode {
		for _, re := range r.Content {
			found:=false
			for _, le := range l.Content { if nodeContains(le, re) || deepEqualNode(le,re) { found=true; break } }
			if !found { return false }
		}
		return true
	}
	if l.Kind == yaml.SequenceNode {
		for _, le := range l.Content { if deepEqualNode(le,r) { return true } }
		return false
	}
	return deepEqualNode(l,r)
}
func funcSortBy(ast *AST, ctx *EvalContext, c *Candidate) ([]*Candidate, error) {
	node := effectiveNode(c.Node)
	if node == nil { return []*Candidate{c}, nil }
	if node.Kind == yaml.SequenceNode {
		type item struct { el *yaml.Node; key *yaml.Node; idx int }
		var items []item
		for i, el := range node.Content {
			elCand := c.child(el, node, i, i)
			kres, err := evalAST(ast.Args[0], ctx.withCandidates([]*Candidate{elCand}))
			if err != nil { return nil, err }
			var kn *yaml.Node; if len(kres)>0 { kn=kres[0].Node } else { kn=nullNode() }
			items = append(items, item{el, kn, i})
		}
		sort.SliceStable(items, func(a,b int) bool { cmp,_:=compareNodes(items[a].key, items[b].key); return cmp<0 })
		node.Content = nil
		for _, it := range items { node.Content = append(node.Content, it.el) }
		return []*Candidate{c}, nil
	}
	if node.Kind == yaml.MappingNode {
		type pair struct{k,v,key *yaml.Node}
		var pairs []pair
		for i:=0;i+1<len(node.Content);i+=2 {
			vCand := c.child(node.Content[i+1], node, i+1, pathElemForKey(node.Content[i]))
			kres, err := evalAST(ast.Args[0], ctx.withCandidates([]*Candidate{vCand}))
			if err != nil { return nil, err }
			var kn *yaml.Node; if len(kres)>0 { kn=kres[0].Node } else { kn=nullNode() }
			pairs = append(pairs, pair{node.Content[i], node.Content[i+1], kn})
		}
		sort.SliceStable(pairs, func(a,b int) bool { cmp,_:=compareNodes(pairs[a].key, pairs[b].key); return cmp<0 })
		node.Content=nil
		for _,p := range pairs { node.Content=append(node.Content,p.k,p.v) }
		return []*Candidate{c}, nil
	}
	return []*Candidate{c}, nil
}
func funcMap(ast *AST, ctx *EvalContext, c *Candidate, values bool) ([]*Candidate, error) {
	node := effectiveNode(c.Node)
	if node == nil { return nil, nil }
	if node.Kind == yaml.SequenceNode {
		if values {
			resNode := cloneNode(node)
			// evaluate per original element
			newContent := []*yaml.Node{}
			for i, el := range node.Content {
				elCand := c.child(el, node, i, i)
				r, err := evalAST(ast.Args[0], ctx.withCandidates([]*Candidate{elCand}))
				if err != nil { return nil, err }
				for _, rr := range r { newContent = append(newContent, cloneNode(rr.Node)) }
				if len(r)==0 { /* keep? map_values with empty result removes element? Keep original? We'll skip */ }
			}
			resNode.Content = newContent
			return []*Candidate{resultCand(c, resNode)}, nil
		} else {
			resNode := &yaml.Node{Kind: yaml.SequenceNode, Tag: "!!seq", Style: node.Style}
			for i, el := range node.Content {
				elCand := c.child(el, node, i, i)
				r, err := evalAST(ast.Args[0], ctx.withCandidates([]*Candidate{elCand}))
				if err != nil { return nil, err }
				for _, rr := range r { resNode.Content = append(resNode.Content, cloneNode(rr.Node)) }
			}
			return []*Candidate{resultCand(c, resNode)}, nil
		}
	}
	if node.Kind == yaml.MappingNode {
		if values {
			resNode := cloneNode(node)
			for i:=0;i+1<len(node.Content);i+=2 {
				vCand := c.child(node.Content[i+1], node, i+1, pathElemForKey(node.Content[i]))
				r, err := evalAST(ast.Args[0], ctx.withCandidates([]*Candidate{vCand}))
				if err != nil { return nil, err }
				if len(r)>0 {
					// find in resNode by key
					if idx,_,_ := findMapEntry(resNode, node.Content[i].Value); idx>=0 { resNode.Content[idx]=cloneNode(r[0].Node) }
				}
			}
			return []*Candidate{resultCand(c, resNode)}, nil
		} else {
			// map over values returns flat results
			var out []*Candidate
			for i:=0;i+1<len(node.Content);i+=2 {
				vCand := c.child(node.Content[i+1], node, i+1, pathElemForKey(node.Content[i]))
				r, err := evalAST(ast.Args[0], ctx.withCandidates([]*Candidate{vCand}))
				if err != nil { return nil, err }
				out = append(out, r...)
			}
			return out, nil
		}
	}
	// scalar: apply arg to candidate itself? map on scalar: treat as map_values?
	r, err := evalAST(ast.Args[0], ctx.withCandidates([]*Candidate{c}))
	if err != nil { return nil, err }
	if values { return r, nil }
	return r, nil
}
func funcToNumber(ast *AST, ctx *EvalContext, c *Candidate) ([]*Candidate, error) {
	node := effectiveNode(c.Node)
	pathStr := formatPath(c.Path)
	if node == nil || node.Kind != yaml.ScalarNode {
		return nil, fmt.Errorf("cannot convert node at path %s of tag %s to number", pathStr, nodeTag(node))
	}
	if node.Tag == "!!int" || node.Tag == "!!float" {
		return []*Candidate{resultCand(c, cloneNode(node))}, nil
	}
	// try parse
	s := node.Value
	// int attempt
	if _, _, err := parseIntValue(s); err == nil && !strings.ContainsAny(s, ".eE") {
		nn := cloneNode(node); nn.Tag="!!int"; return []*Candidate{resultCand(c, nn)}, nil
	}
	if _, err := parseFloatValue(normaliseNumStr(s)); err == nil && (strings.ContainsAny(s, ".eE") || strings.HasPrefix(s,".")) {
		nn := cloneNode(node); nn.Tag="!!float"; return []*Candidate{resultCand(c, nn)}, nil
	}
	// Also float strings like "1.0" handled; plain "abc" fails
	if _, err := strconv.ParseFloat(s, 64); err == nil {
		nn := cloneNode(node); nn.Tag="!!float"; return []*Candidate{resultCand(c, nn)}, nil
	}
	return nil, fmt.Errorf("cannot convert node value [%s] at path %s of tag %s to number", s, pathStr, node.Tag)
}
func compileRegex(pat string) (*regexp.Regexp, error) { return regexp.Compile(pat) }
func funcTestMatch(ast *AST, ctx *EvalContext, c *Candidate, isMatch bool) ([]*Candidate, error) {
	node := effectiveNode(c.Node)
	pat, _, err := evalArgString(ast, ctx, c, 0); if err != nil { return nil, err }
	if node == nil || node.Kind != yaml.ScalarNode || node.Tag == "!!map" {
		// map check
		if node != nil && node.Kind != yaml.ScalarNode {
			return nil, fmt.Errorf("cannot match with %s, can only match strings. Hint: Most often you'll want to use '|=' over '=' for this operation", nodeTag(node))
		}
	}
	// if scalar but not string? test on numbers: treat value
	re, err := compileRegex(pat); if err != nil { return nil, err }
	if !isMatch {
		return []*Candidate{resultCand(c, boolNode(re.MatchString(node.Value)))}, nil
	}
	loc := re.FindStringSubmatchIndex(node.Value)
	if loc == nil { return nil, nil }
	// build match map
	m := &yaml.Node{Kind: yaml.MappingNode, Tag: "!!map"}
	addEntry := func(k string, v *yaml.Node){ m.Content = append(m.Content, strNode(k), v) }
	addEntry("string", strNode(node.Value[loc[0]:loc[1]]))
	addEntry("offset", intNode(int64(loc[0])))
	addEntry("length", intNode(int64(loc[1]-loc[0])))
	caps := &yaml.Node{Kind: yaml.SequenceNode, Tag: "!!seq"}
	// if no captures, caps should be flow empty [] as in original: style flow
	if len(loc) <=2 { caps.Style = yaml.FlowStyle }
	names := re.SubexpNames()
	for i:=1;i<len(names);i++ {
		sidx := loc[2*i]; eidx := loc[2*i+1]
		capMap := &yaml.Node{Kind: yaml.MappingNode, Tag: "!!map"}
		var cs string; var coff, clen int
		if sidx>=0 { cs = node.Value[sidx:eidx]; coff=sidx; clen=eidx-sidx } else { cs=""; coff=-1; clen=0 }
		capMap.Content = append(capMap.Content, strNode("string"), strNode(cs), strNode("offset"), intNode(int64(coff)), strNode("length"), intNode(int64(clen)))
		if names[i] != "" { capMap.Content = append(capMap.Content, strNode("name"), strNode(names[i])) }
		caps.Content = append(caps.Content, capMap)
	}
	addEntry("captures", caps)
	return []*Candidate{resultCand(c, m)}, nil
}
func funcCapture(ast *AST, ctx *EvalContext, c *Candidate) ([]*Candidate, error) {
	node := effectiveNode(c.Node)
	pat, _, err := evalArgString(ast, ctx, c, 0); if err != nil { return nil, err }
	if node == nil || node.Kind != yaml.ScalarNode {
		return nil, fmt.Errorf("cannot match with %s, can only match strings. Hint: Most often you'll want to use '|=' over '=' for this operation", nodeTag(node))
	}
	re, err := compileRegex(pat); if err != nil { return nil, err }
	loc := re.FindStringSubmatchIndex(node.Value)
	if loc == nil { return nil, nil }
	names := re.SubexpNames()
	m := &yaml.Node{Kind: yaml.MappingNode, Tag: "!!map"}
	for i:=1;i<len(names);i++ {
		sidx:=loc[2*i]; eidx:=loc[2*i+1]
		var cs string; if sidx>=0 { cs=node.Value[sidx:eidx] }
		m.Content = append(m.Content, strNode(names[i]), strNode(cs))
	}
	return []*Candidate{resultCand(c, m)}, nil
}
func funcSub(ast *AST, ctx *EvalContext, c *Candidate) ([]*Candidate, error) {
	node := effectiveNode(c.Node)
	if node == nil || node.Kind != yaml.ScalarNode {
		return nil, fmt.Errorf("cannot substitute with %s, can only substitute strings. Hint: Most often you'll want to use '|=' over '=' for this operation", nodeTag(node))
	}
	if len(ast.Args) < 2 {
		return nil, fmt.Errorf("'sub' expects 1 arg but received none")
	}
	pat, _, err := evalArgString(ast, ctx, c, 0); if err != nil { return nil, err }
	repl, _, err := evalArgString(ast, ctx, c, 1); if err != nil { return nil, err }
	re, err := compileRegex(pat); if err != nil { return nil, err }
	v := re.ReplaceAllString(node.Value, repl)
	return []*Candidate{resultCand(c, strNode(v))}, nil
}
func funcToEntries(c *Candidate) ([]*Candidate, error) {
	node := effectiveNode(c.Node)
	if node == nil || (node.Kind != yaml.MappingNode && node.Kind != yaml.SequenceNode) {
		return nil, fmt.Errorf("%s has no keys", nodeTag(node))
	}
	seq := &yaml.Node{Kind: yaml.SequenceNode, Tag: "!!seq"}
	if node.Kind == yaml.MappingNode {
		for i:=0;i+1<len(node.Content);i+=2 {
			entry := &yaml.Node{Kind: yaml.MappingNode, Tag: "!!map"}
			entry.Content = append(entry.Content, strNode("key"), cloneNode(node.Content[i]), strNode("value"), cloneNode(node.Content[i+1]))
			seq.Content = append(seq.Content, entry)
		}
	} else {
		for i, el := range node.Content {
			entry := &yaml.Node{Kind: yaml.MappingNode, Tag: "!!map"}
			entry.Content = append(entry.Content, strNode("key"), intNode(int64(i)), strNode("value"), cloneNode(el))
			seq.Content = append(seq.Content, entry)
		}
	}
	return []*Candidate{resultCand(c, seq)}, nil
}
func funcFromEntries(c *Candidate) ([]*Candidate, error) {
	node := effectiveNode(c.Node)
	if node == nil || node.Kind != yaml.SequenceNode {
		return nil, fmt.Errorf("from entries only runs against arrays")
	}
	m := &yaml.Node{Kind: yaml.MappingNode, Tag: "!!map"}
	for pos, el := range node.Content {
		en := effectiveNode(el)
		if en.Kind != yaml.MappingNode {
			return nil, fmt.Errorf("expected to find one 'key' entry but found 0 in position %d", pos)
		}
		ki, _, kv := findMapEntry(en, "key")
		if ki<0 { return nil, fmt.Errorf("expected to find one 'key' entry but found 0 in position %d", pos) }
		vi, _, vv := findMapEntry(en, "value")
		if vi<0 { return nil, fmt.Errorf("expected to find one 'value' entry but found 0 in position %d", pos) }
		m.Content = append(m.Content, cloneNode(kv), cloneNode(vv))
		// Note kv here is key node? findMapEntry returns idx,k,v so kv variable above misnamed: we used kv as key? Wait re-evaluate: ki is idx, second return is k node, third is v. We captured _, kv as ??? Actually code: ki, _, kv := findMapEntry(en,"key") => kv is value node of "key" entry, which is actual key. Good.
		_ = vi; _ = vv
		// But vv is value of "value" entry, correct.
		// However we appended cloneNode(kv), cloneNode(vv) - correct.
	}
	return []*Candidate{resultCand(c, m)}, nil
}
func funcPickOmit(ast *AST, ctx *EvalContext, c *Candidate, isPick bool) ([]*Candidate, error) {
	node := effectiveNode(c.Node)
	args, err := evalArg(ast, ctx, c, 0); if err != nil { return nil, err }
	if len(args)==0 { return []*Candidate{resultCand(c, cloneNode(node))}, nil }
	argNode := effectiveNode(args[0].Node)
	var keys []string
	var indices []int
	isIndex := false
	if argNode != nil && argNode.Kind == yaml.SequenceNode {
		for _, el := range argNode.Content {
			en := effectiveNode(el)
			keys = append(keys, en.Value)
			if iv, err := strconv.Atoi(en.Value); err==nil { indices = append(indices, iv); isIndex=true }
		}
	}
	if node == nil { return []*Candidate{c}, nil }
	if node.Kind == yaml.MappingNode {
		if isPick {
			m := &yaml.Node{Kind: yaml.MappingNode, Tag: "!!map", Style: node.Style}
			for _, k := range keys {
				if idx, kn, v := findMapEntry(node, k); idx>=0 { m.Content = append(m.Content, cloneNode(kn), cloneNode(v)) }
			}
			return []*Candidate{resultCand(c, m)}, nil
		} else {
			m := cloneNode(node)
			var content []*yaml.Node
			for i:=0;i+1<len(m.Content);i+=2 {
				if !containsStr(keys, m.Content[i].Value) { content = append(content, m.Content[i], m.Content[i+1]) }
			}
			m.Content = content
			return []*Candidate{resultCand(c, m)}, nil
		}
	}
	if node.Kind == yaml.SequenceNode {
		if isPick {
			seq := &yaml.Node{Kind: yaml.SequenceNode, Tag: "!!seq", Style: node.Style}
			for _, iv := range indices { if iv>=0 && iv < len(node.Content) { seq.Content = append(seq.Content, cloneNode(node.Content[iv])) } }
			_ = isIndex
			return []*Candidate{resultCand(c, seq)}, nil
		} else {
			seq := cloneNode(node)
			var content []*yaml.Node
			for i, el := range node.Content { if !containsInt(indices, i) { content = append(content, el) } }
			seq.Content = content
			return []*Candidate{resultCand(c, seq)}, nil
		}
	}
	return []*Candidate{c}, nil
}
