package main

import (
	"fmt"
	"sort"
	"strconv"
	"strings"

	"gopkg.in/yaml.v3"
)

// XML encoder: expects map at top; keys are element names; attributes keys prefixed +@, content +content etc using current opts.
func encodeXMLString(n *yaml.Node) (string, error) {
	var sb strings.Builder
	err := writeXMLNode(&sb, n, "", 0, true)
	if err != nil { return "", err }
	return sb.String(), nil
}

func xmlOpts() (attrPrefix, contentName, procPrefix, directiveName string) {
	attrPrefix = "+@"; contentName="+content"; procPrefix="+p_"; directiveName="+directive"
	if globalOpts != nil {
		if globalOpts.XMLAttrPrefix != "" { attrPrefix = globalOpts.XMLAttrPrefix }
		if globalOpts.XMLContentName != "" { contentName = globalOpts.XMLContentName }
		if globalOpts.XMLProcInstPrefix != "" { procPrefix = globalOpts.XMLProcInstPrefix }
		if globalOpts.XMLDirectiveName != "" { directiveName = globalOpts.XMLDirectiveName }
	}
	return
}

func writeXMLNode(sb *strings.Builder, n *yaml.Node, name string, level int, top bool) error {
	node := effectiveNode(n)
	indent := strings.Repeat("  ", level)
	attrPrefix, contentName, procPrefix, directiveName := xmlOpts()
	if node == nil { return nil }
	if name == "" {
		// top level: if map, each key is element; if scalar, write value raw; seq write each?
		if node.Kind == yaml.MappingNode {
			// directives/proc inst at top?
			for i:=0;i+1<len(node.Content);i+=2 {
				k := node.Content[i].Value
				v := node.Content[i+1]
				if strings.HasPrefix(k, procPrefix) {
					procName := strings.TrimPrefix(k, procPrefix)
					// value is string like version="1.0"
					sb.WriteString("<?"+procName+" "+effectiveNode(v).Value+"?>\n")
					continue
				}
				if k == directiveName {
					sb.WriteString("<!"+effectiveNode(v).Value+">\n")
					continue
				}
				if err := writeXMLNode(sb, v, k, level, false); err != nil { return err }
			}
			return nil
		}
		if node.Kind == yaml.SequenceNode {
			for _, el := range node.Content {
				if err := writeXMLNode(sb, el, name, level, top); err != nil { return err }
			}
			return nil
		}
		// scalar
		sb.WriteString(xmlEscape(node.Value))
		return nil
