	// named element
	if node.Kind == yaml.SequenceNode {
		for _, el := range node.Content {
			if err := writeXMLNode(sb, el, name, level, false); err != nil { return err }
		}
		return nil
	}
	if node.Kind == yaml.MappingNode {
		// collect attrs, content, children
		var attrs []struct{k,v string}
		var content string
		hasContent := false
		type child struct{k string; v *yaml.Node}
		var children []child
		for i:=0;i+1<len(node.Content);i+=2 {
			k := node.Content[i].Value
			v := node.Content[i+1]
			if strings.HasPrefix(k, attrPrefix) {
				attrs = append(attrs, struct{k,v string}{strings.TrimPrefix(k, attrPrefix), effectiveNode(v).Value})
			} else if k == contentName {
				content = effectiveNode(v).Value; hasContent = true
			} else if strings.HasPrefix(k, procPrefix) {
				// nested proc inst?
				children = append(children, child{k,v})
			} else {
				children = append(children, child{k,v})
			}
