package main

import (
	"bytes"
	"encoding/csv"
	"encoding/json"
	"fmt"
	"io"
	"net/url"
	"strconv"
	"strings"
	"encoding/base64"

	"gopkg.in/yaml.v3"
)

// Document candidate creation
func makeDocCandidate(node *yaml.Node, docIdx int, fileIdx int, filename string, leadingSep bool, globalPrintID int) *Candidate {
	c := &Candidate{Node: node, DocIndex: docIdx, FileIdx: fileIdx, Filename: filename, RootNode: node, LeadingSep: leadingSep, PrintID: globalPrintID, FromRoot: true}
	c.Lead = c
	return c
}

func decodeYAMLBytes(data []byte, filename string) ([]*Candidate, error) {
	// returns candidates per doc; caller sets indices
	dec := yaml.NewDecoder(bytes.NewReader(data))
	var docs []*Candidate
	docIdx := 0
	leading := detectLeadingSep(data)
	for {
		var docNode yaml.Node
		err := dec.Decode(&docNode)
		if err == io.EOF {
			break
		}
		if err != nil {
			return nil, err
		}
		var content *yaml.Node
		if docNode.Kind == yaml.DocumentNode && len(docNode.Content) > 0 {
			content = docNode.Content[0]
		} else {
			// empty doc
			content = nullNode()
			// yaml decoder for empty input returns a document with null? Actually decode on empty returns EOF, so unreachable.
		}
		ls := false
		if docIdx == 0 && leading {
			ls = true
		}
		c := makeDocCandidate(content, docIdx, 0, filename, ls, docIdx)
		docs = append(docs, c)
		docIdx++
	}
	if len(docs) == 0 {
		// empty input -> one null doc
		docs = append(docs, makeDocCandidate(nullNode(), 0, 0, filename, false, 0))
	}
	return docs, nil
}

func detectLeadingSep(data []byte) bool {
	// Look at leading lines: skip blank and comment lines, if first is --- return true
	lines := strings.Split(string(data), "\n")
	for _, line := range lines {
		trim := strings.TrimSpace(line)
		if trim == "" {
			continue
		}
		if strings.HasPrefix(trim, "#") {
			continue
		}
		if trim == "---" || strings.HasPrefix(trim, "--- ") {
			return true
		}
		return false
	}
	return false
}

// Decode dispatch by format name (canonical)
func decodeBytesByFormat(data []byte, format string, filename string) ([]*Candidate, error) {
	switch format {
	case "yaml", "kyaml":
		docs, err := decodeYAMLBytes(data, filename)
		if err != nil {
			// wrap as bad file error in caller
			return nil, err
		}
		if format == "kyaml" {
			// kyaml parser seems to produce flow style root? Mark root style flow if map/seq
			for _, d := range docs {
				if d.Node != nil && (d.Node.Kind == yaml.MappingNode || d.Node.Kind == yaml.SequenceNode) {
					// Only if input looks like kyaml/json-like? Original -p kyaml on flow input produced flow output; setting flow for all kyaml?
					d.Node.Style = yaml.FlowStyle
				}
			}
		}
		return docs, nil
	case "json":
		return decodeJSONBytes(data, filename)
	case "props":
		n, err := decodePropsBytes(data)
		if err != nil { return nil, err }
		return []*Candidate{makeDocCandidate(n, 0, 0, filename, false, 0)}, nil
	case "csv":
		sep := ',' 
		if globalOpts != nil && len([]rune(globalOpts.CSVSeparator))>0 { sep = []rune(globalOpts.CSVSeparator)[0] }
		n, err := decodeCSVBytes(data, sep, false)
		if err != nil { return nil, err }
		return []*Candidate{makeDocCandidate(n, 0, 0, filename, false, 0)}, nil
	case "tsv":
		n, err := decodeCSVBytes(data, '\t', true)
		if err != nil { return nil, err }
		return []*Candidate{makeDocCandidate(n, 0, 0, filename, false, 0)}, nil
	case "xml":
		n, err := decodeXMLBytes(data)
		if err != nil { return nil, err }
		if n == nil { n = nullNode() }
		return []*Candidate{makeDocCandidate(n, 0, 0, filename, false, 0)}, nil
	case "toml":
		n, err := decodeTOMLBytes(data)
		if err != nil { return nil, err }
		return []*Candidate{makeDocCandidate(n, 0, 0, filename, false, 0)}, nil
	case "ini":
		n, err := decodeINIBytes(data)
		if err != nil { return nil, err }
		return []*Candidate{makeDocCandidate(n, 0, 0, filename, false, 0)}, nil
	case "lua":
		n, err := decodeLuaBytes(data)
		if err != nil { return nil, err }
		return []*Candidate{makeDocCandidate(n, 0, 0, filename, false, 0)}, nil
	case "hcl":
		n, err := decodeHCLBytes(data)
		if err != nil { return nil, err }
		return []*Candidate{makeDocCandidate(n, 0, 0, filename, false, 0)}, nil
	case "base64":
		// Input is entire content trimmed
		s := strings.TrimSpace(string(data))
		dec, err := base64.StdEncoding.DecodeString(s)
		if err != nil {
			// try raw
			dec, err = base64.RawStdEncoding.DecodeString(s)
			if err != nil { return nil, err }
		}
		return []*Candidate{makeDocCandidate(strNode(string(dec)), 0, 0, filename, false, 0)}, nil
	case "uri":
		s := strings.TrimSpace(string(data))
		dec, err := url.QueryUnescape(s)
		if err != nil { return nil, err }
		return []*Candidate{makeDocCandidate(strNode(dec), 0, 0, filename, false, 0)}, nil
	}
	return nil, fmt.Errorf("unknown format '%s' please use [yaml|y|kyaml|ky|json|j|props|p|csv|c|tsv|t|xml|x|base64|uri|toml|hcl|h|shell|s|lua|l|ini|i]", format)
}

func decodeJSONBytes(data []byte, filename string) ([]*Candidate, error) {
	trim := strings.TrimSpace(string(data))
	if trim == "" {
		return []*Candidate{makeDocCandidate(nullNode(), 0, 0, filename, false, 0)}, nil
	}
	dec := json.NewDecoder(bytes.NewReader(data))
	dec.UseNumber()
	var docs []*Candidate
	idx := 0
	for {
		var v interface{}
		err := dec.Decode(&v)
		if err == io.EOF { break }
		if err != nil {
			// Simplify error: original: json: invalid character o as null etc. We'll attempt to generate similar for 'not json'
			return nil, jsonError(err, data)
		}
		n := jsonValueToNode(v, false)
		docs = append(docs, makeDocCandidate(n, idx, 0, filename, false, idx))
		idx++
	}
	if len(docs)==0 { docs = append(docs, makeDocCandidate(nullNode(),0,0,filename,false,0)) }
	return docs, nil
}

func jsonError(err error, data []byte) error {
	// Go's decoder error messages: e.g., invalid character 'n' in literal null (expecting 'u')
	// Original yq json error for "not json" is "json: invalid character o as null" which differs.
	// We'll return err as-is prefixed? Caller wraps with "bad file '-': ". Original message: "bad file '-': json: invalid character o as null"
	// Go json error for 'not' is "invalid character 'o' in literal null (expecting 'u')" Not matching. Try mimic yq's custom json parser? It probably uses a fork that reports differently.
	// Keep Go error but strip quotes? We'll return fmt.Errorf("json: %v", err) and caller will add bad file. That yields "bad file '-': json: invalid character ..."
	// To approximate original for words starting with n/t/f: they tried parse literal and second char mismatch gives "invalid character o as null"... Hard.
	return fmt.Errorf("json: %v", err)
