// Document candidate creation
func makeDocCandidate(node *yaml.Node, docIdx int, fileIdx int, filename string, leadingSep bool, globalPrintID int) *Candidate {
	c := &Candidate{Node: node, DocIndex: docIdx, FileIdx: fileIdx, Filename: filename, RootNode: node, LeadingSep: leadingSep, PrintID: globalPrintID, FromRoot: true}
	c.Lead = c
	return c
}

func decodeYAMLBytes(data []byte, filename string) ([]*Candidate, error) {
	// returns candidates per doc; caller sets indices
	dec := yaml.NewDecoder(bytes.NewReader(data))
	var docs []*Candidate
	docIdx := 0
	leading := detectLeadingSep(data)
	for {
		var docNode yaml.Node
		err := dec.Decode(&docNode)
		if err == io.EOF {
			break
		}
		if err != nil {
			return nil, err
		}
		var content *yaml.Node
		if docNode.Kind == yaml.DocumentNode && len(docNode.Content) > 0 {
			content = docNode.Content[0]
		} else {
			// empty doc
			content = nullNode()
			// yaml decoder for empty input returns a document with null? Actually decode on empty returns EOF, so unreachable.
		}
		ls := false
		if docIdx == 0 && leading {
			ls = true
		}
		c := makeDocCandidate(content, docIdx, 0, filename, ls, docIdx)
		docs = append(docs, c)
		docIdx++
	}
	if len(docs) == 0 {
		// empty input -> one null doc
		docs = append(docs, makeDocCandidate(nullNode(), 0, 0, filename, false, 0))
	}
	return docs, nil
}

func detectLeadingSep(data []byte) bool {
	// Look at leading lines: skip blank and comment lines, if first is --- return true
	lines := strings.Split(string(data), "\n")
	for _, line := range lines {
		trim := strings.TrimSpace(line)
		if trim == "" {
			continue
		}
		if strings.HasPrefix(trim, "#") {
			continue
		}
		if trim == "---" || strings.HasPrefix(trim, "--- ") {
			return true
		}
		return false
	}
	return false
}

// Decode dispatch by format name (canonical)
func decodeBytesByFormat(data []byte, format string, filename string) ([]*Candidate, error) {
	switch format {
	case "yaml", "kyaml":
		docs, err := decodeYAMLBytes(data, filename)
