func decodeJSONBytes(data []byte, filename string) ([]*Candidate, error) {
	trim := strings.TrimSpace(string(data))
	if trim == "" {
		return []*Candidate{makeDocCandidate(nullNode(), 0, 0, filename, false, 0)}, nil
	}
	dec := json.NewDecoder(bytes.NewReader(data))
	dec.UseNumber()
	var docs []*Candidate
	idx := 0
	for {
		var v interface{}
		err := dec.Decode(&v)
		if err == io.EOF { break }
		if err != nil {
			// Simplify error: original: json: invalid character o as null etc. We'll attempt to generate similar for 'not json'
			return nil, jsonError(err, data)
		}
		n := jsonValueToNode(v, false)
		docs = append(docs, makeDocCandidate(n, idx, 0, filename, false, idx))
