			} else {
				seq := &yaml.Node{Kind: yaml.SequenceNode, Tag: "!!seq"}
				// mark duplicate seq by... we use a helper: sequences created here have style 0; to distinguish from original seq values (which are maps/scalars), we assume existing not seq or if seq from element repeated, its elements are... XML repeated elements produce seq of scalars/maps; original element values are not seq unless nested repeated. If existing is seq and was created by us, we need flag. Simplify: if existing Kind seq, append (this may incorrectly append to a genuine single element that is seq? XML elements don't produce seq except repeats, so fine)
				seq.Content = append(seq.Content, existing, val)
