	for _,r:=range s {
		if r=='"' { inQ=!inQ; cur.WriteRune(r); continue }
		if r=='.' && !inQ { parts=append(parts, strings.Trim(strings.TrimSpace(cur.String()), "\"")); cur.Reset(); continue }
		cur.WriteRune(r)
	}
	if cur.Len()>0 { parts=append(parts, strings.Trim(strings.TrimSpace(cur.String()), "\"")) }
	return parts
}
func navigateTomlTable(root *yaml.Node, path []string) *yaml.Node {
	cur := root
	for _, p := range path {
		idx,_,existing := findMapEntry(cur, p)
		if idx>=0 {
			en := effectiveNode(existing)
			if en.Kind == yaml.SequenceNode && len(en.Content)>0 {
				cur = effectiveNode(en.Content[len(en.Content)-1])
			} else if en.Kind == yaml.MappingNode {
				cur = en
			} else {
				m:=&yaml.Node{Kind: yaml.MappingNode, Tag:"!!map"}; cur.Content[idx]=m; cur=m
			}
		} else {
			m:=&yaml.Node{Kind: yaml.MappingNode, Tag:"!!map"}
			cur.Content = append(cur.Content, strNode(p), m)
			cur=m
		}
	}
	return cur
}
func parseTOMLValue(s string) (*yaml.Node, error) {
	s=strings.TrimSpace(s)
	if strings.HasPrefix(s, "\"") {
		// basic string
		if v,err:=strconv.Unquote(s); err==nil { return strNode(v), nil }
		// trim quotes
		return strNode(strings.Trim(s, "\"")), nil
	}
	if strings.HasPrefix(s, "'") { return strNode(strings.Trim(s,"'")), nil }
	if strings.HasPrefix(s, "[") && strings.HasSuffix(s, "]") {
		inner:=strings.TrimSpace(s[1:len(s)-1])
		seq:=&yaml.Node{Kind: yaml.SequenceNode, Tag:"!!seq"}
		if inner!="" {
			parts:=splitTopLevel(inner, ',')
			for _,p:=range parts { vn,err:=parseTOMLValue(strings.TrimSpace(p)); if err!=nil{return nil,err}; seq.Content=append(seq.Content, vn) }
		}
		return seq, nil
	}
	if strings.HasPrefix(s, "{") && strings.HasSuffix(s, "}") {
		inner:=strings.TrimSpace(s[1:len(s)-1])
		m:=&yaml.Node{Kind: yaml.MappingNode, Tag:"!!map"}
		if inner!="" {
			for _,p:=range splitTopLevel(inner, ',') {
				kv:=strings.SplitN(p,"=",2); if len(kv)!=2{continue}; vn,_:=parseTOMLValue(strings.TrimSpace(kv[1])); m.Content=append(m.Content, strNode(strings.TrimSpace(kv[0])), vn)
			}
		}
		return m, nil
	}
	if s=="true"||s=="false" { return boolNode(s=="true"), nil }
	// datetime try keep as timestamp string node
	if _,err:=parseTimeValue(s); err==nil && strings.Contains(s,"T") { return scalarNode("!!timestamp", s), nil }
	if iv,_,err:=parseIntValue(s); err==nil && !strings.ContainsAny(s,".eE") { return intNode(iv), nil }
	if fv,err:=parseFloatValue(s); err==nil { return scalarNode("!!float", formatFloat(fv)), nil }
	return strNode(s), nil
}
func splitTopLevel(s string, sep rune) []string {
	var parts []string; var cur strings.Builder; depth:=0; inStr:=false; esc:=false
	for _,r:=range s {
		if inStr { cur.WriteRune(r); if esc{esc=false}else if r=='\\'{esc=true}else if r=='"'{inStr=false}; continue }
		if r=='"' {inStr=true; cur.WriteRune(r); continue}
		if r=='['||r=='{'{depth++}
		if r==']'||r=='}'{depth--}
		if r==sep && depth==0 { parts=append(parts,cur.String()); cur.Reset(); continue }
		cur.WriteRune(r)
	}
	if cur.Len()>0 { parts=append(parts,cur.String()) }
	return parts
}

// INI decode: values always strings, sections maps
func decodeINIBytes(data []byte) (*yaml.Node, error) {
	root := &yaml.Node{Kind: yaml.MappingNode, Tag: "!!map"}
	current := root
	for _, raw := range strings.Split(string(data), "\n") {
		line:=strings.TrimSpace(raw)
		if line=="" || strings.HasPrefix(line,";") || strings.HasPrefix(line,"#") { continue }
		if strings.HasPrefix(line,"[") && strings.HasSuffix(line,"]") {
			name:=strings.TrimSpace(line[1:len(line)-1])
			// nested section names with '.' create nested maps
			path:=strings.Split(name,".")
			current = navigateTomlTable(root, path)
			continue
		}
		// key separator = or :
		idx:=strings.IndexAny(line, "=:") 
		if idx<0 { continue }
		key:=strings.TrimSpace(line[:idx]); val:=strings.TrimSpace(line[idx+1:])
		current.Content = append(current.Content, strNode(key), strNode(val))
	}
	return root, nil
}

// HCL decode (basic attributes & blocks)
func decodeHCLBytes(data []byte) (*yaml.Node, error) {
	// Use a simple parser for tokens
	p := &hclParser{s: string(data)}
	root, err := p.parseBody(true)
	if err!=nil { return nil, err }
	return root, nil
}
type hclParser struct { s string; pos int }
func (p *hclParser) skip() {
	for p.pos < len(p.s) {
		c:=p.s[p.pos]
		if c==' '||c=='\t'||c=='\n'||c=='\r' { p.pos++; continue }
		if c=='#' { for p.pos < len(p.s) && p.s[p.pos]!='\n' {p.pos++}; continue }
		if c=='/' && p.pos+1<len(p.s) && p.s[p.pos+1]=='/' { for p.pos < len(p.s) && p.s[p.pos]!='\n' {p.pos++}; continue }
		break
	}
}
func (p *hclParser) parseBody(top bool) (*yaml.Node, error) {
	m:=&yaml.Node{Kind: yaml.MappingNode, Tag:"!!map"}
	for {
		p.skip()
		if p.pos>=len(p.s) { break }
		if p.s[p.pos]=='}' { p.pos++; break }
		// read ident
		start:=p.pos
		for p.pos<len(p.s) && (isLuaIdentByte(p.s[p.pos])) { p.pos++ }
		if start==p.pos { p.pos++; continue }
		ident:=p.s[start:p.pos]
		p.skip()
		// labels (quoted strings or idents)
		var labels []string
		for p.pos<len(p.s) {
			p.skip()
			if p.pos<len(p.s) && p.s[p.pos]=='"' {
				// string
				end:=p.pos+1; for end<len(p.s)&&p.s[end]!='"'{if p.s[end]=='\\'{end++}; end++}
				if end>=len(p.s){break}
				q:=p.s[p.pos:end+1]; if v,err:=strconv.Unquote(q);err==nil{labels=append(labels,v)}else{labels=append(labels,strings.Trim(q,"\""))}
				p.pos=end+1; continue
			}
			if p.pos<len(p.s) && isIdentStartByte(p.s[p.pos]) {
				s2:=p.pos; for p.pos<len(p.s)&&isLuaIdentByte(p.s[p.pos]){p.pos++}; labels=append(labels,p.s[s2:p.pos]); continue
			}
			break
		}
		p.skip()
		if p.pos<len(p.s) && p.s[p.pos]=='=' {
			p.pos++; p.skip()
			val:=p.parseValue()
			addMapEntry(m, ident, val)
			continue
		}
		if p.pos<len(p.s) && p.s[p.pos]=='{' {
			p.pos++
			body, err:=p.parseBody(false); if err!=nil{return nil,err}
			// nested by labels
			node:=body
			for i:=len(labels)-1;i>=0;i-- {
				wrap:=&yaml.Node{Kind: yaml.MappingNode, Tag:"!!map"}
				wrap.Content=append(wrap.Content, strNode(labels[i]), node); node=wrap
			}
			addMapEntry(m, ident, node)
			continue
		}
		// unknown char
		if p.pos<len(p.s){p.pos++}
	}
	return m, nil
}
func (p *hclParser) parseValue() *yaml.Node {
	p.skip()
	if p.pos>=len(p.s){return nullNode()}
	c:=p.s[p.pos]
	if c=='"' { start:=p.pos; p.pos++; for p.pos<len(p.s)&&p.s[p.pos]!='"'{if p.s[p.pos]=='\\'{p.pos++}; p.pos++}; if p.pos<len(p.s){p.pos++}; q:=p.s[start:p.pos]; if v,err:=strconv.Unquote(q);err==nil{return strNode(v)}; return strNode(strings.Trim(q,"\"")) }
