		p.pos++; seq:=&yaml.Node{Kind: yaml.SequenceNode, Tag:"!!seq"}; for { p.skip(); if p.pos>=len(p.s){break}; if p.s[p.pos]==']'{p.pos++;break}; v:=p.parseValue(); seq.Content=append(seq.Content,v); p.skip(); if p.pos<len(p.s)&&p.s[p.pos]==','{p.pos++} }; return seq }
