	if iv,_,err:=parseIntValue(tok);err==nil&&!strings.ContainsAny(tok,".eE"){return intNode(iv)}
	if fv,err:=parseFloatValue(tok);err==nil&&(strings.ContainsAny(tok,".eE")){return scalarNode("!!float",formatFloat(fv))}
	return strNode(tok)
}
func isLuaIdentByte(b byte) bool { return b=='_'||(b>='a'&&b<='z')||(b>='A'&&b<='Z')||(b>='0'&&b<='9')||b=='-'||b=='.' }
func isIdentStartByte(b byte) bool { return b=='_'||(b>='a'&&b<='z')||(b>='A'&&b<='Z') }

// Lua decode (basic table constructor parser)
func decodeLuaBytes(data []byte) (*yaml.Node, error) {
	s:=strings.TrimSpace(string(data))
	// Must start with return? Original library executes Lua: return {...}; a bare {...} gives syntax error at column1
	if !strings.HasPrefix(s, "return") {
		// Mimic error format: bad file will be prefixed by caller; error itself is "@input line:1(column:1) near '{':   syntax error\n"
		// The lua parser error includes a trailing blank line.
		return nil, fmt.Errorf("@input line:1(column:1) near '%s':   syntax error\n", firstChar(s))
	}
	s=strings.TrimSpace(strings.TrimPrefix(s,"return"))
	s=strings.TrimSuffix(s,";")
	p:=&luaParser{s:s}
	n,err:=p.parseValue(); if err!=nil{return nil,err}
	return n,nil
}
func firstChar(s string) string { if s==""{return ""}; return string([]rune(s)[0]) }
type luaParser struct{s string; pos int}
func (p *luaParser) skip(){for p.pos<len(p.s)&&(p.s[p.pos]==' '||p.s[p.pos]=='\t'||p.s[p.pos]=='\n'||p.s[p.pos]=='\r'||p.s[p.pos]==';'||p.s[p.pos]==','){p.pos++}}
func (p *luaParser) skipSep(){for p.pos<len(p.s)&&(p.s[p.pos]==' '||p.s[p.pos]=='\t'||p.s[p.pos]=='\n'||p.s[p.pos]=='\r'){p.pos++}}
func (p *luaParser) parseValue() (*yaml.Node,error){
	p.skipSep()
	if p.pos>=len(p.s){return nullNode(),nil}
	c:=p.s[p.pos]
	if c=='{'{return p.parseTable()}
	if c=='"'||c=='\''{
		quote:=c; p.pos++; var sb strings.Builder; for p.pos<len(p.s)&&p.s[p.pos]!=quote{if p.s[p.pos]=='\\'&&p.pos+1<len(p.s){p.pos++; sb.WriteByte(p.s[p.pos]); p.pos++; continue}; sb.WriteByte(p.s[p.pos]); p.pos++}; if p.pos<len(p.s){p.pos++}; return strNode(sb.String()),nil
	}
	// word/number
	start:=p.pos; for p.pos<len(p.s)&&!strings.ContainsRune(",}] \t\n\r;",rune(p.s[p.pos])){p.pos++}
	tok:=p.s[start:p.pos]
	if tok=="true"||tok=="false"{return boolNode(tok=="true"),nil}
	if tok=="nil"{return nullNode(),nil}
	if iv,_,err:=parseIntValue(tok);err==nil&&!strings.ContainsAny(tok,".eE"){return intNode(iv),nil}
	if fv,err:=parseFloatValue(tok);err==nil{return scalarNode("!!float",formatFloat(fv)),nil}
	return strNode(tok),nil
}
func (p *luaParser) parseTable() (*yaml.Node,error){
	// assume at '{'
	p.pos++
	// Determine if array or map by scanning entries? We'll collect entries: each entry may be [k]=v, k=v, or value
	type entry struct{k *yaml.Node; v *yaml.Node; isValue bool}
	var entries []entry
	isArray:=true
	for {
		p.skip()
		if p.pos>=len(p.s){break}
		if p.s[p.pos]=='}'{p.pos++;break}
		// Check for key =
		save:=p.pos
		var keyNode *yaml.Node
		isKeyEntry:=false
		if p.s[p.pos]=='[' {
			p.pos++; kv,err:=p.parseValue(); if err!=nil{return nil,err}; keyNode=kv; p.skip(); if p.pos<len(p.s)&&p.s[p.pos]==']'{p.pos++}; p.skip(); if p.pos<len(p.s)&&p.s[p.pos]=='=' {p.pos++; isKeyEntry=true} else {p.pos=save}
		} else if isIdentStartByte(p.s[p.pos]) {
			s2:=p.pos; for p.pos<len(p.s)&&isLuaIdentByte(p.s[p.pos]){p.pos++}; name:=p.s[s2:p.pos]; p.skipSep(); if p.pos<len(p.s)&&p.s[p.pos]=='='{p.pos++; keyNode=strNode(name); isKeyEntry=true}else{p.pos=save}
		}
		if isKeyEntry {
			v,err:=p.parseValue(); if err!=nil{return nil,err}; entries=append(entries,entry{keyNode,v,false}); isArray=false
		} else {
			v,err:=p.parseValue(); if err!=nil{return nil,err}; entries=append(entries,entry{v:v,isValue:true})
		}
		p.skip()
	}
	if isArray {
		seq:=&yaml.Node{Kind: yaml.SequenceNode, Tag:"!!seq"}
		for _,e:=range entries{seq.Content=append(seq.Content,e.v)}
		return seq,nil
	}
	m:=&yaml.Node{Kind: yaml.MappingNode, Tag:"!!map"}
	idx:=0
	for _,e:=range entries{
		if e.isValue { m.Content=append(m.Content,intNode(int64(idx)),e.v); idx++ } else { m.Content=append(m.Content,e.k,e.v) }
	}
	return m,nil
}

