// XML decode
func decodeXMLBytes(data []byte) (*yaml.Node, error) {
	if len(strings.TrimSpace(string(data)))==0 {
		return nil, nil
	}
	attrPrefix, contentName, procPrefix, directiveName := xmlOpts()
	skipProc := globalOpts != nil && globalOpts.XMLSkipProcInst
	skipDirective := globalOpts != nil && globalOpts.XMLSkipDirectives
	dec := xml.NewDecoder(bytes.NewReader(data))
	// Configure strict?
	if globalOpts != nil && !globalOpts.XMLStrictMode {
		dec.Strict = false
	}
	// Use raw token if enabled (default true) - Go decoder Token vs RawToken difference for namespaces; RawToken preserves namespace prefixes as strings in Name.Space?
	useRaw := true
	if globalOpts != nil { useRaw = globalOpts.XMLRawToken }
	root := &yaml.Node{Kind: yaml.MappingNode, Tag: "!!map"}
	type elem struct {
		name string
		node *yaml.Node // map node for element content (building)
		text strings.Builder
		attrs []*yaml.Node // not used
	}
	var stack []*elem
	var currentRootSet bool
	addToParent := func(name string, node *yaml.Node) {
		if len(stack)==0 {
			// top level
			addMapEntry(root, name, node)
			currentRootSet = true
			_ = currentRootSet
		} else {
			parent := stack[len(stack)-1]
			addMapEntry(parent.node, name, node)
		}
	}
	_ = addToParent
	for {
		var tok xml.Token
		var err error
		if useRaw {
			tok, err = dec.RawToken()
		} else {
			tok, err = dec.Token()
		}
		if err == io.EOF { break }
		if err != nil { return nil, err }
		switch t := tok.(type) {
		case xml.StartElement:
			name := t.Name.Local
			if globalOpts != nil && globalOpts.XMLKeepNamespace && t.Name.Space != "" {
				// RawToken: Space is namespace URL or prefix depending. Original keeps namespace after parsing attributes: names like "ns:tag"? With RawToken, Space is prefix as in source.
				// Heuristic: if Space contains ":" or is short prefix and not URL, prefix it.
				if !strings.Contains(t.Name.Space, "/") && !strings.Contains(t.Name.Space, ".") {
					name = t.Name.Space + ":" + name
				}
			}
			m := &yaml.Node{Kind: yaml.MappingNode, Tag: "!!map"}
			e := &elem{name: name, node: m}
			// attributes: add at end? Original ordering: content first then attrs, but attrs stored; when finalizing, if there's content, content first.
			// Store attrs in map but insert later; we will add attrs now and reorder on close if text present.
			for _, a := range t.Attr {
				aname := a.Name.Local
				if globalOpts != nil && globalOpts.XMLKeepNamespace && a.Name.Space != "" && !strings.Contains(a.Name.Space, "/") {
					aname = a.Name.Space + ":" + aname
				}
				m.Content = append(m.Content, strNode(attrPrefix+aname), strNode(a.Value))
			}
			stack = append(stack, e)
		case xml.EndElement:
			if len(stack)==0 { continue }
			e := stack[len(stack)-1]; stack = stack[:len(stack)-1]
			text := strings.TrimSpace(e.text.String())
			var finalNode *yaml.Node
			if len(e.node.Content)==0 {
				// scalar text
				finalNode = strNode(text)
			} else {
				// if text non-empty, need content entry first
				if text != "" {
					// Build new map with content first, then existing (attrs etc)
					newMap := &yaml.Node{Kind: yaml.MappingNode, Tag: "!!map"}
					newMap.Content = append(newMap.Content, strNode(contentName), strNode(text))
					newMap.Content = append(newMap.Content, e.node.Content...)
					finalNode = newMap
				} else {
					finalNode = e.node
				}
			}
			// add to parent or root
			if len(stack)==0 {
				addMapEntry(root, e.name, finalNode)
			} else {
				addMapEntry(stack[len(stack)-1].node, e.name, finalNode)
			}
		case xml.CharData:
			if len(stack)>0 {
				stack[len(stack)-1].text.Write([]byte(t))
			}
		case xml.ProcInst:
			if skipProc { continue }
			name := procPrefix + t.Target
			val := string(t.Inst)
			addMapEntry(root, name, strNode(val))
		case xml.Directive:
			if skipDirective { continue }
			val := string(t)
			addMapEntry(root, directiveName, strNode(val))
		case xml.Comment:
			// ignore?
		}
	}
	// If root empty but there was text? return null
	if len(root.Content)==0 {
		return root, nil
	}
	return root, nil
}

func addMapEntry(m *yaml.Node, key string, val *yaml.Node) {
	// If key exists, convert to seq or append
	for i:=0;i+1<len(m.Content);i+=2 {
		if m.Content[i].Value == key {
			existing := m.Content[i+1]
			if existing.Kind == yaml.SequenceNode && existing.Tag == "!!seq" && isSeqFromDuplicate(existing) {
				existing.Content = append(existing.Content, val)
			} else {
				seq := &yaml.Node{Kind: yaml.SequenceNode, Tag: "!!seq"}
