	root := &yaml.Node{Kind: yaml.MappingNode, Tag: "!!map"}
	current := root
	lines := strings.Split(string(data), "\n")
	for _, raw := range lines {
		line := strings.TrimSpace(raw)
		if line=="" || strings.HasPrefix(line, "#") { continue }
		if strings.HasPrefix(line, "[[") && strings.HasSuffix(line, "]]") {
			// array of tables - not fully supported: create seq of maps
			name := strings.TrimSpace(line[2:len(line)-2])
			path := strings.Split(name, ".")
			// navigate/create parent map
			parent := navigateTomlTable(root, path[:len(path)-1])
			last := path[len(path)-1]
			idx,_,existing := findMapEntry(parent, last)
			var seq *yaml.Node
			if idx>=0 && effectiveNode(existing).Kind == yaml.SequenceNode { seq = effectiveNode(existing) } else {
				seq = &yaml.Node{Kind: yaml.SequenceNode, Tag: "!!seq"}
				if idx>=0 { parent.Content[idx]=seq } else { parent.Content = append(parent.Content, strNode(last), seq) }
			}
			m := &yaml.Node{Kind: yaml.MappingNode, Tag: "!!map"}
			seq.Content = append(seq.Content, m)
			current = m
			continue
		}
		if strings.HasPrefix(line, "[") && strings.HasSuffix(line, "]") {
			name := strings.TrimSpace(line[1:len(line)-1])
			// quoted parts?
			path := splitTomlPath(name)
			current = navigateTomlTable(root, path)
			continue
		}
		// key = value
		eq := strings.Index(line, "=")
		if eq<0 { return nil, fmt.Errorf("expected character =") }
		key := strings.TrimSpace(line[:eq])
		valStr := strings.TrimSpace(line[eq+1:])
		// strip inline comment? Not if in string. Simplify: if not quoted, cut # ?
		valNode, err := parseTOMLValue(valStr)
		if err != nil { return nil, err }
		path := splitTomlPath(key)
		target := current
		if len(path)>1 { target = navigateTomlTable(current, path[:len(path)-1]) }
		last := path[len(path)-1]
		target.Content = append(target.Content, strNode(last), valNode)
	}
	return root, nil
}
func splitTomlPath(s string) []string {
	var parts []string
	var cur strings.Builder
	inQ:=false
	for _,r:=range s {
		if r=='"' { inQ=!inQ; cur.WriteRune(r); continue }
		if r=='.' && !inQ { parts=append(parts, strings.Trim(strings.TrimSpace(cur.String()), "\"")); cur.Reset(); continue }
		cur.WriteRune(r)
	}
	if cur.Len()>0 { parts=append(parts, strings.Trim(strings.TrimSpace(cur.String()), "\"")) }
	return parts
}
func navigateTomlTable(root *yaml.Node, path []string) *yaml.Node {
	cur := root
	for _, p := range path {
		idx,_,existing := findMapEntry(cur, p)
		if idx>=0 {
			en := effectiveNode(existing)
			if en.Kind == yaml.SequenceNode && len(en.Content)>0 {
				cur = effectiveNode(en.Content[len(en.Content)-1])
			} else if en.Kind == yaml.MappingNode {
				cur = en
			} else {
				m:=&yaml.Node{Kind: yaml.MappingNode, Tag:"!!map"}; cur.Content[idx]=m; cur=m
			}
		} else {
			m:=&yaml.Node{Kind: yaml.MappingNode, Tag:"!!map"}
			cur.Content = append(cur.Content, strNode(p), m)
			cur=m
		}
	}
	return cur
}
func parseTOMLValue(s string) (*yaml.Node, error) {
	s=strings.TrimSpace(s)
	if strings.HasPrefix(s, "\"") {
		// basic string
		if v,err:=strconv.Unquote(s); err==nil { return strNode(v), nil }
		// trim quotes
		return strNode(strings.Trim(s, "\"")), nil
	}
	if strings.HasPrefix(s, "'") { return strNode(strings.Trim(s,"'")), nil }
	if strings.HasPrefix(s, "[") && strings.HasSuffix(s, "]") {
		inner:=strings.TrimSpace(s[1:len(s)-1])
		seq:=&yaml.Node{Kind: yaml.SequenceNode, Tag:"!!seq"}
		if inner!="" {
			parts:=splitTopLevel(inner, ',')
			for _,p:=range parts { vn,err:=parseTOMLValue(strings.TrimSpace(p)); if err!=nil{return nil,err}; seq.Content=append(seq.Content, vn) }
		}
		return seq, nil
	}
	if strings.HasPrefix(s, "{") && strings.HasSuffix(s, "}") {
		inner:=strings.TrimSpace(s[1:len(s)-1])
		m:=&yaml.Node{Kind: yaml.MappingNode, Tag:"!!map"}
		if inner!="" {
			for _,p:=range splitTopLevel(inner, ',') {
				kv:=strings.SplitN(p,"=",2); if len(kv)!=2{continue}; vn,_:=parseTOMLValue(strings.TrimSpace(kv[1])); m.Content=append(m.Content, strNode(strings.TrimSpace(kv[0])), vn)
			}
		}
		return m, nil
	}
	if s=="true"||s=="false" { return boolNode(s=="true"), nil }
	// datetime try keep as timestamp string node
	if _,err:=parseTimeValue(s); err==nil && strings.Contains(s,"T") { return scalarNode("!!timestamp", s), nil }
	if iv,_,err:=parseIntValue(s); err==nil && !strings.ContainsAny(s,".eE") { return intNode(iv), nil }
	if fv,err:=parseFloatValue(s); err==nil { return scalarNode("!!float", formatFloat(fv)), nil }
	return strNode(s), nil
}
func splitTopLevel(s string, sep rune) []string {
	var parts []string; var cur strings.Builder; depth:=0; inStr:=false; esc:=false
	for _,r:=range s {
		if inStr { cur.WriteRune(r); if esc{esc=false}else if r=='\\'{esc=true}else if r=='"'{inStr=false}; continue }
		if r=='"' {inStr=true; cur.WriteRune(r); continue}
		if r=='['||r=='{'{depth++}
		if r==']'||r=='}'{depth--}
		if r==sep && depth==0 { parts=append(parts,cur.String()); cur.Reset(); continue }
		cur.WriteRune(r)
	}
	if cur.Len()>0 { parts=append(parts,cur.String()) }
	return parts
}

// INI decode: values always strings, sections maps
func decodeINIBytes(data []byte) (*yaml.Node, error) {
	root := &yaml.Node{Kind: yaml.MappingNode, Tag: "!!map"}
	current := root
	for _, raw := range strings.Split(string(data), "\n") {
		line:=strings.TrimSpace(raw)
		if line=="" || strings.HasPrefix(line,";") || strings.HasPrefix(line,"#") { continue }
		if strings.HasPrefix(line,"[") && strings.HasSuffix(line,"]") {
			name:=strings.TrimSpace(line[1:len(line)-1])
			// nested section names with '.' create nested maps
			path:=strings.Split(name,".")
			current = navigateTomlTable(root, path)
			continue
		}
		// key separator = or :
		idx:=strings.IndexAny(line, "=:") 
		if idx<0 { continue }
		key:=strings.TrimSpace(line[:idx]); val:=strings.TrimSpace(line[idx+1:])
		current.Content = append(current.Content, strNode(key), strNode(val))
	}
	return root, nil
}

// HCL decode (basic attributes & blocks)
func decodeHCLBytes(data []byte) (*yaml.Node, error) {
	// Use a simple parser for tokens
	p := &hclParser{s: string(data)}
	root, err := p.parseBody(true)
	if err!=nil { return nil, err }
	return root, nil
}
type hclParser struct { s string; pos int }
func (p *hclParser) skip() {
	for p.pos < len(p.s) {
		c:=p.s[p.pos]
		if c==' '||c=='\t'||c=='\n'||c=='\r' { p.pos++; continue }
		if c=='#' { for p.pos < len(p.s) && p.s[p.pos]!='\n' {p.pos++}; continue }
		if c=='/' && p.pos+1<len(p.s) && p.s[p.pos+1]=='/' { for p.pos < len(p.s) && p.s[p.pos]!='\n' {p.pos++}; continue }
		break
	}
}
func (p *hclParser) parseBody(top bool) (*yaml.Node, error) {
	m:=&yaml.Node{Kind: yaml.MappingNode, Tag:"!!map"}
	for {
		p.skip()
		if p.pos>=len(p.s) { break }
		if p.s[p.pos]=='}' { p.pos++; break }
		// read ident
		start:=p.pos
		for p.pos<len(p.s) && (isLuaIdentByte(p.s[p.pos])) { p.pos++ }
		if start==p.pos { p.pos++; continue }
		ident:=p.s[start:p.pos]
		p.skip()
		// labels (quoted strings or idents)
		var labels []string
		for p.pos<len(p.s) {
			p.skip()
			if p.pos<len(p.s) && p.s[p.pos]=='"' {
				// string
				end:=p.pos+1; for end<len(p.s)&&p.s[end]!='"'{if p.s[end]=='\\'{end++}; end++}
				if end>=len(p.s){break}
				q:=p.s[p.pos:end+1]; if v,err:=strconv.Unquote(q);err==nil{labels=append(labels,v)}else{labels=append(labels,strings.Trim(q,"\""))}
				p.pos=end+1; continue
			}
			if p.pos<len(p.s) && isIdentStartByte(p.s[p.pos]) {
				s2:=p.pos; for p.pos<len(p.s)&&isLuaIdentByte(p.s[p.pos]){p.pos++}; labels=append(labels,p.s[s2:p.pos]); continue
			}
			break
		}
		p.skip()
		if p.pos<len(p.s) && p.s[p.pos]=='=' {
			p.pos++; p.skip()
			val:=p.parseValue()
			addMapEntry(m, ident, val)
			continue
		}
		if p.pos<len(p.s) && p.s[p.pos]=='{' {
			p.pos++
			body, err:=p.parseBody(false); if err!=nil{return nil,err}
			// nested by labels
			node:=body
			for i:=len(labels)-1;i>=0;i-- {
				wrap:=&yaml.Node{Kind: yaml.MappingNode, Tag:"!!map"}
				wrap.Content=append(wrap.Content, strNode(labels[i]), node); node=wrap
			}
			addMapEntry(m, ident, node)
			continue
		}
		// unknown char
		if p.pos<len(p.s){p.pos++}
	}
	return m, nil
}
func (p *hclParser) parseValue() *yaml.Node {
	p.skip()
	if p.pos>=len(p.s){return nullNode()}
	c:=p.s[p.pos]
	if c=='"' { start:=p.pos; p.pos++; for p.pos<len(p.s)&&p.s[p.pos]!='"'{if p.s[p.pos]=='\\'{p.pos++}; p.pos++}; if p.pos<len(p.s){p.pos++}; q:=p.s[start:p.pos]; if v,err:=strconv.Unquote(q);err==nil{return strNode(v)}; return strNode(strings.Trim(q,"\"")) }
	if c=='[' { // list
		p.pos++; seq:=&yaml.Node{Kind: yaml.SequenceNode, Tag:"!!seq"}; for { p.skip(); if p.pos>=len(p.s){break}; if p.s[p.pos]==']'{p.pos++;break}; v:=p.parseValue(); seq.Content=append(seq.Content,v); p.skip(); if p.pos<len(p.s)&&p.s[p.pos]==','{p.pos++} }; return seq }
	if c=='{' { p.pos++; body,_:=p.parseBody(false); return body }
	// bare word/number until comma/newline/brace
	start:=p.pos; for p.pos<len(p.s) && !strings.ContainsRune(",\n}] ", rune(p.s[p.pos])) {p.pos++}
	tok:=p.s[start:p.pos]
	if tok=="true"||tok=="false"{return boolNode(tok=="true")}
	if iv,_,err:=parseIntValue(tok);err==nil&&!strings.ContainsAny(tok,".eE"){return intNode(iv)}
	if fv,err:=parseFloatValue(tok);err==nil&&(strings.ContainsAny(tok,".eE")){return scalarNode("!!float",formatFloat(fv))}
	return strNode(tok)
}
func isLuaIdentByte(b byte) bool { return b=='_'||(b>='a'&&b<='z')||(b>='A'&&b<='Z')||(b>='0'&&b<='9')||b=='-'||b=='.' }
func isIdentStartByte(b byte) bool { return b=='_'||(b>='a'&&b<='z')||(b>='A'&&b<='Z') }

// Lua decode (basic table constructor parser)
func decodeLuaBytes(data []byte) (*yaml.Node, error) {
	s:=strings.TrimSpace(string(data))
	// Must start with return? Original library executes Lua: return {...}; a bare {...} gives syntax error at column1
	if !strings.HasPrefix(s, "return") {
		// Mimic error format: bad file will be prefixed by caller; error itself is "@input line:1(column:1) near '{':   syntax error\n"
		// The lua parser error includes a trailing blank line.
		return nil, fmt.Errorf("@input line:1(column:1) near '%s':   syntax error\n", firstChar(s))
	}
	s=strings.TrimSpace(strings.TrimPrefix(s,"return"))
	s=strings.TrimSuffix(s,";")
	p:=&luaParser{s:s}
	n,err:=p.parseValue(); if err!=nil{return nil,err}
	return n,nil
}
func firstChar(s string) string { if s==""{return ""}; return string([]rune(s)[0]) }
type luaParser struct{s string; pos int}
func (p *luaParser) skip(){for p.pos<len(p.s)&&(p.s[p.pos]==' '||p.s[p.pos]=='\t'||p.s[p.pos]=='\n'||p.s[p.pos]=='\r'||p.s[p.pos]==';'||p.s[p.pos]==','){p.pos++}}
func (p *luaParser) skipSep(){for p.pos<len(p.s)&&(p.s[p.pos]==' '||p.s[p.pos]=='\t'||p.s[p.pos]=='\n'||p.s[p.pos]=='\r'){p.pos++}}
func (p *luaParser) parseValue() (*yaml.Node,error){
	p.skipSep()
	if p.pos>=len(p.s){return nullNode(),nil}
	c:=p.s[p.pos]
	if c=='{'{return p.parseTable()}
	if c=='"'||c=='\''{
		quote:=c; p.pos++; var sb strings.Builder; for p.pos<len(p.s)&&p.s[p.pos]!=quote{if p.s[p.pos]=='\\'&&p.pos+1<len(p.s){p.pos++; sb.WriteByte(p.s[p.pos]); p.pos++; continue}; sb.WriteByte(p.s[p.pos]); p.pos++}; if p.pos<len(p.s){p.pos++}; return strNode(sb.String()),nil
	}
	// word/number
	start:=p.pos; for p.pos<len(p.s)&&!strings.ContainsRune(",}] \t\n\r;",rune(p.s[p.pos])){p.pos++}
	tok:=p.s[start:p.pos]
	if tok=="true"||tok=="false"{return boolNode(tok=="true"),nil}
	if tok=="nil"{return nullNode(),nil}
	if iv,_,err:=parseIntValue(tok);err==nil&&!strings.ContainsAny(tok,".eE"){return intNode(iv),nil}
	if fv,err:=parseFloatValue(tok);err==nil{return scalarNode("!!float",formatFloat(fv)),nil}
	return strNode(tok),nil
}
func (p *luaParser) parseTable() (*yaml.Node,error){
	// assume at '{'
	p.pos++
	// Determine if array or map by scanning entries? We'll collect entries: each entry may be [k]=v, k=v, or value
	type entry struct{k *yaml.Node; v *yaml.Node; isValue bool}
	var entries []entry
	isArray:=true
	for {
		p.skip()
		if p.pos>=len(p.s){break}
		if p.s[p.pos]=='}'{p.pos++;break}
		// Check for key =
		save:=p.pos
		var keyNode *yaml.Node
		isKeyEntry:=false
		if p.s[p.pos]=='[' {
			p.pos++; kv,err:=p.parseValue(); if err!=nil{return nil,err}; keyNode=kv; p.skip(); if p.pos<len(p.s)&&p.s[p.pos]==']'{p.pos++}; p.skip(); if p.pos<len(p.s)&&p.s[p.pos]=='=' {p.pos++; isKeyEntry=true} else {p.pos=save}
		} else if isIdentStartByte(p.s[p.pos]) {
			s2:=p.pos; for p.pos<len(p.s)&&isLuaIdentByte(p.s[p.pos]){p.pos++}; name:=p.s[s2:p.pos]; p.skipSep(); if p.pos<len(p.s)&&p.s[p.pos]=='='{p.pos++; keyNode=strNode(name); isKeyEntry=true}else{p.pos=save}
		}
		if isKeyEntry {
			v,err:=p.parseValue(); if err!=nil{return nil,err}; entries=append(entries,entry{keyNode,v,false}); isArray=false
		} else {
			v,err:=p.parseValue(); if err!=nil{return nil,err}; entries=append(entries,entry{v:v,isValue:true})
		}
		p.skip()
	}
	if isArray {
		seq:=&yaml.Node{Kind: yaml.SequenceNode, Tag:"!!seq"}
		for _,e:=range entries{seq.Content=append(seq.Content,e.v)}
		return seq,nil
	}
	m:=&yaml.Node{Kind: yaml.MappingNode, Tag:"!!map"}
	idx:=0
	for _,e:=range entries{
		if e.isValue { m.Content=append(m.Content,intNode(int64(idx)),e.v); idx++ } else { m.Content=append(m.Content,e.k,e.v) }
	}
	return m,nil
}

var _ = bytes.NewReader
EOF
