}

func applyColorYAML(s string) string {
	if !colorsEnabled() { return s }
	// Very approximate yq colouring: keys cyan (36), string values green (32), number/bool magenta bright (95), null none.
	// yq's implementation colourises individual scalars during encoding, resulting in some empty codes at line starts.
	// To approximate simple outputs, we process line by line.
	lines := strings.Split(s, "\n")
	for i, line := range lines {
		lines[i] = colorizeYAMLLine(line)
	}
	return strings.Join(lines, "\n")
}

func colorizeYAMLLine(line string) string {
	// Leave document separators and comments uncoloured? Original comments? Skip separators
	if line=="---" || strings.HasPrefix(line, "#") { return line }
	// Flow / block handling simple cases:
	// "key: value"
	// "- value"
	// "- key: value" handled partially
	// We'll handle scalar values after ": " and after "- "
	// Find key colon
	indent := ""
	rest := line
	for strings.HasPrefix(rest, " ") { indent += " "; rest = rest[1:] }
	// sequence dash
	prefix := indent
	if strings.HasPrefix(rest, "- ") {
		prefix += "-"
		rest = rest[1:] // keep leading space for value colouring as original: "-\x1b[95m 1..."
		// rest starts with space
		// colour scalar rest
		return prefix + colorScalarChunk(rest)
	}
	// map key
	colonIdx := strings.Index(rest, ":")
	if colonIdx > 0 {
		key := rest[:colonIdx]
		after := rest[colonIdx+1:] // includes space if value
		// If key is quoted, colour whole quoted key? Original keys are cyan without quotes? For plain keys:
		coloredKey := "\x1b[36m"+key+"\x1b[0m"
		if after == "" {
			// nested map: yq emits \x1b[36m\x1b[0m after colon for empty? It gave "a:\x1b[36m\x1b[0m\n"
			// Mimic: add empty cyan code
			return prefix + coloredKey + ":" + "\x1b[36m\x1b[0m"
		}
		// after can be flow seq/map or scalar
		return prefix + coloredKey + ":" + colorValueChunk(after)
	}
	// plain scalar line (string content indented, block scalar etc)
	return prefix + colorScalarChunk(rest)
	// prefix already includes indent, rest is content; colorScalarChunk expects leading spaces included
}

