	// s starts with space for scalar, or " [" etc
	if strings.HasPrefix(s, " [") || strings.HasPrefix(s, " {") {
		// flow: colour elements inside
		return colorFlow(s)
	}
	return colorScalarChunk(s)
}
func colorFlow(s string) string {
	// naive: colour numbers/strings inside brackets
	// Keep brackets plain.
	var out strings.Builder
	i:=0
	for i < len(s) {
		c:=s[i]
		if c=='"' {
			// quoted string
			j:=i+1; for j<len(s) && s[j]!='"' { if s[j]=='\\' {j++}; j++ }
			if j<len(s){j++}
			out.WriteString("\x1b[32m"+s[i:j]+"\x1b[0m"); i=j; continue
		}
		if c==' ' && i+1<len(s) && (isDigitByte(s[i+1]) || s[i+1]=='-' ) {
			// number with leading space like ', 2'
			j:=i+1; for j<len(s) && !strings.ContainsRune(",]} \n", rune(s[j])) {j++}
			out.WriteString("\x1b[95m"+s[i:j]+"\x1b[0m"); i=j; continue
		}
		if isDigitByte(c) || c=='-' {
			j:=i; for j<len(s) && !strings.ContainsRune(",]} \n", rune(s[j])) {j++}
			tok:=s[i:j]
