func isNumberToken(s string) bool {
	if s==""{return false}
	for _,r:=range s{ if !(r>='0'&&r<='9'||r=='.'||r=='-'||r=='+'||r=='e'||r=='E'){return false} }
	return true
}
func colorScalarChunk(s string) string {
	// s may start with space(s)
	trim := strings.TrimLeft(s, " ")
	lead := s[:len(s)-len(trim)]
	if trim=="" { return s }
