	if !colorsEnabled() { return s }
	// Approximation: colour keys cyan and numbers magenta per line similar to yaml but json keys quoted
	lines:=strings.Split(s,"\n")
	for i,line:=range lines{ lines[i]=colorizeJSONLine(line) }
	return strings.Join(lines,"\n")
}
func colorizeJSONLine(line string) string {
	// "key": value
	trim:=strings.TrimLeft(line," ")
	indent:=line[:len(line)-len(trim)]
	if strings.HasPrefix(trim, "\"") {
		// find closing quote
		end:=1; for end<len(trim) && trim[end]!='"' { if trim[end]=='\\'{end++}; end++ }
		if end<len(trim) {
			key:=trim[:end+1]; rest:=trim[end+1:]
			if strings.HasPrefix(rest, ":") {
				val:=rest[1:]
				return indent+"\x1b[36m"+key+"\x1b[0m:"+colorScalarChunk(val)
			}
			// string value in array
			return indent+"\x1b[32m"+trim+"\x1b[0m"
		}
	}
	if isNumberToken(trim) || trim=="true"||trim=="false" {
		// strip trailing comma
		suffix:=""; core:=trim; if strings.HasSuffix(core,","){suffix=","; core=core[:len(core)-1]}
		if trim=="true"||trim=="false"||isNumberToken(core){ return indent+"\x1b[95m"+core+"\x1b[0m"+suffix }
	}
	return line
}
