package main

import (
	"fmt"
	"io"
	"strings"

	"gopkg.in/yaml.v3"
)

type Printer struct {
	w       io.Writer
	format  string // canonical output format
	first   bool
	prevID  int
	hasPrev bool
	// for exit status tracking
	lastResult *Candidate
	resultCount int
}

func newPrinter(w io.Writer, format string) *Printer {
	return &Printer{w: w, format: format, first: true}
}

func (p *Printer) Print(c *Candidate) error {
	if c == nil || c.Node == nil {
		return nil
	}
	p.lastResult = c
	p.resultCount++
	switch p.format {
	case "yaml":
		return p.printYAML(c)
	case "json":
		s, err := encodeJSONWithIndent(effectiveNodeForPrint(c), outputIndent())
		if err != nil { return err }
		_, err = io.WriteString(p.w, applyColorJSON(s, c)+"\n")
		p.first = false
		return err
	case "kyaml":
		s := encodeKYAMLToString(effectiveNodeForPrint(c))
		_, err := io.WriteString(p.w, s+"\n")
		p.first = false
		return err
	case "csv", "tsv":
		sep := ','; if p.format=="tsv" { sep='\t' }
		s, err := encodeCSVString(c.Node, sep)
		if err != nil { return err }
		_, err = io.WriteString(p.w, s)
		p.first = false
		return err
	case "props":
		// scalar special
		if effectiveNode(c.Node)!=nil && effectiveNode(c.Node).Kind == yaml.ScalarNode {
			_, err := io.WriteString(p.w, effectiveNode(c.Node).Value+"\n")
			p.first=false; return err
		}
		s, err := encodePropsString(c.Node)
		if err != nil { return err }
		_, err = io.WriteString(p.w, s)
		p.first=false; return err
	case "shell":
		s, err := encodeShellString(c.Node)
		if err != nil { return err }
		_, err = io.WriteString(p.w, s); p.first=false; return err
	case "toml":
		s, err := encodeTOMLString(c.Node)
		if err != nil { return err }
		_, err = io.WriteString(p.w, s); p.first=false; return err
	case "ini":
		s, err := encodeINIString(c.Node)
		if err != nil { return err }
		_, err = io.WriteString(p.w, s); p.first=false; return err
	case "hcl":
		s, err := encodeHCLString(c.Node)
		if err != nil { return err }
		_, err = io.WriteString(p.w, s); p.first=false; return err
	case "lua":
		s, err := encodeLuaString(c.Node)
		if err != nil { return err }
		_, err = io.WriteString(p.w, s); p.first=false; return err
	case "xml":
		s, err := encodeXMLString(c.Node)
		if err != nil { return err }
		_, err = io.WriteString(p.w, s); p.first=false; return err
	case "base64":
		node := effectiveNode(c.Node)
		if node == nil || node.Kind != yaml.ScalarNode {
			return fmt.Errorf("cannot encode %s as base64, can only operate on strings", nodeTag(node))
		}
		_, err := io.WriteString(p.w, encodeBase64Str(node.Value)); p.first=false; return err
	case "uri":
		node := effectiveNode(c.Node)
		if node == nil || node.Kind != yaml.ScalarNode {
			return fmt.Errorf("cannot encode %s as URI, can only operate on strings. Please first pipe through another encoding operator to convert the value to a string", nodeTag(node))
		}
		_, err := io.WriteString(p.w, encodeURIStr(node.Value)); p.first=false; return err
	}
	return p.printYAML(c)
}

func effectiveNodeForPrint(c *Candidate) *yaml.Node {
	// For printing, if candidate is a key, just its node. Alias handling by encoders.
	return c.Node
}

func outputIndent() int {
	if globalOpts == nil { return 2 }
	return globalOpts.Indent
}

func (p *Printer) printYAML(c *Candidate) error {
	node := c.Node
	// unwrap scalar
	if globalOpts != nil && globalOpts.UnwrapScalar && !globalOpts.NulOutput {
		if en := unwrapScalarNode(node); en != nil {
			// write raw value
			if en.Kind == yaml.ScalarNode {
				_, err := io.WriteString(p.w, en.Value+"\n")
				p.updatePrev(c)
				p.first = false
				return err
			}
		}
	}
	if globalOpts != nil && globalOpts.NulOutput {
		// NUL separated values: if scalar, write raw + NUL; else yaml + NUL? Observed for maps? We'll handle scalar first
		if en := unwrapScalarNode(node); en != nil && en.Kind == yaml.ScalarNode {
			if strings.Contains(en.Value, "\x00") {
				if globalOpts.UnwrapScalar {
					return fmt.Errorf("unwrapped scalar contains NUL character")
				}
			}
			_, err := io.WriteString(p.w, en.Value+"\x00")
			p.updatePrev(c); p.first=false; return err
		}
		// non-scalar: encode then replace trailing newline with NUL?
		s, err := encodeYAMLToString(node)
		if err != nil { return err }
		s = applyColorYAML(s)
		// For NUL output on non-scalars original behaviour unknown; write s without trailing newline + NUL
		s = strings.TrimSuffix(s, "\n")
		_, err = io.WriteString(p.w, s+"\x00")
		p.updatePrev(c); p.first=false; return err
	}
	// General YAML encode
	s, err := encodeYAMLToString(node)
	if err != nil { return err }
	// Document separator handling
	var prefix string
	needsSep := false
	if globalOpts == nil || !globalOpts.NoDoc {
		if !p.first && p.hasPrev && c.PrintID != p.prevID {
			needsSep = true
		}
	}
	if needsSep {
		prefix = "---\n"
	}
	// Leading separator for first doc
	if p.first && c.LeadingSep && c.Node == c.RootNode && (globalOpts==nil || !globalOpts.NoDoc) {
		s = insertLeadingSep(s)
	} else if prefix != "" {
		s = prefix + s
	}
	s = applyColorYAML(s)
	// If colour applied after sep insertion, leading sep line should not be coloured.
	_, err = io.WriteString(p.w, s)
	p.updatePrev(c)
	p.first = false
	return err
}

func (p *Printer) updatePrev(c *Candidate) {
	p.prevID = c.PrintID
	p.hasPrev = true
}

func unwrapScalarNode(n *yaml.Node) *yaml.Node {
	if n == nil { return nil }
	if n.Kind == yaml.ScalarNode { return n }
	if n.Kind == yaml.AliasNode {
		// Unwrapping alias returns its target's scalar value? But original printing of alias selection... we return alias node itself will be handled as scalar? Alias node Value is anchor name, not correct.
		// If alias to scalar, return alias target
		if n.Alias != nil && n.Alias.Kind == yaml.ScalarNode {
			// However selecting .b where b is *x, output in original is? It prints "1"? Let's trust unwrap returns target value.
			// But to distinguish, caller checks Kind scalar: alias target is scalar.
			return n.Alias
		}
	}
	return nil
}

func insertLeadingSep(s string) string {
	// Insert --- after leading comment lines
	lines := strings.Split(s, "\n")
	idx := 0
	for idx < len(lines) && strings.HasPrefix(lines[idx], "#") {
		idx++
	}
	// Insert before idx
	var out []string
	out = append(out, lines[:idx]...)
	out = append(out, "---")
	out = append(out, lines[idx:]...)
	return strings.Join(out, "\n")
}
