	HeaderPreprocess bool
	Indent int
	Inplace bool
	InputFormat string
	OutputFormat string
	LuaGlobals bool
	LuaPrefix string
	LuaSuffix string
	LuaUnquoted bool
	NoDoc bool
	NulOutput bool
	NullInput bool
	Pretty bool
	PropsArrayBrackets bool
