	// Preprocess args: default to eval if first arg is non-flag and not a known command
	args := os.Args[1:]
	if len(args) > 0 {
		first := args[0]
		known := map[string]bool{"eval":true,"e":true,"eval-all":true,"ea":true,"completion":true,"shell-completion":true,"__complete":true,"__completeNoDesc":true,"help":false}
		if _, isKnown := known[first]; !isKnown && !strings.HasPrefix(first, "-") {
			// insert eval
			newArgs := append([]string{"eval"}, args...)
			rootCmd.SetArgs(newArgs)
		} else if first == "help" {
			// Original treats help as expression (eval), so insert eval as well
			newArgs := append([]string{"eval"}, args...)
			rootCmd.SetArgs(newArgs)
		}
	}
	if err := rootCmd.Execute(); err != nil {
		os.Exit(1)
	}
}

func buildRoot(cfg *Config) *cobra.Command {
	rootCmd := &cobra.Command{
		Use: "yq [flags]",
		Long: longIntro,
		Example: "\n# yq tries to auto-detect the file format based off the extension, and defaults to YAML if it's unknown (or piping through STDIN)\n# Use the '-p/--input-format' flag to specify a format type.\ncat file.xml | yq -p xml\n\n# read the \"stuff\" node from \"myfile.yml\"\nyq '.stuff' < myfile.yml\n\n# update myfile.yml in place\nyq -i '.stuff = \"foo\"' myfile.yml\n\n# print contents of sample.json as idiomatic YAML\nyq -P -oy sample.json\n",
		Args: cobra.ArbitraryArgs,
		RunE: func(cmd *cobra.Command, args []string) error {
			if cfg.VersionFlag {
				fmt.Println(versionStr)
				return nil
			}
			runEvalAndExit(args, false)
			return nil
		},
		SilenceUsage: false,
		SilenceErrors: false,
	}
	// detect tty for colors default
	if isTTY(os.Stdout) {
		cfg.ColorsDefault = true
	}
	addPersistentFlags(rootCmd, cfg)
	rootCmd.Flags().BoolVarP(&cfg.VersionFlag, "version", "V", false, "Print version information and quit")

	evalCmd := &cobra.Command{
		Use: "eval [expression] [yaml_file1]... [flags]",
		Aliases: []string{"e"},
		Short: "(default) Apply the expression to each document in each yaml file in sequence",
		Long: longIntro + "\n\n## Evaluate Sequence ##\nThis command iterates over each yaml document from each given file, applies the \nexpression and prints the result in sequence.",
		Example: "\n# Reads field under the given path for each file\nyq e '.a.b' f1.yml f2.yml \n\n# Prints out the file\nyq e sample.yaml \n\n# Pipe from STDIN\n## use '-' as a filename to pipe from STDIN\ncat file2.yml | yq e '.a.b' file1.yml - file3.yml\n\n# Creates a new yaml document\n## Note that editing an empty file does not work.\nyq e -n '.a.b.c = \"cat\"' \n\n# Update a file in place\nyq e '.a.b = \"cool\"' -i file.yaml \n",
		Args: cobra.ArbitraryArgs,
		RunE: func(cmd *cobra.Command, args []string) error {
			runEvalAndExit(args, false)
			return nil
		},
	}
	evalAllCmd := &cobra.Command{
		Use: "eval-all [expression] [yaml_file1]... [flags]",
		Aliases: []string{"ea"},
		Short: "Loads _all_ yaml documents of _all_ yaml files and runs expression once",
		Long: longIntro + "\n\n## Evaluate All ##\nThis command loads _all_ yaml documents of _all_ yaml files and runs expression once\nUseful when you need to run an expression across several yaml documents or files (like merge).\nNote that it consumes more memory than eval.",
		Example: "\n# Merge f2.yml into f1.yml (in place)\nyq eval-all --inplace 'select(fileIndex == 0) * select(fileIndex == 1)' f1.yml f2.yml\n## the same command and expression using shortened names:\nyq ea -i 'select(fi == 0) * select(fi == 1)' f1.yml f2.yml\n\n\n# Merge all given files\nyq ea '. as $item ireduce ({}; . * $item )' file1.yml file2.yml ...\n\n# Pipe from STDIN\n## use '-' as a filename to pipe from STDIN\ncat file2.yml | yq ea '.a.b' file1.yml - file3.yml\n",
		Args: cobra.ArbitraryArgs,
		RunE: func(cmd *cobra.Command, args []string) error {
			runEvalAndExit(args, true)
			return nil
		},
	}
	rootCmd.AddCommand(evalCmd)
	rootCmd.AddCommand(evalAllCmd)
	return rootCmd
}

func isTTY(f *os.File) bool {
	fi, err := f.Stat()
	if err != nil { return false }
	return (fi.Mode() & os.ModeCharDevice) != 0
}

