func runEvalAndExit(args []string, isEvalAll bool) {
	if err := doEval(args, isEvalAll); err != nil {
		if err == errExitStatus {
			// Message already printed
			os.Exit(1)
		}
		fmt.Fprintf(os.Stderr, "Error: %v\n", err)
		os.Exit(1)
	}
}

var errExitStatus = fmt.Errorf("exit status")
EOF
"}

