func canonicalFormat(s string, isOutput bool) (string, error) {
	if v, ok := formatAliases[s]; ok {
		if !isOutput && v=="shell" {
			return "", fmt.Errorf("unknown format '%s' please use [yaml|y|kyaml|ky|json|j|props|p|csv|c|tsv|t|xml|x|base64|uri|toml|hcl|h|shell|s|lua|l|ini|i]", s)
		}
		return v, nil
	}
