	case "yaml": return "yml"
	case "json": return "json"
	case "props": return "properties"
	case "csv": return "csv"
	case "tsv": return "tsv"
	case "xml": return "xml"
	case "toml": return "toml"
	case "ini": return "ini"
	case "lua": return "lua"
	case "hcl": return "hcl"
	case "kyaml": return "yaml"
	case "base64": return "txt"
	case "uri": return "txt"
	case "shell": return "sh"
	default: return format
	}
}

func isRegularFile(p string) bool {
	fi, err := os.Stat(p)
	return err == nil && !fi.IsDir()
}

func doEval(args []string, isEvalAll bool) error {
	cfg := globalOpts
	if cfg.Verbose {
		logVerbose(fmt.Sprintf("checking '%s' is a file", strings.Join(args," ")))
	}
	// validate formats first (original validates before reading?)
	inputFormatRaw := cfg.InputFormat
	outputFormatRaw := cfg.OutputFormat
	// canonical input (auto allowed)
	specifiedInput, err := canonicalFormat(inputFormatRaw, false)
	if err != nil { return err }
	specifiedOutput, err := canonicalFormat(outputFormatRaw, true)
	if err != nil { return err }
	// expression/file resolution
	exprStr, files, err := resolveExprFiles(args)
	if err != nil { return err }
	// null-input validation
	if cfg.NullInput && len(files)>0 {
		return fmt.Errorf("cannot pass files in when using null-input flag")
	}
	// inplace validation
	if cfg.Inplace {
		if len(files)==0 || files[0]=="-" {
			return fmt.Errorf("write in place flag only applicable when giving an expression and at least one file")
		}
	}
	// parse expression
	exprAST, err := parseExpressionString(exprStr)
	if err != nil { return err }
	// split expression
	var splitAST *AST
	splitExpStr := cfg.SplitExp
	if cfg.SplitExpFile != "" {
		b, err := os.ReadFile(cfg.SplitExpFile)
		if err != nil { return err }
		splitExpStr = string(b)
	}
	if splitExpStr != "" {
		splitAST, err = parseExpressionString(strings.TrimSpace(splitExpStr))
		if err != nil { return err }
	}
	// Determine output writer: inplace buffer, split handled elsewhere, stdout
	var outWriter io.Writer = os.Stdout
	var inplaceBuf *bytes.Buffer
	if cfg.Inplace {
		inplaceBuf = &bytes.Buffer{}
		outWriter = inplaceBuf
	}
	// Determine output format
	outputFormat := specifiedOutput
	if outputFormat == "auto" {
		if len(files)>0 && files[0] != "-" {
			outputFormat = formatFromFilename(files[0])
			// props extension maps to props, etc.
			if formatFromFilename(files[0])=="yaml" && specifiedInput != "auto" {
				// If input format explicitly specified and output auto and no file? stdin case handled
			}
		} else {
			outputFormat = "yaml"
		}
	}
	// Front matter handling (single input case simplified)
	isFront := cfg.FrontMatter != ""
	// For pretty print, we will modify docs after decoding
	printer := newPrinter(outWriter, outputFormat)
	// tracking for exit-status
	tracker := &statusTracker{}
	globalPrintID := 0
	// Helper to evaluate and print list of doc candidates
	evaluateDocs := func(docs []*Candidate) error {
		if isEvalAll {
			// Called once with all docs (handled outside)
			return nil
		}
		for _, doc := range docs {
			if cfg.Pretty { clearStyles(doc.Node) }
			ctx := &EvalContext{Candidates: []*Candidate{doc}, Vars: map[string][]*Candidate{}}
			results, err := evalAST(exprAST, ctx)
			if err != nil { return err }
			if len(results)==0 { tracker.markNoMatch() }
			for _, r := range results {
				if err := outputResult(printer, r, splitAST, outputFormat, tracker); err != nil { return err }
			}
		}
		return nil
	}
	if cfg.NullInput {
		doc := makeDocCandidate(nullNode(), 0, 0, "-", false, 0)
		if cfg.Pretty { clearStyles(doc.Node) }
		ctx := &EvalContext{Candidates: []*Candidate{doc}, Vars: map[string][]*Candidate{}}
		results, err := evalAST(exprAST, ctx)
		if err != nil { return err }
		if len(results)==0 { tracker.markNoMatch() }
		for _, r := range results {
			if err := outputResult(printer, r, splitAST, outputFormat, tracker); err != nil { return err }
		}
	} else if isEvalAll {
		// Load all docs from all sources
		var allDocs []*Candidate
		if len(files)==0 { files = []string{"-"} }
		for fileIdx, fname := range files {
			docs, rest, isFM, err := loadInput(fname, fileIdx, specifiedInput, &globalPrintID, isFront && fileIdx==0)
			if err != nil { return err }
			if isFM {
				// Front matter for eval-all: handle separately for first file: evaluate on fm docs and print
				// Simplify: evaluate fm docs individually and append rest after for process
				for _, doc := range docs { if cfg.Pretty { clearStyles(doc.Node) } }
				ctxDocs := docs
				ctx := &EvalContext{Candidates: ctxDocs, Vars: map[string][]*Candidate{}}
				results, err := evalAST(exprAST, ctx)
				if err != nil { return err }
				if len(results)==0 { tracker.markNoMatch() }
				for _, r := range results { if err := outputResult(printer, r, splitAST, outputFormat, tracker); err != nil { return err } }
				if cfg.FrontMatter == "process" {
					_, _ = io.WriteString(outWriter, "---\n"+rest)
				}
				continue
			}
			allDocs = append(allDocs, docs...)
		}
		if len(allDocs)>0 {
			for _, d := range allDocs { if cfg.Pretty { clearStyles(d.Node) } }
			ctx := &EvalContext{Candidates: allDocs, Vars: map[string][]*Candidate{}}
			results, err := evalAST(exprAST, ctx)
			if err != nil { return err }
			if len(results)==0 { tracker.markNoMatch() }
			for _, r := range results {
				if err := outputResult(printer, r, splitAST, outputFormat, tracker); err != nil { return err }
			}
		} else if !isFront {
			// no docs? treat as one null?
			ctx := &EvalContext{Candidates: []*Candidate{makeDocCandidate(nullNode(),0,0,"-",false,0)}, Vars: map[string][]*Candidate{}}
			results, err := evalAST(exprAST, ctx)
			if err != nil { return err }
			for _, r := range results { if err := outputResult(printer, r, splitAST, outputFormat, tracker); err != nil { return err } }
		}
	} else {
		// eval sequence
		if len(files)==0 { files = []string{"-"} }
		for fileIdx, fname := range files {
			docs, rest, isFM, err := loadInput(fname, fileIdx, specifiedInput, &globalPrintID, isFront && fileIdx==0)
			if err != nil { return wrapFileError(fname, err) }
			if isFM {
				// if no front matter detected, loadInput returns raw flag via special doc? It handles printing raw inside? We use isFMProcessed marker: if docs is nil and rest is raw output
				if docs == nil {
					// raw passthrough
					_, _ = io.WriteString(outWriter, rest)
					continue
				}
				if err := evaluateDocs(docs); err != nil { return err }
				if cfg.FrontMatter == "process" {
					_, _ = io.WriteString(outWriter, "---\n"+rest)
				}
				continue
			}
			if err := evaluateDocs(docs); err != nil { return err }
		}
	}
	// inplace write
	if cfg.Inplace {
		target := files[0]
		if err := os.WriteFile(target, inplaceBuf.Bytes(), 0644); err != nil { return err }
	}
	// exit status
	if cfg.ExitStatus && !tracker.success() {
		fmt.Fprintf(os.Stderr, "Error: no matches found\n")
		return errExitStatusSpecial()
	}
	return nil
}

func errExitStatusSpecial() error { return errExitStatus }

type statusTracker struct {
	hasResult bool
	lastSuccess bool
	hadNoMatch bool
}
func (t *statusTracker) markResult(c *Candidate) {
	t.hasResult = true
	n := effectiveNode(c.Node)
	if n == nil { t.lastSuccess = false; return }
	if n.Tag == "!!null" { t.lastSuccess = false; return }
	if n.Tag == "!!bool" && n.Value != "true" { t.lastSuccess = false; return }
	t.lastSuccess = true
}
func (t *statusTracker) markNoMatch() { t.hadNoMatch = true }
func (t *statusTracker) success() bool {
	if !t.hasResult { return false }
	// If last result was success, even if earlier no-match? Original logic probably uses last result. If there were docs with no results but another succeeded, lastSuccess determines.
	// If we had no match at end (last eval empty), tracker won't have updated lastSuccess and hasResult may be true from earlier but should be failure. We need to know.
	if t.hadNoMatch && !t.lastSuccess {
		// ambiguous
	}
	// Use lastSuccess as primary, but if last evaluations were empty, lastSuccess should be false: markNoMatch sets it
	return t.lastSuccess
}

// override markNoMatch to set lastSuccess false
func init() {
	// placeholder to keep compiler happy; actual markNoMatch defined above sets hadNoMatch but we also adjust in success logic via wrapper below.
}

func resolveExprFiles(args []string) (string, []string, error) {
	cfg := globalOpts
	if cfg.FromFile != "" {
		b, err := os.ReadFile(cfg.FromFile)
		if err != nil { return "", nil, err }
		expr := string(b)
		// Files are args as-is
		return expr, args, nil
	}
	if cfg.Expression != "" {
		// If --expression was explicitly set (even to empty?), cobra can't distinguish, but non-empty here
		return cfg.Expression, args, nil
	}
	// Also if Expression flag was set to empty via --expression=, treat as "."? ignore
	if len(args)==0 {
		return ".", nil, nil
	}
	if len(args)==1 {
		if args[0]=="-" || isRegularFile(args[0]) {
			return ".", args, nil
		}
		return args[0], nil, nil
	}
	// >=2
	if args[0]=="-" || isRegularFile(args[0]) {
		return ".", args, nil
	}
	return args[0], args[1:], nil
}

func loadInput(fname string, fileIdx int, specifiedInput string, globalPrintID *int, handleFront bool) (docs []*Candidate, rest string, isFM bool, err error) {
	var data []byte
	if fname == "-" {
		data, err = io.ReadAll(os.Stdin)
		if err != nil { return nil, "", false, err }
	} else {
		data, err = os.ReadFile(fname)
		if err != nil { return nil, "", false, err }
	}
	// front matter
	if handleFront && globalOpts.FrontMatter != "" {
		fmContent, restContent, has := splitFrontMatter(data)
		if !has {
			return nil, string(data), true, nil
		}
		docs, err := decodeYAMLBytes(fmContent, fname)
		if err != nil { return nil, "", false, err }
		for _, d := range docs { d.FileIdx = fileIdx; d.Filename = fname; d.DocIndex = d.DocIndex; d.PrintID = (*globalPrintID); *globalPrintID++; d.LeadingSep = true }
		return docs, restContent, true, nil
	}
	format := specifiedInput
	if format == "auto" {
		if fname == "-" { format = "yaml" } else { format = formatFromFilename(fname) }
	}
	docs, err = decodeBytesByFormat(data, format, fname)
	if err != nil {
		return nil, "", false, fmt.Errorf("bad file '%s': %v", fname, err)
	}
	for _, d := range docs {
		d.FileIdx = fileIdx
