	cfg := globalOpts
	if cfg.FromFile != "" {
		b, err := os.ReadFile(cfg.FromFile)
		if err != nil { return "", nil, err }
		expr := string(b)
		// Files are args as-is
		return expr, args, nil
	}
	if cfg.Expression != "" {
		// If --expression was explicitly set (even to empty?), cobra can't distinguish, but non-empty here
		return cfg.Expression, args, nil
	}
	// Also if Expression flag was set to empty via --expression=, treat as "."? ignore
	if len(args)==0 {
		return ".", nil, nil
	}
	if len(args)==1 {
		if args[0]=="-" || isRegularFile(args[0]) {
			return ".", args, nil
		}
		return args[0], nil, nil
	}
	// >=2
	if args[0]=="-" || isRegularFile(args[0]) {
		return ".", args, nil
	}
	return args[0], args[1:], nil
