package main

import (
	"strings"
)

func colorsEnabled() bool {
	if globalOpts == nil { return false }
	if globalOpts.NoColors { return false }
	if globalOpts.Colors { return true }
	return globalOpts.ColorsDefault
}

const (
	colKey = "36"
	colStr = "32"
	colNum = "95"
)
func wrapCol(code, s string) string { return "\x1b["+code+"m"+s+"\x1b[0m" }
func emptyCol(code, inner string) string { return "\x1b["+code+"m"+inner+"\x1b[0m" }

func scalarColorOf(trim string) string {
	if trim=="" { return "" }
	if trim=="null" || trim=="~" { return "" }
	if trim=="true" || trim=="false" { return colNum }
	// quoted strings
	if strings.HasPrefix(trim, "\"") || strings.HasPrefix(trim, "'") { return colStr }
	if isNumberToken(trim) { return colNum }
	return colStr
}

// YAML colouring approximation of yq's chunk-based colour encoder.
func applyColorYAML(s string) string {
	if !colorsEnabled() { return s }
	lines := strings.Split(s, "\n")
	var out []string
	prevScalarCol := ""
	prevHadScalar := false
	inBlock := false
	blockCol := colStr
	// For determining block map vs seq after a key with empty value, look ahead
	for idx, line := range lines {
		// trailing empty line
		if line=="" && idx==len(lines)-1 {
			if inBlock {
				out = append(out, emptyCol(blockCol, ""))
			} else {
				out = append(out, "")
			}
			continue
		}
		if line=="---" {
			out = append(out, line)
			prevHadScalar=false; inBlock=false
			continue
		}
		trimLeft := strings.TrimLeft(line, " ")
		indent := line[:len(line)-len(trimLeft)]
		// block scalar content
		if inBlock {
			if trimLeft=="" {
				out = append(out, line)
				continue
			}
			// content lines are coloured whole
			out = append(out, wrapCol(blockCol, line))
			prevScalarCol = blockCol; prevHadScalar = true
			// stay in block until a line with indent <=? We don't know block indent; heuristic: if following processing sees a key at indent 0, our inBlock will be reset below by checking indent? Keep inBlock while line starts with spaces and is not a map key at lower indent - ambiguous.
			// If next line is a key at indent 0, next iteration will still treat as block unless we clear. Clear if trim contains ": " at indent 0? Content could too.
			// Use: if line is last content (next line is key with indent <= block key indent) caller logic will handle in next iteration by detecting a map key whose indent is small.
			// We keep flag and next iteration may override if it looks like a key and indent is 0 and block scalar originated at indent 0.
			// Simplification: leave flag, next iteration checks below before block handling if indent==""
			if indent=="" {
				inBlock=false
			} else {
				continue
			}
		}
		// If in block but this line looks like a top-level key (indent "") and previous block started at 0, fall through.
		// Determine line forms
		isSeq := strings.HasPrefix(trimLeft, "- ") || trimLeft=="-"
		rest := trimLeft
		prefixPlain := indent // for seq, dash added later
		if isSeq {
			rest = strings.TrimPrefix(trimLeft, "-")
			// rest starts with space if "- "
			prefixPlain = indent + "-"
		}
		// Check map key in rest (taking into account leading space for seq)
		keyPart, afterColon, hasKey := splitYAMLKey(rest)
		if hasKey {
			// hasKey: keyPart is text before colon (may include leading space for seq case), afterColon is remainder after colon (starts with space or empty)
			// Build coloured key segment
			// Determine if we need sibling prefix
			usePrefix := prevHadScalar && prevScalarCol != ""
			var coloured string
			if usePrefix {
				// indent spaces go into empty segment
				coloured = emptyCol(prevScalarCol, indent)
				if isSeq {
					coloured += "-"
					// keyPart may include leading space (from "- a") - that space belongs to key colour
					coloured += wrapCol(colKey, keyPart)
				} else {
					coloured += wrapCol(colKey, strings.TrimLeft(keyPart, " "))
					// Note keyPart for non-seq is just key without indent; indent already in empty
				}
			} else {
				if isSeq {
					coloured = prefixPlain + wrapCol(colKey, keyPart)
				} else {
					coloured = wrapCol(colKey, indent+keyPart)
				}
			}
			coloured += ":"
			// Value handling
			valTrim := strings.TrimSpace(afterColon)
			if valTrim == "" {
				// empty value: block map or seq or null empty
				// Look ahead to next non-empty line
				nextIsSeq := false
				nextIsMap := false
				for j:=idx+1;j<len(lines);j++ {
					if strings.TrimSpace(lines[j])=="" { continue }
					nt := strings.TrimLeft(lines[j], " ")
					if strings.HasPrefix(nt, "- ") || nt=="-" { nextIsSeq = true } else { nextIsMap = true }
					break
				}
				if nextIsMap {
					coloured += emptyCol(colKey, "")
				}
				_ = nextIsSeq
				out = append(out, coloured)
				prevHadScalar = false; prevScalarCol = ""
				inBlock = false
				continue
			}
			if valTrim=="|" || valTrim==">" || strings.HasPrefix(valTrim, "|-") || strings.HasPrefix(valTrim, ">-") || strings.HasPrefix(valTrim, "|+") || strings.HasPrefix(valTrim, ">+") {
				coloured += afterColon
				out = append(out, coloured)
				inBlock = true; blockCol = colStr; prevHadScalar=false
				continue
			}
			if strings.HasPrefix(valTrim, "[") || strings.HasPrefix(valTrim, "{") {
				coloured += colorFlow(afterColon)
				// trailing empty cyan after flow collection as map value
				coloured += emptyCol(colKey, "")
				out = append(out, coloured)
				prevHadScalar = false; prevScalarCol = ""
				continue
			}
			// scalar value
			ccol := scalarColorOf(valTrim)
			if ccol == "" {
				coloured += afterColon
				prevHadScalar = false; prevScalarCol = ""
			} else {
				coloured += wrapCol(ccol, afterColon)
				prevHadScalar = true; prevScalarCol = ccol
			}
			out = append(out, coloured)
			inBlock = false
			continue
		}
		// No key: seq scalar or scalar line
		if isSeq {
			valTrim := strings.TrimSpace(rest)
			if valTrim=="|" || valTrim==">" {
				out = append(out, line); inBlock=true; blockCol=colStr; prevHadScalar=false; continue
			}
			if strings.HasPrefix(valTrim, "[") || strings.HasPrefix(valTrim, "{") {
				var coloured string
				if prevHadScalar && prevScalarCol!="" {
					coloured = emptyCol(prevScalarCol, indent) + "-" + colorFlow(rest)
				} else {
					coloured = prefixPlain + colorFlow(rest)
				}
				out = append(out, coloured); prevHadScalar=false; continue
			}
			ccol := scalarColorOf(valTrim)
			var coloured string
			if prevHadScalar && prevScalarCol!="" {
				coloured = emptyCol(prevScalarCol, indent) + "-"
				if ccol=="" { coloured += rest } else { coloured += wrapCol(ccol, rest) }
			} else {
				coloured = prefixPlain
				if ccol=="" { coloured += rest } else { coloured += wrapCol(ccol, rest) }
			}
			out = append(out, coloured)
			if ccol!="" { prevHadScalar=true; prevScalarCol=ccol } else { prevHadScalar=false }
			continue
		}
		// Plain line (top scalar etc) - if previous in block handled above; colour as string if not empty
		if trimLeft != "" {
			// Could be a scalar line (wrapped plain string). Colour rest as string with indent outside? Original block scalar includes indent, plain wrapped maybe similar. We'll colour whole line if it appears to be continuation.
			// For a lone scalar document (unwrap false) encoder gives plain/quoted line; colourise token.
			ccol := scalarColorOf(trimLeft)
			if ccol != "" {
				out = append(out, wrapCol(ccol, line))
				prevHadScalar=true; prevScalarCol=ccol
				continue
			}
		}
		out = append(out, line)
	}
	return strings.Join(out, "\n")
}

func splitYAMLKey(rest string) (key string, after string, ok bool) {
	// rest may start with space (seq "- a")
	// Find colon that is followed by space or EOL, not inside quotes/flow
	inS := false; inD := false; depth := 0
	for i:=0;i<len(rest);i++ {
		c:=rest[i]
		if inD { if c=='\\' {i++; continue}; if c=='"' {inD=false}; continue }
		if inS { if c=='\'' {inS=false}; continue }
		if c=='"' {inD=true; continue}
		if c=='\'' {inS=true; continue}
		if c=='['||c=='{' {depth++}
		if c==']'||c=='}' {depth--}
		if c==':' && depth==0 {
			if i+1>=len(rest) || rest[i+1]==' ' {
				return rest[:i], rest[i+1:], true
			}
		}
	}
	return "", "", false
}

func colorFlow(s string) string {
	// Colour a flow chunk (starting possibly with space)
	var out strings.Builder
	i:=0
	for i < len(s) {
		c:=s[i]
		if c==' ' {
			// Look ahead to next token
			j:=i; for j<len(s) && s[j]==' ' {j++}
			if j<len(s) && (s[j]=='"' || s[j]=='\'' || isDigitByte(s[j]) || isIdentStartByte(s[j]) || s[j]=='-' ) {
				// parse token from j
				tok, next := parseFlowToken(s, j)
				code := flowTokenColor(s, tok, next)
				if code != "" {
					out.WriteString(wrapCol(code, s[i:next])); i=next; continue
				}
			}
			out.WriteByte(c); i++; continue
		}
		if c=='"' || c=='\'' || isDigitByte(c) || isIdentStartByte(c) || c=='-' {
			tok, next := parseFlowToken(s, i)
			code := flowTokenColor(s, tok, next)
			if code != "" {
				out.WriteString(wrapCol(code, tok)); i=next; continue
			}
			out.WriteString(tok); i=next; continue
		}
		out.WriteByte(c); i++
	}
	return out.String()
}

func parseFlowToken(s string, start int) (string,int) {
	if start>=len(s){return "",start}
	c:=s[start]
	if c=='"' || c=='\'' {
		q:=c; j:=start+1; for j<len(s){ if s[j]=='\\' && q=='"' {j+=2; continue}; if s[j]==q{ j++; break}; j++ }
		return s[start:j], j
	}
	j:=start
	// include minus sign
	for j<len(s) && !strings.ContainsRune(",]}: \n", rune(s[j])) { j++ }
	return s[start:j], j
}
func flowTokenColor(s string, tok string, next int) string {
	// if token is key (followed by colon)
	k:=next; for k<len(s) && s[k]==' ' {k++}
	if k<len(s) && s[k]==':' { return colKey }
	if tok=="" {return ""}
	if tok[0]=='"' || tok[0]=='\'' { return colStr }
	if isNumberToken(tok) { return colNum }
	if tok=="true"||tok=="false" { return colNum }
	if tok=="null"||tok=="~" { return "" }
	// plain string
	return colStr
}
func isDigitByte(b byte) bool { return b>='0'&&b<='9' }
func isIdentStartByte2(b byte) bool { return b=='_'||(b>='a'&&b<='z')||(b>='A'&&b<='Z') }
func isNumberToken(s string) bool {
	if s==""{return false}
	// allow leading -
	t:=s; if strings.HasPrefix(t,"-"){t=t[1:]}
	if t==""{return false}
	for _,r:=range t{ if !(r>='0'&&r<='9'||r=='.'||r=='e'||r=='E'||r=='+'||r=='-'||r=='x'||r=='X'||r=='o'||r=='b'||r=='_'){return false} }
	return true
}

func applyColorJSON(s string, c interface{}) string {
	if !colorsEnabled() { return s }
	if !strings.Contains(s, "\n") {
		return colorJSONCompact(s)
	}
	lines := strings.Split(s, "\n")
	var out []string
	lastScalarCol := ""
	lastWasScalar := false
	for idx, line := range lines {
		trim := strings.TrimLeft(line, " ")
		indent := line[:len(line)-len(trim)]
		// closing line
		if trim=="}" || trim=="]" || trim=="}," || trim=="]," {
			var coloured string
			if lastWasScalar && lastScalarCol==colNum {
				coloured = emptyCol(colNum, indent) + trim
			} else {
				coloured = line
			}
			if strings.HasSuffix(trim, ",") {
				coloured += emptyCol(colKey, "")
			}
			out = append(out, coloured)
			lastWasScalar = false
			continue
		}
		// opening standalone { or [
		if trim=="{" || trim=="[" {
			code := colKey
			if trim=="[" {
				code = jsonFirstElemColor(lines, idx)
				if code=="" {code=colKey}
			}
			out = append(out, line+emptyCol(code, ""))
			lastWasScalar=false
			continue
		}
		// key line
		if strings.HasPrefix(trim, "\"") {
			// find key end
			end := -1
			for i:=1;i<len(trim);i++ { if trim[i]=='\\' {i++; continue}; if trim[i]=='"' {end=i; break} }
			if end>0 && end+1<len(trim) && trim[end+1]==':' {
				keyTok := trim[:end+1]
				after := trim[end+2:] // after colon, may start space
				coloured := wrapCol(colKey, indent+keyTok) + ":"
				// analyse after trimmed
				afterTrim := strings.TrimSpace(after)
				if afterTrim=="{" {
					coloured += after + emptyCol(colKey, "")
					out = append(out, coloured); lastWasScalar=false; continue
				}
				if afterTrim=="[" {
					code := jsonFirstElemColor(lines, idx); if code==""{code=colKey}
					coloured += after + emptyCol(code, "")
					out = append(out, coloured); lastWasScalar=false; continue
				}
				// scalar with optional trailing comma
				hasComma := strings.HasSuffix(afterTrim, ",")
				core := after
				comma := ""
				if hasComma {
					// remove trailing comma from colouring: after ends with ,
					core = strings.TrimSuffix(after, ",")
					// core may still end? after is like " 1," -> remove last ,
					comma = ","
				}
				coreTrim := strings.TrimSpace(core)
				ccol := jsonScalarColor(coreTrim)
				if ccol=="" {
					coloured += core + comma
					lastWasScalar=false; lastScalarCol=""
				} else {
					coloured += wrapCol(ccol, core) + comma
					lastWasScalar=true; lastScalarCol=ccol
				}
				if hasComma {
					coloured += emptyCol(colKey, "")
					lastWasScalar=false
				}
				out = append(out, coloured)
				continue
			}
			// string element line (array)
			hasComma := strings.HasSuffix(trim, ",")
			core:=trim; comma:=""; if hasComma{core=strings.TrimSuffix(trim,","); comma=","}
			coloured := wrapCol(colStr, indent+core) + comma
			if hasComma {
				coloured += emptyCol(jsonNextElemColor(lines, idx), "")
				lastWasScalar=false
			} else { lastWasScalar=true; lastScalarCol=colStr }
			out = append(out, coloured)
			continue
		}
		// scalar element line (number/bool/null or nested opening ending)
		if strings.HasSuffix(trim, "{") || strings.HasSuffix(trim, "[") {
			// shouldn't happen separate
			out = append(out, line); continue
		}
		{
			hasComma := strings.HasSuffix(trim, ",")
			core:=trim; comma:=""; if hasComma{core=strings.TrimSuffix(trim,","); comma=","}
			ccol := jsonScalarColor(core)
			var coloured string
			if ccol=="" { coloured = line } else { coloured = wrapCol(ccol, indent+core) + comma }
			if hasComma {
				code:=jsonNextElemColor(lines, idx); if code!="" { coloured += emptyCol(code, "") }
				lastWasScalar=false
			} else {
				if ccol!="" {lastWasScalar=true; lastScalarCol=ccol} else {lastWasScalar=false}
			}
			out = append(out, coloured)
			continue
		}
	}
	return strings.Join(out, "\n")
}

func jsonScalarColor(trim string) string {
	if trim==""{return ""}
	if trim=="null"{return ""}
	if trim=="true"||trim=="false"{return colNum}
	if strings.HasPrefix(trim,"\""){return colStr}
	if isNumberToken(trim){return colNum}
	return colStr
}
func jsonFirstElemColor(lines []string, idx int) string {
	for j:=idx+1;j<len(lines);j++ {
		t:=strings.TrimSpace(lines[j])
		if t==""{continue}
		if strings.HasPrefix(t,"\""){
			// could be key or string elem: if next line... Determine if it's a key by looking for '":' pattern - if the token ends with ":, it's key.
			// Simple: check if after closing quote there's colon
			// Use scalar color if string elem else cyan
			// Find closing quote
			for i:=1;i<len(t);i++{if t[i]=='\\'{i++;continue}; if t[i]=='"'{ if i+1<len(t)&&t[i+1]==':'{return colKey}; break}}
			return colStr
		}
		return jsonScalarColor(strings.TrimSuffix(t,","))
	}
	return colKey
}
func jsonNextElemColor(lines []string, idx int) string {
	// colour of next element/key: if next line is key line, cyan; else scalar colour
	if idx+1>=len(lines){return colKey}
	t:=strings.TrimLeft(lines[idx+1]," ")
	if strings.HasPrefix(t,"\""){
		for i:=1;i<len(t);i++{if t[i]=='\\'{i++;continue}; if t[i]=='"'{ if i+1<len(t)&&t[i+1]==':'{return colKey}; return colStr}}
	}
	return jsonScalarColor(strings.TrimSpace(strings.TrimSuffix(t,",")))
}

func colorJSONCompact(s string) string {
	var out strings.Builder
	i:=0
	for i<len(s){
		c:=s[i]
		if c=='"' {
			tok,next:=parseFlowToken(s,i)
			// key if colon follows
			k:=next; for k<len(s)&&s[k]==' '{k++}
			if k<len(s)&&s[k]==':'{ out.WriteString(wrapCol(colKey,tok)) } else { out.WriteString(wrapCol(colStr,tok)) }
			i=next; continue
		}
		if isDigitByte(c)||c=='-'{
			tok,next:=parseFlowToken(s,i)
			if isNumberToken(tok){out.WriteString(wrapCol(colNum,tok))}else{out.WriteString(tok)}
			i=next; continue
		}
		// bool/null words
		if isIdentStartByte2(c){
			tok,next:=parseFlowToken(s,i)
			if tok=="true"||tok=="false"{out.WriteString(wrapCol(colNum,tok))}else{out.WriteString(tok)}
			i=next; continue
		}
		out.WriteByte(c); i++
	}
	return out.String()
}
