func isDigitByte(b byte) bool { return b>='0'&&b<='9' }
func isIdentStartByte2(b byte) bool { return b=='_'||(b>='a'&&b<='z')||(b>='A'&&b<='Z') }
func isNumberToken(s string) bool {
	if s==""{return false}
	// allow leading -
	t:=s; if strings.HasPrefix(t,"-"){t=t[1:]}
	if t==""{return false}
	for _,r:=range t{ if !(r>='0'&&r<='9'||r=='.'||r=='e'||r=='E'||r=='+'||r=='-'||r=='x'||r=='X'||r=='o'||r=='b'||r=='_'){return false} }
	return true
}

func applyColorJSON(s string, c interface{}) string {
	if !colorsEnabled() { return s }
	if !strings.Contains(s, "\n") {
		return colorJSONCompact(s)
	}
	lines := strings.Split(s, "\n")
	var out []string
	lastScalarCol := ""
	lastWasScalar := false
	for idx, line := range lines {
		trim := strings.TrimLeft(line, " ")
		indent := line[:len(line)-len(trim)]
		// closing line
		if trim=="}" || trim=="]" || trim=="}," || trim=="]," {
			var coloured string
			if lastWasScalar && lastScalarCol==colNum {
				coloured = emptyCol(colNum, indent) + trim
			} else {
				coloured = line
			}
			if strings.HasSuffix(trim, ",") {
				coloured += emptyCol(colKey, "")
			}
			out = append(out, coloured)
			lastWasScalar = false
			continue
		}
		// opening standalone { or [
		if trim=="{" || trim=="[" {
			code := colKey
			if trim=="[" {
				code = jsonFirstElemColor(lines, idx)
				if code=="" {code=colKey}
			}
			out = append(out, line+emptyCol(code, ""))
			lastWasScalar=false
			continue
		}
		// key line
		if strings.HasPrefix(trim, "\"") {
			// find key end
			end := -1
			for i:=1;i<len(trim);i++ { if trim[i]=='\\' {i++; continue}; if trim[i]=='"' {end=i; break} }
			if end>0 && end+1<len(trim) && trim[end+1]==':' {
				keyTok := trim[:end+1]
				after := trim[end+2:] // after colon, may start space
				coloured := wrapCol(colKey, indent+keyTok) + ":"
				// analyse after trimmed
				afterTrim := strings.TrimSpace(after)
				if afterTrim=="{" {
					coloured += after + emptyCol(colKey, "")
					out = append(out, coloured); lastWasScalar=false; continue
				}
				if afterTrim=="[" {
					code := jsonFirstElemColor(lines, idx); if code==""{code=colKey}
					coloured += after + emptyCol(code, "")
					out = append(out, coloured); lastWasScalar=false; continue
				}
				// scalar with optional trailing comma
				hasComma := strings.HasSuffix(afterTrim, ",")
				core := after
				comma := ""
				if hasComma {
					// remove trailing comma from colouring: after ends with ,
					core = strings.TrimSuffix(after, ",")
					// core may still end? after is like " 1," -> remove last ,
					comma = ","
				}
				coreTrim := strings.TrimSpace(core)
				ccol := jsonScalarColor(coreTrim)
				if ccol=="" {
					coloured += core + comma
					lastWasScalar=false; lastScalarCol=""
				} else {
					coloured += wrapCol(ccol, core) + comma
					lastWasScalar=true; lastScalarCol=ccol
				}
				if hasComma {
					coloured += emptyCol(colKey, "")
					lastWasScalar=false
				}
				out = append(out, coloured)
				continue
			}
			// string element line (array)
			hasComma := strings.HasSuffix(trim, ",")
			core:=trim; comma:=""; if hasComma{core=strings.TrimSuffix(trim,","); comma=","}
			coloured := wrapCol(colStr, indent+core) + comma
			if hasComma {
				coloured += emptyCol(jsonNextElemColor(lines, idx), "")
				lastWasScalar=false
			} else { lastWasScalar=true; lastScalarCol=colStr }
			out = append(out, coloured)
			continue
		}
		// scalar element line (number/bool/null or nested opening ending)
		if strings.HasSuffix(trim, "{") || strings.HasSuffix(trim, "[") {
			// shouldn't happen separate
			out = append(out, line); continue
		}
		{
			hasComma := strings.HasSuffix(trim, ",")
			core:=trim; comma:=""; if hasComma{core=strings.TrimSuffix(trim,","); comma=","}
			ccol := jsonScalarColor(core)
			var coloured string
			if ccol=="" { coloured = line } else { coloured = wrapCol(ccol, indent+core) + comma }
			if hasComma {
				code:=jsonNextElemColor(lines, idx); if code!="" { coloured += emptyCol(code, "") }
				lastWasScalar=false
			} else {
				if ccol!="" {lastWasScalar=true; lastScalarCol=ccol} else {lastWasScalar=false}
			}
			out = append(out, coloured)
			continue
		}
	}
	return strings.Join(out, "\n")
}

func jsonScalarColor(trim string) string {
	if trim==""{return ""}
	if trim=="null"{return ""}
	if trim=="true"||trim=="false"{return colNum}
	if strings.HasPrefix(trim,"\""){return colStr}
	if isNumberToken(trim){return colNum}
	return colStr
}
func jsonFirstElemColor(lines []string, idx int) string {
	for j:=idx+1;j<len(lines);j++ {
		t:=strings.TrimSpace(lines[j])
		if t==""{continue}
		if strings.HasPrefix(t,"\""){
			// could be key or string elem: if next line... Determine if it's a key by looking for '":' pattern - if the token ends with ":, it's key.
			// Simple: check if after closing quote there's colon
			// Use scalar color if string elem else cyan
			// Find closing quote
			for i:=1;i<len(t);i++{if t[i]=='\\'{i++;continue}; if t[i]=='"'{ if i+1<len(t)&&t[i+1]==':'{return colKey}; break}}
			return colStr
		}
		return jsonScalarColor(strings.TrimSuffix(t,","))
	}
	return colKey
}
func jsonNextElemColor(lines []string, idx int) string {
	// colour of next element/key: if next line is key line, cyan; else scalar colour
	if idx+1>=len(lines){return colKey}
	t:=strings.TrimLeft(lines[idx+1]," ")
	if strings.HasPrefix(t,"\""){
		for i:=1;i<len(t);i++{if t[i]=='\\'{i++;continue}; if t[i]=='"'{ if i+1<len(t)&&t[i+1]==':'{return colKey}; return colStr}}
	}
	return jsonScalarColor(strings.TrimSpace(strings.TrimSuffix(t,",")))
}

func colorJSONCompact(s string) string {
	var out strings.Builder
	i:=0
	for i<len(s){
		c:=s[i]
		if c=='"' {
			tok,next:=parseFlowToken(s,i)
			// key if colon follows
			k:=next; for k<len(s)&&s[k]==' '{k++}
			if k<len(s)&&s[k]==':'{ out.WriteString(wrapCol(colKey,tok)) } else { out.WriteString(wrapCol(colStr,tok)) }
			i=next; continue
		}
		if isDigitByte(c)||c=='-'{
			tok,next:=parseFlowToken(s,i)
			if isNumberToken(tok){out.WriteString(wrapCol(colNum,tok))}else{out.WriteString(tok)}
			i=next; continue
		}
		// bool/null words
		if isIdentStartByte2(c){
			tok,next:=parseFlowToken(s,i)
			if tok=="true"||tok=="false"{out.WriteString(wrapCol(colNum,tok))}else{out.WriteString(tok)}
			i=next; continue
		}
		out.WriteByte(c); i++
	}
	return out.String()
}
