package main

import (
	"fmt"
	"regexp"
	"strconv"
	"strings"
)

var reYamlLineMsg = regexp.MustCompile(`^yaml: line (\d+): (.*)$`)
var reYamlLineColMsg = regexp.MustCompile(`^yaml: line (\d+), column (\d+): (.*)$`)

func transformYAMLError(err error, data []byte) error {
	if err == nil { return nil }
	msg := err.Error()
	if !strings.HasPrefix(msg, "yaml: ") {
		return err
	}
	// unknown anchor
	if strings.Contains(msg, "unknown anchor") {
		re := regexp.MustCompile(`unknown anchor '([^']+)'`)
		m := re.FindStringSubmatch(msg)
		if m != nil {
			name := m[1]
			lines := strings.Split(string(data), "\n")
			for i, line := range lines {
				idx := strings.Index(line, "*"+name)
				if idx >= 0 {
					return fmt.Errorf("yaml: line %d, column %d: unknown anchor '%s' referenced", i+1, idx+1, name)
				}
			}
		}
		return err
	}
	if m := reYamlLineColMsg.FindStringSubmatch(msg); m != nil {
		return err
	}
	m := reYamlLineMsg.FindStringSubmatch(msg)
	if m == nil {
		return err
	}
	lineNum, _ := strconv.Atoi(m[1])
	rest := m[2]
	switch {
	case strings.HasPrefix(rest, "did not find expected ',' or ']'"):
		return fmt.Errorf("yaml: while parsing a flow sequence at <unknown position>: line %d: %s", lineNum, rest)
	case strings.HasPrefix(rest, "did not find expected ',' or '}'"):
		return fmt.Errorf("yaml: while parsing a flow mapping at <unknown position>: line %d: %s", lineNum, rest)
	case strings.HasPrefix(rest, "did not find expected node content"):
		return fmt.Errorf("yaml: while parsing a flow node at <unknown position>: %s", rest)
	case strings.HasPrefix(rest, "did not find expected key"):
		return fmt.Errorf("yaml: while parsing a block mapping at <unknown position>: %s", rest)
	case strings.HasPrefix(rest, "found unexpected end of stream"):
		// find unclosed quote
		lines := strings.Split(string(data), "\n")
		for i, line := range lines {
			// Count unescaped double quotes; if odd, opening is last quote
			if strings.Count(line, "\"")%2==1 {
				idx := strings.LastIndex(line, "\"")
				return fmt.Errorf("yaml: while scanning a quoted scalar at line %d, column %d: line %d: %s", i+1, idx+1, lineNum, rest)
			}
			if strings.Count(line, "'")%2==1 {
				idx := strings.LastIndex(line, "'")
				return fmt.Errorf("yaml: while scanning a quoted scalar at line %d, column %d: line %d: %s", i+1, idx+1, lineNum, rest)
			}
		}
		return err
	case strings.Contains(rest, "found a tab character"):
		// plain scalar context from previous line
		lines := strings.Split(string(data), "\n")
		prevIdx := lineNum-2
		if prevIdx >=0 && prevIdx < len(lines) {
			prev := lines[prevIdx]
			col := 1
			if idx := strings.Index(prev, ": "); idx>=0 { col = idx+3 } else {
				col = len(prev)-len(strings.TrimLeft(prev," "))+1
				if strings.HasPrefix(strings.TrimLeft(prev," "), "- ") { col += 2 }
			}
			return fmt.Errorf("yaml: while scanning a plain scalar at line %d, column %d: line %d: %s", prevIdx+1, col, lineNum, rest)
		}
		return err
	}
	return err
}
