		out = compactSeqIndent(out, indent)
	}
	return out, nil
}

func compactSeqIndent(s string, indentWidth int) string {
	if indentWidth < 2 { indentWidth = 2 }
	type block struct{ seqIndent int; shift int }
	var stack []block
	lines := strings.Split(s, "\\n")
	var out []string
	prevIsKey := false
	prevIndent := 0
	for _, line := range lines {
		if strings.TrimSpace(line)=="" { out = append(out, line); continue }
		origIndent := len(line) - len(strings.TrimLeft(line, " "))
		for len(stack)>0 && origIndent < stack[len(stack)-1].seqIndent { stack = stack[:len(stack)-1] }
		reduction := 0
		if len(stack)>0 { reduction = stack[len(stack)-1].shift }
		isSeq := false
		trim := strings.TrimLeft(line, " ")
		if trim=="-" || strings.HasPrefix(trim, "- ") { isSeq = true }
		if isSeq {
			isSibling := len(stack)>0 && stack[len(stack)-1].seqIndent == origIndent
			if !isSibling && prevIsKey && origIndent == prevIndent + indentWidth {
				shift := reduction + indentWidth
				stack = append(stack, block{seqIndent: origIndent, shift: shift})
				reduction = shift
			}
		}
		newIndent := origIndent - reduction
		if newIndent < 0 { newIndent = 0 }
		out = append(out, strings.Repeat(" ", newIndent) + trim)
		// update prev key info
		tt := strings.TrimRight(trim, " ")
		// A mapping key line ends with ':' (standalone). For seq item '- key:' also.
		content := tt
		if strings.HasPrefix(content, "- ") { content = content[2:] }
		if strings.HasSuffix(content, ":") && strings.Contains(content, ":") {
			prevIsKey = true; prevIndent = origIndent
			// if key is inline in a seq item, its effective indent is origIndent+2
			if strings.HasPrefix(trim, "- ") { prevIndent = origIndent + 2 }
		} else {
			// seq item with inline key also handled above; otherwise not key
			if strings.HasSuffix(tt, ":") && !isSeq {
				prevIsKey = true; prevIndent = origIndent
			} else {
				prevIsKey = false; prevIndent = origIndent
			}
		}
	}
	return strings.Join(out, "\\n")
}
