import pathlib
p=pathlib.Path("formats_out.go"); t=p.read_text()
start=t.find("// TOML encoder:")
end=t.find("func tomlTableName", start)
new='''// TOML encoder
type tomlWriter struct { sb strings.Builder; first bool }
func (w *tomlWriter) header(name string, array bool) {
	if !w.first { w.sb.WriteString("\\n") }
	if array { w.sb.WriteString("[["+tomlTableName(name)+"]]\\n") } else { w.sb.WriteString("["+tomlTableName(name)+"]\\n") }
	w.first = false
}
func (w *tomlWriter) line(s string) { w.sb.WriteString(s+"\\n"); w.first=false }
func isTomlSeqOfMaps(n *yaml.Node) bool {
	if n==nil || n.Kind!=yaml.SequenceNode || len(n.Content)==0 { return false }
	for _,el:=range n.Content { if effectiveNode(el).Kind!=yaml.MappingNode { return false } }
	return true
}
func isTomlTableValue(n *yaml.Node) bool {
	en:=effectiveNode(n)
	if en==nil { return false }
	if en.Kind==yaml.MappingNode && en.Style&yaml.FlowStyle==0 { return true }
	return isTomlSeqOfMaps(en)
}
func (w *tomlWriter) processTable(path string, m *yaml.Node, forceHeader bool) {
	// direct entries first
	var direct [][2]*yaml.Node // key node, value effective
	var tables [][2]*yaml.Node
	for i:=0;i+1<len(m.Content);i+=2 {
		k:=m.Content[i]; v:=effectiveNode(m.Content[i+1])
		if isTomlTableValue(v) { tables=append(tables, [2]*yaml.Node{k, v}) } else { direct=append(direct, [2]*yaml.Node{k, v}) }
	}
	if forceHeader || len(direct)>0 {
		// path may be empty for root (not called)
		if path!="" { w.header(path, false) }
	}
	for _,d:=range direct { w.line(d[0].Value+" = "+tomlScalarValue(d[1])) }
	for _,tb:=range tables {
		k:=tb[0].Value; v:=tb[1]
		childPath:=k; if path!="" { childPath=path+"."+k }
		if v.Kind==yaml.MappingNode {
			w.processTable(childPath, v, false)
		} else if isTomlSeqOfMaps(v) {
			for _,el:=range v.Content {
				w.header(childPath, true)
				w.processTableBody(childPath, effectiveNode(el))
			}
		}
	}
}
// processTableBody for array element: header already written, so force direct/table processing without printing its own header
func (w *tomlWriter) processTableBody(path string, m *yaml.Node) {
	var direct [][2]*yaml.Node
	var tables [][2]*yaml.Node
	for i:=0;i+1<len(m.Content);i+=2 {
		k:=m.Content[i]; v:=effectiveNode(m.Content[i+1])
		if isTomlTableValue(v) { tables=append(tables, [2]*yaml.Node{k, v}) } else { direct=append(direct, [2]*yaml.Node{k, v}) }
	}
	for _,d:=range direct { w.line(d[0].Value+" = "+tomlScalarValue(d[1])) }
	for _,tb:=range tables {
		k:=tb[0].Value; v:=tb[1]
		childPath:=k; if path!="" { childPath=path+"."+k }
		if v.Kind==yaml.MappingNode { w.processTable(childPath, v, false) } else if isTomlSeqOfMaps(v) {
			for _,el:=range v.Content { w.header(childPath, true); w.processTableBody(childPath, effectiveNode(el)) }
		}
	}
}
func (w *tomlWriter) processRoot(m *yaml.Node) {
