package main

import (
	"strconv"
	"strings"
)

func joinTomlMultiline(s string) string {
	lines := strings.Split(s, "\n")
	var out []string
	for i := 0; i < len(lines); i++ {
		line := lines[i]
		// detect = """ or = '''
		delim := ""
		idx := -1
		if j := strings.Index(line, `"""`); j >= 0 {
			delim = `"""`; idx = j
		} else if j := strings.Index(line, `'''`); j >= 0 {
			delim = `'''`; idx = j
		}
		if idx < 0 {
			out = append(out, line)
			continue
		}
		rest := line[idx+3:]
		if strings.Contains(rest, delim) {
			// single line triple, leave as is (parseTOMLValue handles it)
			out = append(out, line)
			continue
		}
		var content strings.Builder
		content.WriteString(rest)
		closed := false
		for i+1 < len(lines) {
			i++
			content.WriteString("\n")
			if cidx := strings.Index(lines[i], delim); cidx >= 0 {
				content.WriteString(lines[i][:cidx])
				closed = true
				break
			}
			content.WriteString(lines[i])
		}
		_ = closed
		txt := content.String()
		txt = strings.TrimPrefix(txt, "\n")
		prefix := strings.TrimSpace(line[:idx])
		out = append(out, prefix+" "+strconv.Quote(txt))
	}
	return strings.Join(out, "\n")
}

func stripTomlCommentFromLine(s string) string {
	inD := false
	inS := false
	esc := false
	for i := 0; i < len(s); i++ {
		c := s[i]
		if inD {
			if esc { esc = false } else if c == '\\' { esc = true } else if c == '"' { inD = false }
			continue
		}
		if inS {
			if c == '\'' { inS = false }
			continue
		}
		if c == '"' { inD = true; continue }
		if c == '\'' { inS = true; continue }
		if c == '#' {
			return strings.TrimSpace(s[:i])
		}
	}
	return s
}
