package main

import "strings"

func shEncode(s string) string {
	var sb strings.Builder
	inQuote := false
	for _, r := range s {
		if isShellSafeRune(r) {
			sb.WriteRune(r)
			continue
		}
		if r == '\'' {
			if inQuote {
				sb.WriteString("'\\''")
				// after this sequence we are back in a quote (last ' opens)
				inQuote = true
			} else {
				sb.WriteString("\\'")
			}
			continue
		}
		if !inQuote {
			sb.WriteString("'")
			inQuote = true
		}
		sb.WriteRune(r)
	}
	if inQuote {
		sb.WriteString("'")
	}
	return sb.String()
}
func isShellSafeRune(r rune) bool {
	return (r>='a'&&r<='z')||(r>='A'&&r<='Z')||(r>='0'&&r<='9')|| strings.ContainsRune("_-.,:/@%+=", r)
}
EOF
