import pathlib
p=pathlib.Path("funcs.go"); t=p.read_text()
start=t.find("func funcSortBy(")
end=t.find("func funcMap(", start)
seg=t[start:end]
# Replace the whole funcSortBy with a new implementation using direction handling
new = '''func funcSortBy(ast *AST, ctx *EvalContext, c *Candidate) ([]*Candidate, error) {
	node := effectiveNode(c.Node)
	if node == nil || (node.Kind != yaml.SequenceNode && node.Kind != yaml.MappingNode) {
		return nil, fmt.Errorf("node at path %s is not an array or map (it's a %s)", formatPathBracket(c.Path), nodeTag(node))
	}
	// Determine key args and optional direction (last string literal arg)
	keyArgs := []*AST{}
	direction := ""
	args := ast.Args
	if len(args) >= 2 {
		last := args[len(args)-1]
		isStrLit := false
		var dirVal string
		if last.Kind == AKString && !last.HasInterp { isStrLit = true; dirVal = last.StrVal }
		if last.Kind == AKLiteral && last.Node != nil && last.Node.Tag == "!!str" { isStrLit = true; dirVal = last.Node.Value }
		if isStrLit {
			direction = dirVal
			args = args[:len(args)-1]
		}
	}
	for _, a := range args {
		if a != nil && a.Kind == AKUnion {
			// flatten union leaves
			var walk func(x *AST)
			walk = func(x *AST) { if x != nil && x.Kind == AKUnion { walk(x.L); walk(x.R); return }; keyArgs = append(keyArgs, x) }
			walk(a)
		} else {
			keyArgs = append(keyArgs, a)
		}
	}
	if len(keyArgs)==0 { keyArgs = ast.Args }
	if direction != "" && direction != "asc" && direction != "desc" {
		return []*Candidate{c}, nil
	}
	lessKeys := func(aKeys, bKeys []*yaml.Node) bool {
		for ki := range aKeys {
			if ki >= len(bKeys) { break }
			isLast := ki == len(aKeys)-1
			if isLast && direction == "desc" {
				if sortByLess(bKeys[ki], aKeys[ki]) { return true }
				if sortByLess(aKeys[ki], bKeys[ki]) { return false }
			} else {
				if sortByLess(aKeys[ki], bKeys[ki]) { return true }
				if sortByLess(bKeys[ki], aKeys[ki]) { return false }
			}
		}
		return false
	}
	if node.Kind == yaml.SequenceNode {
		type item struct { el *yaml.Node; keys []*yaml.Node; idx int }
		var items []item
		for i, el := range node.Content {
			elCand := c.child(el, node, i, i)
			var keys []*yaml.Node
			for _, ka := range keyArgs {
